module.exports = {"id":"politics-systematic-content-v2-samples","curriculumVersion":"units-50de00939577","knowledgePackageVersion":"kp1-a6-runtime-77a15fc82abc-lb-715e57f57689","candidateOnly":true,"reviewState":"draft","groups":[{"id":"foundation","title":"核心要义 新时代与两个结合","topicId":"A1","scope":"主题、时代条件与理论来源的联系，不含完整理论发展史","following":"接着理解十个明确","lessonIds":["FOUND-01","FOUND-02","FOUND-03"],"routeId":"thought","connectionToNext":"先明确贯穿主题、时代条件和理论怎样扎根，才能进入这一思想的主体内容“十个明确”。"},{"id":"ten","title":"十个明确","topicId":"A2","scope":"十条的核心含义与职责，固定表述及下属术语可进一步查阅","enumeration":{"id":"ten-clarifications","count":10},"following":"接着理解科学体系：方略与方法","lessonIds":["TEN-01","TEN-02","TEN-03","TEN-04"],"routeId":"thought","connectionToNext":"十条主体内容形成轮廓后，再用十四个坚持、十三个方面成就和六个必须坚持分清方略、成果与方法。"},{"id":"framework","title":"科学体系：方略与方法","topicId":"A2","scope":"四组表述的职责与联系、十四个坚持、六个必须坚持；十三个方面成就只解释职责","following":"接着理解中国式现代化","lessonIds":["SYS-01","SYS-02","SYS-03","SYS-04","SYS-05"],"routeId":"thought","connectionToNext":"主体内容、基本方略和方法论的职责分清后，转入中国式现代化，观察理论怎样解释总任务与实践道路。"},{"id":"modernization","title":"中国式现代化","topicId":"A3","scope":"目标与阶段、五个特色、本质要求和重大原则；战略目标细目保留查阅","following":"接着理解党的领导与人民立场","lessonIds":["MOD-01","MOD-02","MOD-03"],"routeId":"thought","connectionToNext":"中国式现代化的目标、特色和原则明确后，先回到贯穿各领域的领导力量与人民立场。"},{"id":"leadership","title":"党的领导与人民立场","topicId":"A4","scope":"领导地位与制度、人民立场、共同富裕及分配；制度细目保留查阅","routeId":"thought","following":"接着理解高质量发展","lessonIds":["LEADERSHIP-01","LEADERSHIP-02","LEADERSHIP-03"],"connectionToNext":"领导力量和人民立场说明发展为了谁、依靠谁，下一主题继续看高质量发展怎样形成现实条件。"},{"id":"development","title":"高质量发展","topicId":"A5","scope":"新发展阶段、新发展理念、新发展格局、基本经济制度、政府与市场、乡村振兴、区域与城镇化；具体措施与历史材料保留查阅。","following":"接着理解民生：就业 分配与保障","lessonIds":["DEV-01","DEV-02","DEV-03","DEV-04","DEV-05","DEV-06","DEV-07"],"routeId":"thought","connectionToNext":"发展阶段、理念、格局和制度安排搭好后，下一主题转向就业、分配、保障与健康等民生结果。"},{"id":"livelihood","title":"民生：就业 分配与保障","topicId":"A5","scope":"就业、分配、社会保障与健康的基本联系；具体措施保留查阅","routeId":"thought","following":"接着理解教育 科技与人才","lessonIds":["LIVELIHOOD-01","LIVELIHOOD-02"],"connectionToNext":"民生目标需要教育、科技和人才提供长期支撑，下一主题继续理解这三者怎样形成基础能力。"},{"id":"support","title":"教育 科技与人才","topicId":"A5","scope":"基础性战略性支撑、教育目标、科技创新与人才评价；具体政策细目可查阅","routeId":"thought","following":"接着理解全过程人民民主","lessonIds":["SUPPORT-01","SUPPORT-02"],"connectionToNext":"教育、科技和人才说明发展支撑，下一主题转向人民当家作主的制度和参与过程。"},{"id":"democracy","title":"全过程人民民主","topicId":"A6","scope":"根本与基本政治制度、全过程民主及统一战线的核心关系，制度细目可查阅","routeId":"thought","following":"接着理解改革与法治","lessonIds":["DEMOCRACY-01","DEMOCRACY-02","DEMOCRACY-03"],"connectionToNext":"民主制度和参与过程说明人民怎样成为治理主体，下一主题继续理解改革动力与法治保障。"},{"id":"reformlaw","title":"改革与法治","topicId":"A6","scope":"改革目标、法治道路体系与共同推进的联系；历史材料与实施细目可查阅","routeId":"thought","following":"接着理解文化与生态文明","lessonIds":["REFORMLAW-01","REFORMLAW-02","REFORMLAW-03"],"connectionToNext":"改革与法治说明制度怎样完善和运行，下一主题转向文化建设与生态文明两个现代化领域。"},{"id":"cultureeco","title":"文化与生态文明","topicId":"A7","scope":"分别理解文化建设与生态文明，再回看在现代化中的位置，不将二者伪造为因果关系","routeId":"thought","following":"接着理解党的建设与自我革命","lessonIds":["CULTUREECO-01","CULTUREECO-02","CULTUREECO-03","CULTUREECO-04"],"connectionToNext":"文化与生态文明补充现代化的精神和自然维度，下一主题回到党的建设与自我革命这一政治保证。"},{"id":"party","title":"党的建设与自我革命","topicId":"A8","scope":"总要求、各项建设的职责与自我革命联系；九项实践要求的细目保留查阅","routeId":"thought","following":"接着理解总体安全与国防","lessonIds":["PARTY-01","PARTY-02","PARTY-03"],"connectionToNext":"党的建设与自我革命说明长期执政能力怎样保持，下一主题进入总体国家安全和国防保障。"},{"id":"security","title":"总体安全与国防","topicId":"A9","scope":"总体国家安全的结构与风险、强军目标和制度；按现有来源认识目标安排","routeId":"thought","following":"接着理解统一与对外关系","lessonIds":["SECURITY-01","SECURITY-02","SECURITY-03"],"connectionToNext":"安全与国防说明发展所需的底线和保障，下一主题延伸到国家统一与对外关系。"},{"id":"unityforeign","title":"统一与对外关系","topicId":"A9","scope":"一国两制与统一方略、外交关系和人类命运共同体的基本结构；不补写时事进展","routeId":"thought","following":"完成新时代思想篇","lessonIds":["UNITYFOREIGN-01","UNITYFOREIGN-02","UNITYFOREIGN-03"],"connectionToNext":"统一与对外关系补齐国家发展面对的内外关系，到这里可以把新时代思想篇的十四个主题合起来回看。"},{"id":"basics","title":"基本立场与物质意识","topicId":"B1","scope":"马克思主义组成与理论来源、哲学基本问题、物质意识关系；科学社会主义不作独立详细课程","routeId":"principles","following":"接着理解联系 发展与矛盾","lessonIds":["BASICS-01","BASICS-02","BASICS-03","BASICS-04"],"connectionToNext":"物质与意识的基本立场明确后，下一主题用联系、发展和矛盾解释事物怎样变化。"},{"id":"dialectics","title":"联系 发展与矛盾","topicId":"B2","scope":"联系与发展、矛盾分析、内外因、量变质变和辩证否定；每节只解决一个核心问题。","routeId":"principles","following":"接着理解实践 认识与真理","lessonIds":["DIALECTICS-01","DIALECTICS-02","DIALECTICS-03","DIALECTICS-04","DIALECTICS-05","DIALECTICS-06"],"connectionToNext":"辩证法提供理解变化的结构，下一主题继续回答认识怎样从实践产生、发展并接受检验。"},{"id":"cognition","title":"实践 认识与真理","topicId":"B3","scope":"实践认识的作用、认识两次飞跃与真理属性，不替代完整认识论课程","routeId":"principles","following":"接着理解社会与历史","lessonIds":["COGNITION-01","COGNITION-02","COGNITION-03"],"connectionToNext":"认识论说明实践与真理的关系，下一主题把这些观点放进社会结构、历史动力和历史主体中。"},{"id":"history","title":"社会与历史","topicId":"B4","scope":"社会存在意识、两对基本矛盾与人民群众作用；详细学派分类保留查阅","routeId":"principles","following":"接着理解商品 劳动与价值量","lessonIds":["HISTORY-01","HISTORY-02","HISTORY-03","HISTORY-04"],"connectionToNext":"社会历史结构明确后，下一主题进入政治经济学，从商品、劳动和价值量开始。"},{"id":"value","title":"商品 劳动与价值量","topicId":"B5","scope":"商品二因素、劳动二重性及价值量的基本联系，不包括完整政治经济学","following":"接着理解货币：本质与职能","lessonIds":["VALUE-01","VALUE-02","VALUE-03"],"routeId":"principles","connectionToNext":"商品、劳动与价值量的关系建立后，下一主题继续理解货币为什么产生以及怎样发挥职能。"},{"id":"money","title":"货币：本质与职能","topicId":"B5","scope":"货币本质与五种职能的作用、条件和联系","routeId":"principles","following":"接着理解剩余价值：定义与条件","lessonIds":["MONEY-01","MONEY-02"],"connectionToNext":"货币本质与职能明确后，下一主题进入资本和剩余价值的有边界基础认识。"},{"id":"capital","title":"剩余价值：定义与条件","topicId":"B5","scope":"只理解现有定义、两种方法的时间条件及资本分类；劳动力价值前置不足，完整产生机制待补源","routeId":"principles","following":"完成马克思主义基本原理篇","lessonIds":["CAPITAL-01","CAPITAL-02"],"connectionToNext":"剩余价值方法与资本分类读完后，可以把基本立场、辩证法、认识论、历史观和政治经济学基础放回同一篇回看。"}],"routes":[{"id":"thought","title":"新时代思想","summary":"从主题与体系出发，逐步理解现代化与各实践领域","scope":"当前新时代思想篇；十三个方面成就只说明职责，不逐项展开","groupIds":["foundation","ten","framework","modernization","leadership","development","livelihood","support","democracy","reformlaw","cultureeco","party","security","unityforeign"],"conclusion":{"title":"把十四个主题放回新时代思想篇","summary":"你已经从核心主题和科学体系出发，依次理解中国式现代化以及领导、发展、民生、民主、法治、文化生态、党的建设、安全、统一与外交等主题的基本职责和联系。","boundary":"这表示当前48节已读完，不表示已经掌握全部原文、十三个方面成就细目或完整考试范围。"}},{"id":"principles","title":"马克思主义基本原理","summary":"从基本立场到联系变化、认识历史，再理解商品价值","scope":"当前基本原理篇；科学社会主义不作详细课程，剩余价值机制目标限缩","groupIds":["basics","dialectics","cognition","history","value","money","capital"],"conclusion":{"title":"把七个主题放回基本原理篇","summary":"你已经从理论组成和物质意识出发，依次理解辩证法、认识论、历史观以及商品、货币和剩余价值的有边界基础关系。","boundary":"科学社会主义没有展开为独立详细课程；剩余价值完整机制仍受来源缺口限制，读完不表示覆盖完整基本原理或考试范围。"}}],"progressCompatibleVersions":["units-9000f36d759d","units-bb32645a95ce","units-371caff5370a","units-2ed23ba45dd1","units-ca021565e839","units-290c32b9b468","units-5c825f31114a","units-bc66674c4b7a","units-bdc696129d07","units-31f3d2bfcbb3"],"compatibleKnowledgePackageVersions":["kp1-a6-runtime-77a15fc82abc","kp1-a6-runtime-77a15fc82abc-lb-b64d94e4fdc6","kp1-a6-runtime-77a15fc82abc-lb-e8df016ff9df","kp1-a6-runtime-77a15fc82abc-lb-70ddf928322e","kp1-a6-runtime-77a15fc82abc-lb-34417e5ee72e","kp1-a6-runtime-77a15fc82abc-lb-62c369874da5"],"lessons":[{"id":"TEN-01","groupId":"ten","title":"前三条分别回答什么","question":"领导力量、总任务与社会主要矛盾分别说明什么？","objectives":["认识第1至3条的核心表述","分清领导力量、目标任务与社会主要矛盾的不同作用"],"scopeLimit":"本次解释十个明确的第1至3条；下属固定术语不逐一展开，完整表述可查阅。","reflection":{"prompt":"前三条分别说明了什么？社会主要矛盾变化是否意味着基本国情也改变？","answer":"第1条明确党的领导，第2条明确总任务，第3条明确新时代社会主要矛盾并提出以人民为中心等要求。社会主要矛盾变化没有改变我国仍处于并将长期处于社会主义初级阶段的基本国情。","sourceBlockIds":["block:politics-toc-v2-u003:b005","block:politics-toc-v2-u003:b006","block:politics-toc-v2-u003:b007","block:politics-toc-v2-u001:b012"]},"previousLessonId":null,"nextLessonId":"TEN-02","transition":"下一节：布局怎样连接改革与法治","enumerationItems":[{"groupId":"ten-clarifications","ordinal":1,"sourceBlockId":"block:politics-toc-v2-u003:b005"},{"groupId":"ten-clarifications","ordinal":2,"sourceBlockId":"block:politics-toc-v2-u003:b006"},{"groupId":"ten-clarifications","ordinal":3,"sourceBlockId":"block:politics-toc-v2-u003:b007"}],"primaryUnitIds":["politics-toc-v2-u003"],"parts":[{"label":"先知道这组内容的位置","text":"“十个明确”是这一思想的主体内容，集中体现主要观点和基本精神。先读前三条，不是要立刻背出完整清单，而是看清它们分别说明什么。后面的条目将在接下来的小节逐步展开。","sourceBlockIds":["block:politics-toc-v2-u003:b004"],"emphasis":[],"kind":"explanation","id":"TEN-01-body-1"},{"label":"第1条：领导力量","text":"第一条明确，中国特色社会主义最本质的特征、制度的最大优势是中国共产党领导，中国共产党是最高政治领导力量。这一条先把领导力量讲清楚。理解时要保留这一正式对象，不能把它换成某项具体工作的做法。","sourceBlockIds":["block:politics-toc-v2-u003:b005"],"emphasis":[{"part":"text","quote":"中国共产党领导","occurrence":1,"role":"key"}],"kind":"explanation","id":"TEN-01-body-2"},{"label":"第2条：总任务","text":"第二条明确，总任务是实现社会主义现代化和中华民族伟大复兴，并以中国式现代化推进中华民族伟大复兴。“总任务”指向要实现的目标；它与上一条的领导力量处在不同的理解位置。","sourceBlockIds":["block:politics-toc-v2-u003:b006"],"emphasis":[{"part":"text","quote":"社会主义现代化和中华民族伟大复兴","occurrence":1,"role":"key"}],"kind":"explanation","id":"TEN-01-body-3"},{"label":"第3条：社会主要矛盾与人民立场","text":"第三条明确，新时代我国社会主要矛盾是人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾，同时提出坚持以人民为中心、发展全过程人民民主、推动人的全面发展和共同富裕。它让我们认识当前社会主要矛盾，以及与人民需要相关的要求。","sourceBlockIds":["block:politics-toc-v2-u003:b007"],"emphasis":[{"part":"text","quote":"美好生活需要","occurrence":1,"role":"key"},{"part":"text","quote":"不平衡不充分的发展","occurrence":1,"role":"key"}],"kind":"explanation","id":"TEN-01-body-4"},{"label":"注意边界","text":"社会主要矛盾发生变化，没有改变我国仍处于并将长期处于社会主义初级阶段的基本国情。不能把“进入新时代”读成所处历史阶段已经发生同样改变。","sourceBlockIds":["block:politics-toc-v2-u001:b012","block:politics-toc-v2-u001:b015"],"emphasis":[],"kind":"boundary","id":"TEN-01-boundary"},{"label":"本节结论","text":"前三条可以分别从领导力量、总任务、社会主要矛盾与人民立场来理解。这只是帮助阅读的归纳，三条正式表述各有对象，不能互相代替。","sourceBlockIds":["block:politics-toc-v2-u003:b005","block:politics-toc-v2-u003:b006","block:politics-toc-v2-u003:b007"],"emphasis":[],"kind":"recap","id":"TEN-01-recap"}]},{"id":"TEN-02","groupId":"ten","title":"布局怎样连接改革与法治","question":"第4至6条怎样从事业布局进入改革与法治总目标？","objectives":["分清五位一体总体布局与四个全面战略布局","认清改革总目标和依法治国总目标的各自对象"],"scopeLimit":"本次解释第4至6条如何从整体布局进入两个治理总目标；不展开各领域全部措施。","reflection":{"prompt":"两种布局与改革、法治两个总目标怎样连接，又为什么不能混成一组？","answer":"“五位一体”和“四个全面”说明事业布局；改革总目标指向制度完善与治理现代化，依法治国总目标指向法治体系和法治国家。它们在事业推进中相连，但布局和具体总目标层次不同。","sourceBlockIds":["block:politics-toc-v2-u003:b009","block:politics-toc-v2-u003:b010","block:politics-toc-v2-u012:b011"]},"previousLessonId":"TEN-01","nextLessonId":"TEN-03","transition":"下一节：第七条怎样展开经济发展","enumerationItems":[{"groupId":"ten-clarifications","ordinal":4,"sourceBlockId":"block:politics-toc-v2-u003:b008"},{"groupId":"ten-clarifications","ordinal":5,"sourceBlockId":"block:politics-toc-v2-u003:b009"},{"groupId":"ten-clarifications","ordinal":6,"sourceBlockId":"block:politics-toc-v2-u003:b010"}],"primaryUnitIds":["politics-toc-v2-u003"],"parts":[{"label":"第4条：两种布局","text":"第四条明确，“五位一体”总体布局是经济建设、政治建设、文化建设、社会建设、生态文明建设；“四个全面”战略布局是全面建设社会主义现代化国家、全面深化改革、全面依法治国、全面从严治党。先保留两组的名称和内容，再理解它们处于同一事业展开中的不同组织层次。","sourceBlockIds":["block:politics-toc-v2-u003:b008"],"emphasis":[{"part":"text","quote":"五位一体","occurrence":1,"role":"key"},{"part":"text","quote":"四个全面","occurrence":1,"role":"key"}],"kind":"explanation","id":"TEN-02-body-1"},{"label":"第5条：改革总目标","text":"第五条明确，全面深化改革总目标是完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化。这里的重点是制度的完善发展与治理现代化；学习时不能只记“改革”两个字，而漏掉改革所指向的总目标。","sourceBlockIds":["block:politics-toc-v2-u003:b009"],"emphasis":[],"kind":"explanation","id":"TEN-02-body-2"},{"label":"第6条：依法治国总目标","text":"第六条明确，全面推进依法治国总目标是建设中国特色社会主义法治体系、建设社会主义法治国家。它与改革总目标有关联，但表述的具体对象不同，不能用“治理现代化”替换法治体系与法治国家。","sourceBlockIds":["block:politics-toc-v2-u003:b010"],"emphasis":[{"part":"text","quote":"法治体系","occurrence":1,"role":"key"},{"part":"text","quote":"法治国家","occurrence":1,"role":"key"}],"kind":"explanation","id":"TEN-02-body-3"},{"label":"注意边界","text":"改革是社会主义制度的自我完善和发展，不是改变制度的根本性质。改革与法治相辅相成；有联系不意味着两个总目标可以写成同一句话。","sourceBlockIds":["block:politics-toc-v2-u012:b004","block:politics-toc-v2-u012:b008","block:politics-toc-v2-u012:b011","block:politics-toc-v2-u012:b015"],"emphasis":[],"kind":"boundary","id":"TEN-02-boundary"},{"label":"本节结论","text":"第4条帮助看布局，第5条看改革要达到什么目标，第6条看依法治国要达到什么目标。把这三条放在一起，是为了看清各自职责与联系，而不是把布局、目标混成一组清单。","sourceBlockIds":["block:politics-toc-v2-u003:b008","block:politics-toc-v2-u003:b009","block:politics-toc-v2-u003:b010"],"emphasis":[],"kind":"recap","id":"TEN-02-recap"}]},{"id":"TEN-03","groupId":"ten","title":"第七条怎样展开经济发展","question":"经济制度、发展理念与发展格局各在说明什么？","objectives":["看清第7条的主要内容及其连接","区分制度安排、发展理念和发展格局"],"scopeLimit":"本次只解释第7条的结构；具体制度与发展主题在后续小节继续，不展开所有政策措施。","reflection":{"prompt":"为什么不能把新发展理念、新发展格局和基本经济制度当成同一个概念？","answer":"它们分别承担发展思路、战略路径与制度安排等不同职责。第七条将这些内容联系起来，但没有把它们等同；还保留了市场和政府、高质量发展、统筹发展和安全等要求。","sourceBlockIds":["block:politics-toc-v2-u003:b011","block:politics-toc-v2-u007:b022","block:politics-toc-v2-u007:b041","block:politics-toc-v2-u007:b057"]},"previousLessonId":"TEN-02","nextLessonId":"TEN-04","transition":"下一节：强军 外交与党的建设怎样放回整体","enumerationItems":[{"groupId":"ten-clarifications","ordinal":7,"sourceBlockId":"block:politics-toc-v2-u003:b011"}],"primaryUnitIds":["politics-toc-v2-u003"],"parts":[{"label":"先保留完整结构","text":"第七条同时涉及坚持和完善社会主义基本经济制度，使市场在资源配置中起决定性作用、更好发挥政府作用，以及把握新发展阶段、贯彻新发展理念、构建新发展格局、推动高质量发展、统筹发展和安全。它包含多层内容，因此单独安排一个阅读小节。","sourceBlockIds":["block:politics-toc-v2-u003:b011"],"emphasis":[],"kind":"explanation","id":"TEN-03-body-1"},{"label":"制度安排与市场 政府","text":"基本经济制度涉及所有制、分配制度和社会主义市场经济体制。市场和政府的关系是经济体制改革的核心问题：市场在资源配置中起决定性作用，同时更好发挥政府作用。这两部分不能被理解成只能保留一方。","sourceBlockIds":["block:politics-toc-v2-u007:b022","block:politics-toc-v2-u007:b041","block:politics-toc-v2-u007:b042"],"emphasis":[{"part":"text","quote":"决定性作用","occurrence":1,"role":"key"},{"part":"text","quote":"更好发挥政府作用","occurrence":1,"role":"key"}],"kind":"explanation","id":"TEN-03-body-2"},{"label":"阶段 理念与格局","text":"新发展阶段说明当前的历史方位；新发展理念包含创新、协调、绿色、开放、共享，分别回应发展中的不同问题；新发展格局指以国内大循环为主体、国内国际双循环相互促进。把名称拆开理解，才能看清它们为何并列出现。","sourceBlockIds":["block:politics-toc-v2-u007:b005","block:politics-toc-v2-u007:b009","block:politics-toc-v2-u007:b010","block:politics-toc-v2-u007:b011","block:politics-toc-v2-u007:b012","block:politics-toc-v2-u007:b013","block:politics-toc-v2-u007:b015","block:politics-toc-v2-u007:b057"],"emphasis":[],"kind":"explanation","id":"TEN-03-body-3"},{"label":"回到发展主题","text":"高质量发展强调发展从“有没有”转向“好不好”，是体现新发展理念的发展。第七条把制度、市场政府关系、阶段、理念、格局与高质量发展放在同一条中，同时提出统筹发展和安全；本次先认清这些内容的职责，不把每一层都展开成全文。","sourceBlockIds":["block:politics-toc-v2-u007:b002","block:politics-toc-v2-u007:b003","block:politics-toc-v2-u003:b011"],"emphasis":[{"part":"text","quote":"高质量发展","occurrence":1,"role":"key"}],"kind":"explanation","id":"TEN-03-body-4"},{"label":"注意边界","text":"新发展阶段、新发展理念、新发展格局以及基本经济制度不能互相替代；国内大循环为主体也不意味着各地都搞自己的小循环。","sourceBlockIds":["block:politics-toc-v2-u007:b017","block:politics-toc-v2-u007:b057"],"emphasis":[],"kind":"boundary","id":"TEN-03-boundary"},{"label":"本节结论","text":"读第七条时，可以按制度与资源配置、发展方位与思路、发展格局与主题来整理。它们是便于阅读的线索，原条目中的发展和安全等要求仍要保留，不能只剩几个缩略词。","sourceBlockIds":["block:politics-toc-v2-u003:b011","block:politics-toc-v2-u007:b057"],"emphasis":[],"kind":"recap","id":"TEN-03-recap"}]},{"id":"TEN-04","groupId":"ten","title":"强军 外交与党的建设怎样放回整体","question":"第8至10条各讲什么，十条怎样合起来看？","objectives":["理解第8至10条的核心目标与要求","将十条的主要内容放回同一组中回看"],"scopeLimit":"本次收束十条的核心内容；不逐项讲解军事、外交和党建的全部具体措施。","reflection":{"prompt":"第8、9、10条各自的重点是什么？回看十条时，为什么还要保留原序号与正式表述？","answer":"第8条明确强军目标，第9条明确大国外交的方向与重要内容，第10条明确全面从严治党的战略方针和建设要求。分组只是帮助阅读，不能替换十条正式内容或把它们混成其他表述组。","sourceBlockIds":["block:politics-toc-v2-u003:b004","block:politics-toc-v2-u003:b012","block:politics-toc-v2-u003:b013","block:politics-toc-v2-u003:b014","block:politics-toc-v2-u003:b020"]},"previousLessonId":"TEN-03","nextLessonId":null,"transition":"下一主题：科学体系：方略与方法","enumerationItems":[{"groupId":"ten-clarifications","ordinal":8,"sourceBlockId":"block:politics-toc-v2-u003:b012"},{"groupId":"ten-clarifications","ordinal":9,"sourceBlockId":"block:politics-toc-v2-u003:b013"},{"groupId":"ten-clarifications","ordinal":10,"sourceBlockId":"block:politics-toc-v2-u003:b014"}],"primaryUnitIds":["politics-toc-v2-u003"],"parts":[{"label":"第8条：强军目标","text":"第八条明确，党在新时代的强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队，把人民军队建设成为世界一流军队。理解这一条，要同时保留队伍要求与建设目标，不能只留下“强军”一个概括词。","sourceBlockIds":["block:politics-toc-v2-u003:b012"],"emphasis":[{"part":"text","quote":"听党指挥、能打胜仗、作风优良","occurrence":1,"role":"key"}],"kind":"explanation","id":"TEN-04-body-1"},{"label":"第9条：外交的服务方向","text":"第九条明确，中国特色大国外交要服务民族复兴、促进人类进步，推动建设新型国际关系，推动构建人类命运共同体。它说明外交的方向与重要内容，不是上一条军事建设目标的另一种说法。","sourceBlockIds":["block:politics-toc-v2-u003:b013"],"emphasis":[{"part":"text","quote":"服务民族复兴、促进人类进步","occurrence":1,"role":"key"}],"kind":"explanation","id":"TEN-04-body-2"},{"label":"第10条：全面从严治党","text":"第十条明确全面从严治党的战略方针，提出新时代党的建设总要求，全面推进党的政治、思想、组织、作风、纪律建设，把制度建设贯穿其中，深入推进反腐败斗争，落实管党治党政治责任，并以伟大自我革命引领伟大社会革命。这一条要保留建设内容、责任与要求。","sourceBlockIds":["block:politics-toc-v2-u003:b014"],"emphasis":[{"part":"text","quote":"全面从严治党","occurrence":1,"role":"key"}],"kind":"explanation","id":"TEN-04-body-3"},{"label":"十条放回一起","text":"回看十条：第1至3条涉及领导力量、总任务、社会主要矛盾和人民立场；第4至6条涉及布局、改革与法治；第7条展开经济发展；第8至10条涉及强军、外交与全面从严治党。这种分段只是阅读线索，十条共同构成这一思想体系的主体内容。","sourceBlockIds":["block:politics-toc-v2-u003:b004","block:politics-toc-v2-u003:b005","block:politics-toc-v2-u003:b006","block:politics-toc-v2-u003:b007","block:politics-toc-v2-u003:b008","block:politics-toc-v2-u003:b009","block:politics-toc-v2-u003:b010","block:politics-toc-v2-u003:b011","block:politics-toc-v2-u003:b012","block:politics-toc-v2-u003:b013","block:politics-toc-v2-u003:b014"],"emphasis":[],"kind":"explanation","id":"TEN-04-body-4"},{"label":"注意边界","text":"十个明确侧重理论层面的核心内容，十四个坚持侧重基本方略，六个必须坚持侧重世界观和方法论。这次已经分段认识十条，不表示已经读完这几组内容，也不表示已掌握各领域全部细节。","sourceBlockIds":["block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b018","block:politics-toc-v2-u003:b020"],"emphasis":[],"kind":"boundary","id":"TEN-04-boundary"},{"label":"本主题小结","text":"现在可以回到最初的问题：十个明确不是十个互不相干的名称，而是包含主要观点和基本精神的一组主体内容。能按各条说明其主要职责，再对照正式表述查阅，就是这一组学习所支持的理解目标。","sourceBlockIds":["block:politics-toc-v2-u003:b004"],"emphasis":[],"kind":"recap","id":"TEN-04-recap"}]},{"id":"VALUE-01","groupId":"value","title":"商品为什么有两个方面","question":"使用价值与价值分别说明什么，为什么要放在一起理解？","objectives":["区分商品、使用价值与价值","理解二因素的联系和商品成立的必要边界"],"scopeLimit":"本节只解释商品及其使用价值、价值两个因素；劳动怎样与二因素相连留到下一节。","reflection":{"prompt":"为什么“有用的物品”不能直接等同于商品？","answer":"商品必须是用于交换、能满足需要的劳动产品。“有用”只说明使用价值；判断商品还需保留劳动产品与用于交换等条件。","sourceBlockIds":["block:politics-toc-v2-u033:b002","block:politics-toc-v2-u033:b014"]},"previousLessonId":null,"nextLessonId":"VALUE-02","transition":"下一节：同一劳动为什么有两个方面","primaryUnitIds":["politics-toc-v2-u033"],"parts":[{"label":"先判断是不是商品","text":"商品是用来交换、能满足人的某种需要的劳动产品。这个定义同时保留劳动产品、用于交换和满足需要，不能只看“有用”就判断它一定是商品。","sourceBlockIds":["block:politics-toc-v2-u033:b002","block:politics-toc-v2-u033:b014"],"emphasis":[{"part":"text","quote":"用于交换","occurrence":1,"role":"key"}],"kind":"explanation","id":"VALUE-01-body-1"},{"label":"使用价值：说明有用性","text":"使用价值是商品能够满足某种需要的属性，是商品的自然属性。同一商品可以有不同的使用价值，不同商品也可以有同一种使用价值。学习这一面，关注它能满足什么需要。","sourceBlockIds":["block:politics-toc-v2-u033:b005","block:politics-toc-v2-u033:b006","block:politics-toc-v2-u033:b007"],"emphasis":[{"part":"text","quote":"使用价值","occurrence":1,"role":"key"}],"kind":"explanation","id":"VALUE-01-body-2"},{"label":"价值：说明共同的劳动基础","text":"价值是凝结在商品中无差别的一般人类劳动，是商品的社会属性。使用价值不同的商品能够交换，正文给出的共同基础是它们都具有价值，都耗费了人类一定的体力和脑力。","sourceBlockIds":["block:politics-toc-v2-u033:b009","block:politics-toc-v2-u033:b010","block:politics-toc-v2-u033:b011"],"emphasis":[{"part":"text","quote":"价值","occurrence":1,"role":"key"}],"kind":"explanation","id":"VALUE-01-body-3"},{"label":"两方面怎样相连","text":"商品必须同时具有使用价值和价值，使用价值是价值的物质承担者，价值通过使用价值表现出来。这里讲的是同一商品的两个方面，不能把它们拆成两种彼此无关的商品。","sourceBlockIds":["block:politics-toc-v2-u033:b003","block:politics-toc-v2-u033:b012"],"emphasis":[],"kind":"explanation","id":"VALUE-01-body-4"},{"label":"注意边界","text":"有使用价值的物品不一定是商品。在商品交换中，对同一商品所有者来说，使用价值和价值二者不可兼得；不要把二因素统一于商品，误解成交换时二者都能保有。","sourceBlockIds":["block:politics-toc-v2-u033:b013","block:politics-toc-v2-u033:b014"],"emphasis":[],"kind":"boundary","id":"VALUE-01-boundary"},{"label":"本节结论","text":"先用商品定义确定对象，再分别看有用性与价值，最后保留二者在商品中的联系。接下来需要解释的是：同一劳动过程怎样与这两个方面相连。","sourceBlockIds":["block:politics-toc-v2-u033:b002","block:politics-toc-v2-u033:b003","block:politics-toc-v2-u033:b005","block:politics-toc-v2-u033:b009","block:politics-toc-v2-u033:b012","block:politics-toc-v2-u034:b005","block:politics-toc-v2-u034:b006"],"emphasis":[],"kind":"recap","id":"VALUE-01-recap"}]},{"id":"VALUE-02","groupId":"value","title":"同一劳动为什么有两个方面","question":"具体劳动与抽象劳动怎样对应商品的二因素？","objectives":["分清具体劳动与抽象劳动的观察角度","理解同一劳动过程与使用价值、价值的联系"],"scopeLimit":"本次解释劳动二重性及其与商品二因素的联系；不进入价值量变化计算。","reflection":{"prompt":"具体劳动与抽象劳动为什么不是两次劳动？它们分别与商品的哪一面相连？","answer":"二者是同一劳动过程的两个方面。具体劳动保留具体形式，生产使用价值；抽象劳动撇开具体形式，其凝结形成价值。","sourceBlockIds":["block:politics-toc-v2-u034:b003","block:politics-toc-v2-u034:b004","block:politics-toc-v2-u034:b005","block:politics-toc-v2-u034:b006","block:politics-toc-v2-u034:b007"]},"previousLessonId":"VALUE-01","nextLessonId":"VALUE-03","transition":"下一节：商品价值量由什么决定","primaryUnitIds":["politics-toc-v2-u034"],"parts":[{"label":"从上一小节接过问题","text":"商品既有使用价值，也有价值。劳动二重性用于进一步说明：生产商品的劳动既是具体劳动，又是抽象劳动；不是先做完一种劳动，再另外做第二种劳动。","sourceBlockIds":["block:politics-toc-v2-u033:b003","block:politics-toc-v2-u034:b002","block:politics-toc-v2-u034:b005"],"emphasis":[],"kind":"explanation","id":"VALUE-02-body-1"},{"label":"具体劳动：保留具体形式","text":"具体劳动是人们在一定具体形式下进行的劳动。它反映人与自然的关系，生产出各种各样的使用价值。这里保留劳动的具体形式，才能理解不同的有用劳动怎样产生不同的使用价值。","sourceBlockIds":["block:politics-toc-v2-u034:b003","block:politics-toc-v2-u034:b006"],"emphasis":[{"part":"text","quote":"具体劳动","occurrence":1,"role":"key"},{"part":"text","quote":"使用价值","occurrence":1,"role":"key"}],"kind":"explanation","id":"VALUE-02-body-2"},{"label":"抽象劳动：撇开具体形式","text":"抽象劳动是撇开具体形式的无差别人类劳动，是人的体力和脑力的消耗。它体现人与人的关系，其凝结形成商品价值，是形成商品价值的唯一源泉。这里的“抽象”表达观察角度，不是另一次独立劳动。","sourceBlockIds":["block:politics-toc-v2-u034:b004","block:politics-toc-v2-u034:b005","block:politics-toc-v2-u034:b006"],"emphasis":[{"part":"text","quote":"抽象劳动","occurrence":1,"role":"key"},{"part":"text","quote":"商品价值","occurrence":1,"role":"key"}],"kind":"explanation","id":"VALUE-02-body-3"},{"label":"注意边界","text":"具体劳动和抽象劳动是商品生产者同一劳动过程中不可分割的两个方面，不能理解成两次劳动或两种彼此独立的劳动。","sourceBlockIds":["block:politics-toc-v2-u034:b005","block:politics-toc-v2-u034:b007"],"emphasis":[],"kind":"boundary","id":"VALUE-02-boundary"},{"label":"本节结论","text":"商品这一侧看使用价值与价值，劳动这一侧看具体劳动与抽象劳动。具体劳动生产使用价值，抽象劳动凝结形成价值。","sourceBlockIds":["block:politics-toc-v2-u034:b006","block:politics-toc-v2-u035:b003","block:politics-toc-v2-u035:b004"],"emphasis":[],"kind":"recap","id":"VALUE-02-recap"}]},{"id":"VALUE-03","groupId":"value","title":"商品价值量由什么决定","question":"为什么不能用某个生产者花的时间直接决定商品价值量？","objectives":["理解社会必要劳动时间而非个别劳动时间决定价值量","区分单位价值量、生产率与价格变化的基本层次"],"scopeLimit":"本次理解决定因素和基本关系，不做数值计算，也不展开货币与剩余价值。","reflection":{"prompt":"某个生产者做得更慢，能否据此说商品价值量必然更大？","answer":"不能。商品价值量由社会必要劳动时间决定，不直接取决于个别劳动时间。比较生产率变化时，还要区分社会与个别、单位价值量与价值总量。","sourceBlockIds":["block:politics-toc-v2-u035:b004","block:politics-toc-v2-u035:b005","block:politics-toc-v2-u035:b012"]},"previousLessonId":"VALUE-02","nextLessonId":null,"transition":"下一主题：货币：本质与职能","primaryUnitIds":["politics-toc-v2-u035"],"parts":[{"label":"从价值到价值量","text":"上一小节认识了价值的劳动基础；现在问这种价值的大小。商品价值量由社会必要劳动时间决定，而不是由某个生产者实际花费的个别劳动时间直接决定。","sourceBlockIds":["block:politics-toc-v2-u035:b003","block:politics-toc-v2-u035:b004"],"emphasis":[{"part":"text","quote":"社会必要劳动时间","occurrence":1,"role":"key"}],"kind":"explanation","id":"VALUE-03-body-1"},{"label":"什么叫社会必要","text":"社会必要劳动时间，是在现有社会正常生产条件下，在社会平均劳动熟练程度和劳动强度下，生产某种商品所需要的劳动时间。理解时要同时保留社会正常条件与社会平均程度，不能把“必要”读成个人觉得必需多久。","sourceBlockIds":["block:politics-toc-v2-u035:b005"],"emphasis":[],"kind":"explanation","id":"VALUE-03-body-2"},{"label":"生产率与单位价值量","text":"劳动生产率表示生产使用价值的效率。单位商品价值量与所包含的社会必要劳动时间成正比，与生产该商品的社会劳动生产率成反比。比较时先说明是在谈单位商品，还是一定数量商品的价值总量。","sourceBlockIds":["block:politics-toc-v2-u035:b006","block:politics-toc-v2-u035:b007","block:politics-toc-v2-u035:b012"],"emphasis":[{"part":"text","quote":"单位商品价值量","occurrence":1,"role":"key"}],"kind":"explanation","id":"VALUE-03-body-3"},{"label":"再区分价值与价格","text":"价值规律要求商品交换以价值量为基础，按照等价交换原则进行。价格以价值为基础并围绕价值上下波动；看到一次价格变化，不能直接跳过价值量的决定因素，只用个别生产者的耗时来解释。","sourceBlockIds":["block:politics-toc-v2-u035:b004","block:politics-toc-v2-u035:b009","block:politics-toc-v2-u035:b010"],"emphasis":[],"kind":"explanation","id":"VALUE-03-body-4"},{"label":"注意边界","text":"个别劳动生产率变化会影响生产者收益，但不直接改变社会价值量；商品价值总量还取决于商品数量。社会劳动生产率与个别劳动生产率不能混为一谈。","sourceBlockIds":["block:politics-toc-v2-u035:b012"],"emphasis":[],"kind":"boundary","id":"VALUE-03-boundary"},{"label":"本主题小结","text":"这组三个小节依次认识了商品的二因素、劳动的两个方面，以及价值量的决定因素。先把对象与关系讲清，再区分单位量、总量与价格，能够减少把不同问题混到一起的误解。","sourceBlockIds":["block:politics-toc-v2-u033:b003","block:politics-toc-v2-u034:b005","block:politics-toc-v2-u034:b006","block:politics-toc-v2-u035:b003","block:politics-toc-v2-u035:b004","block:politics-toc-v2-u035:b010","block:politics-toc-v2-u035:b012"],"emphasis":[],"kind":"recap","id":"VALUE-03-recap"}]},{"id":"DEV-01","groupId":"development","title":"发展阶段与发展质量","question":"新发展阶段和高质量发展分别在说明什么？","objectives":["分清历史方位与发展质量","保留新发展阶段与社会主义初级阶段的关系"],"scopeLimit":"本节只解释新发展阶段与高质量发展的关系；发展理念留到下一节。","reflection":{"prompt":"新发展阶段与高质量发展能否互相替代？","answer":"不能。新发展阶段说明历史方位，高质量发展说明发展主题与质量要求；新发展阶段仍是社会主义初级阶段历史进程中的重要阶段。","sourceBlockIds":["block:politics-toc-v2-u007:b002","block:politics-toc-v2-u007:b003","block:politics-toc-v2-u007:b005","block:politics-toc-v2-u007:b007","block:politics-toc-v2-u007:b057"]},"previousLessonId":null,"nextLessonId":"DEV-02","transition":"下一节：五个发展理念分别回应什么","primaryUnitIds":["politics-toc-v2-u007"],"parts":[{"label":"先确定发展主题","text":"高质量发展是全面建设社会主义现代化国家的首要任务，是我国经济社会发展的主题。它强调能够很好满足人民日益增长的美好生活需要的发展，是体现新发展理念的发展。","sourceBlockIds":["block:politics-toc-v2-u007:b002","block:politics-toc-v2-u007:b003"],"emphasis":[{"part":"text","quote":"高质量发展","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEV-01-body-1"},{"label":"新发展阶段：说明历史方位","text":"新发展阶段是全面建成小康社会、实现第一个百年奋斗目标之后，全面建设社会主义现代化国家、向第二个百年奋斗目标进军的重要阶段。正文也将它表述为从站起来、富起来到强起来历史性跨越的新阶段。","sourceBlockIds":["block:politics-toc-v2-u007:b005","block:politics-toc-v2-u007:b006"],"emphasis":[],"kind":"explanation","id":"DEV-01-body-2"},{"label":"质量：从有没有转向好不好","text":"高质量发展从“有没有”转向“好不好”。其内涵体现创新、协调、绿色、开放、共享等新发展理念。因此，“阶段”帮助定位发展所处位置，“质量”则帮助把握对发展的要求。","sourceBlockIds":["block:politics-toc-v2-u007:b003","block:politics-toc-v2-u007:b057"],"emphasis":[{"part":"text","quote":"有没有","occurrence":1,"role":"key"},{"part":"text","quote":"好不好","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEV-01-body-3"},{"label":"注意边界","text":"新发展阶段是社会主义初级阶段历史进程中的一个重要阶段。认识新的发展方位，不等于原来的基本国情已经改变。","sourceBlockIds":["block:politics-toc-v2-u007:b007","block:politics-toc-v2-u001:b012"],"emphasis":[],"kind":"boundary","id":"DEV-01-boundary"},{"label":"本节结论","text":"先认识所处阶段，再把握发展质量要求。它们有关联但不能互换；接下来用五个发展理念，进一步看发展中的不同问题。","sourceBlockIds":["block:politics-toc-v2-u007:b003","block:politics-toc-v2-u007:b005","block:politics-toc-v2-u007:b009","block:politics-toc-v2-u007:b010","block:politics-toc-v2-u007:b011","block:politics-toc-v2-u007:b012","block:politics-toc-v2-u007:b013","block:politics-toc-v2-u007:b057"],"emphasis":[],"kind":"recap","id":"DEV-01-recap"}]},{"id":"DEV-02","groupId":"development","title":"五个发展理念分别回应什么","question":"创新 协调 绿色 开放 共享怎样一起理解？","objectives":["说清五个理念各自回应的问题","将五个理念放回高质量发展的内涵"],"scopeLimit":"认识各理念的职责，不展开对应领域的全部政策。","reflection":{"prompt":"创新和协调分别回应什么问题？为什么还要把五个理念一起回看？","answer":"创新回应发展动力，协调回应发展不平衡。五个理念分别面对不同问题，共同构成高质量发展的内涵；理解整体时不能只保留其中一个方面。","sourceBlockIds":["block:politics-toc-v2-u007:b003","block:politics-toc-v2-u007:b009","block:politics-toc-v2-u007:b010","block:politics-toc-v2-u007:b011","block:politics-toc-v2-u007:b012","block:politics-toc-v2-u007:b013"]},"previousLessonId":"DEV-01","nextLessonId":"DEV-03","transition":"下一节：新发展格局怎样理解","primaryUnitIds":["politics-toc-v2-u007"],"parts":[{"label":"创新与协调","text":"创新是引领发展的第一动力，解决发展动力问题；协调是持续健康发展的内在要求，解决发展不平衡问题。前者与后者不是同一句要求，学习时先明确各自面对的问题。","sourceBlockIds":["block:politics-toc-v2-u007:b009","block:politics-toc-v2-u007:b010"],"emphasis":[{"part":"text","quote":"发展动力","occurrence":1,"role":"key"},{"part":"text","quote":"发展不平衡","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEV-02-body-1"},{"label":"绿色与开放","text":"绿色是永续发展的必要条件，解决人与自然和谐共生问题；开放是国家繁荣发展的必由之路，解决发展内外联动问题。它们同属发展理念，但观察的关系不同，不能只把它们当作抽象口号记在一起。","sourceBlockIds":["block:politics-toc-v2-u007:b011","block:politics-toc-v2-u007:b012"],"emphasis":[{"part":"text","quote":"人与自然和谐共生","occurrence":1,"role":"key"},{"part":"text","quote":"内外联动","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEV-02-body-2"},{"label":"共享与整体","text":"共享是中国特色社会主义的本质要求，解决社会公平正义问题。将五个理念放回高质量发展的定义，可以看到创新、协调、绿色、开放、共享共同构成其内涵，而不是仅用某个单一方面代替发展质量。","sourceBlockIds":["block:politics-toc-v2-u007:b003","block:politics-toc-v2-u007:b013"],"emphasis":[{"part":"text","quote":"社会公平正义","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEV-02-body-3"},{"label":"注意边界","text":"五个理念共同用于理解发展思路，不等于已经解释了新发展阶段、新发展格局或基本经济制度。名称相近，职责仍应分开。","sourceBlockIds":["block:politics-toc-v2-u007:b057"],"emphasis":[],"kind":"boundary","id":"DEV-02-boundary"},{"label":"本节结论","text":"用“动力、不平衡、人与自然、内外联动、公平正义”辨认各理念面对的问题，同时保留各理念的正式名称与表述。","sourceBlockIds":["block:politics-toc-v2-u007:b009","block:politics-toc-v2-u007:b010","block:politics-toc-v2-u007:b011","block:politics-toc-v2-u007:b012","block:politics-toc-v2-u007:b013","block:politics-toc-v2-u007:b057"],"emphasis":[],"kind":"recap","id":"DEV-02-recap"}]},{"id":"DEV-03","groupId":"development","title":"新发展格局怎样理解","question":"国内大循环与国内国际双循环是什么关系？","objectives":["保留主体与相互促进的完整关系","认识新发展格局的基础与关键"],"scopeLimit":"本次解释格局及必要边界，不展开具体产业与贸易措施。","reflection":{"prompt":"理解新发展格局时，为什么不能只记“国内循环”四个字？","answer":"正式表述同时包括国内大循环为主体、国内国际双循环相互促进；还涉及全国统一大市场、循环畅通与高水平自立自强等内容，不能理解成各地自我小循环。","sourceBlockIds":["block:politics-toc-v2-u007:b015","block:politics-toc-v2-u007:b017","block:politics-toc-v2-u007:b018","block:politics-toc-v2-u007:b019","block:politics-toc-v2-u007:b020"]},"previousLessonId":"DEV-02","nextLessonId":"DEV-04","transition":"下一节：基本经济制度包含哪些层次","primaryUnitIds":["politics-toc-v2-u007"],"parts":[{"label":"保留完整关系","text":"新发展格局是以国内大循环为主体、国内国际双循环相互促进。理解时要同时保留“主体”与“相互促进”，不能只剩国内或国际其中一侧。它与上一小节的发展理念有关联，但不是同一种概念。","sourceBlockIds":["block:politics-toc-v2-u007:b015","block:politics-toc-v2-u007:b057"],"emphasis":[{"part":"text","quote":"国内大循环为主体","occurrence":1,"role":"key"},{"part":"text","quote":"相互促进","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEV-03-body-1"},{"label":"基础与关键","text":"全国统一大市场是构建新发展格局的基础支撑和内在要求，关键在于经济循环畅通无阻。这两句帮助进一步认识：构建格局不仅是给循环起名称，还涉及市场与经济循环的条件。","sourceBlockIds":["block:politics-toc-v2-u007:b017","block:politics-toc-v2-u007:b018","block:politics-toc-v2-u007:b019"],"emphasis":[],"kind":"explanation","id":"DEV-03-body-2"},{"label":"主动权与自立自强","text":"构建新发展格局是把握发展主动权的先手棋，不是被迫之举和权宜之计；其最本质特征是实现高水平的自立自强。学习时先保留这些定位，再按需要进入具体领域查阅。","sourceBlockIds":["block:politics-toc-v2-u007:b016","block:politics-toc-v2-u007:b020"],"emphasis":[],"kind":"explanation","id":"DEV-03-body-3"},{"label":"注意边界","text":"国内大循环为主体，不是各地都搞自我小循环。全国统一大市场的要求与地方自我封闭式循环不能混同。","sourceBlockIds":["block:politics-toc-v2-u007:b017","block:politics-toc-v2-u007:b018"],"emphasis":[],"kind":"boundary","id":"DEV-03-boundary"},{"label":"本节结论","text":"现在可以区分：阶段说明历史方位，理念说明发展思路，格局说明战略路径。接下来转向制度安排，继续认识它与这些内容的不同职责。","sourceBlockIds":["block:politics-toc-v2-u007:b057"],"emphasis":[],"kind":"recap","id":"DEV-03-recap"}]},{"id":"DEV-04","groupId":"development","title":"基本经济制度包含哪些层次","question":"所有制 分配制度与市场经济体制怎样区分？","objectives":["认识基本经济制度的三层内容","分清公有制主体与国有经济主导"],"scopeLimit":"本节只解释基本经济制度与所有制、分配制度的核心内容；政府和市场关系留到下一节。","reflection":{"prompt":"公有制主体地位与国有经济主导作用为什么不是同一个概念？","answer":"公有制范围包括国有、集体和混合所有制中的公有成分；国有经济是其中一部分。主体与主导分别说明公有制的地位、国有经济对国民经济的控制力，不能将对象互换。","sourceBlockIds":["block:politics-toc-v2-u007:b025","block:politics-toc-v2-u007:b026","block:politics-toc-v2-u007:b028"]},"previousLessonId":"DEV-03","nextLessonId":"DEV-05","transition":"下一节：政府与市场怎样共同发挥作用","primaryUnitIds":["politics-toc-v2-u007"],"parts":[{"label":"先看完整结构","text":"社会主义基本经济制度包括公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，以及社会主义市场经济体制。它们分别涉及所有制、分配和市场经济体制，不能只记其中一层就认为已说全。","sourceBlockIds":["block:politics-toc-v2-u007:b022"],"emphasis":[{"part":"text","quote":"所有制","occurrence":1,"role":"key"},{"part":"text","quote":"分配","occurrence":1,"role":"key"},{"part":"text","quote":"市场经济体制","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEV-04-body-1"},{"label":"公有制与非公有制","text":"公有制经济包括国有经济、集体经济，以及混合所有制中的国有成分和集体成分；非公有制包括个体、私营等经济。两者都是社会主义市场经济的重要组成部分，也是经济社会发展的重要基础。正文同时要求巩固和发展公有制，鼓励、支持、引导非公有制发展。","sourceBlockIds":["block:politics-toc-v2-u007:b023","block:politics-toc-v2-u007:b025","block:politics-toc-v2-u007:b031","block:politics-toc-v2-u007:b032"],"emphasis":[],"kind":"explanation","id":"DEV-04-body-2"},{"label":"主体与主导","text":"公有制主体地位与国有经济主导作用不能混为一谈。前者包括公有资产在社会总资产中占优势等体现；后者集中体现为国有经济对国民经济的控制力。这是在不同对象上说明各自地位。","sourceBlockIds":["block:politics-toc-v2-u007:b026","block:politics-toc-v2-u007:b028"],"emphasis":[],"kind":"explanation","id":"DEV-04-body-3"},{"label":"分配制度","text":"在社会主义初级阶段，所有制决定分配制度坚持按劳分配为主体、多种分配方式并存。按生产要素分配还涉及劳动、资本、管理和知识产权等要素；这些内容用于进一步认识多种分配方式，而不替代按劳分配的主体地位。","sourceBlockIds":["block:politics-toc-v2-u007:b034","block:politics-toc-v2-u007:b036","block:politics-toc-v2-u007:b037","block:politics-toc-v2-u007:b038"],"emphasis":[],"kind":"explanation","id":"DEV-04-body-4"},{"label":"注意边界","text":"公有制不只等于国有经济；多种分配方式并存，也不能省略按劳分配为主体。制度名称中的对象与层次需要同时保留。","sourceBlockIds":["block:politics-toc-v2-u007:b022","block:politics-toc-v2-u007:b025","block:politics-toc-v2-u007:b034"],"emphasis":[],"kind":"boundary","id":"DEV-04-boundary"},{"label":"本节结论","text":"社会主义基本经济制度包括所有制、分配制度和社会主义市场经济体制三方面内容，各自回答不同层次的问题。","sourceBlockIds":["block:politics-toc-v2-u007:b022","block:politics-toc-v2-u007:b041"],"emphasis":[],"kind":"recap","id":"DEV-04-recap"}]},{"id":"DEV-05","groupId":"development","title":"政府与市场怎样共同发挥作用","question":"市场决定资源配置与更好发挥政府作用是否矛盾？","objectives":["保留政府与市场关系的完整要求","将资源配置问题放回基本经济制度"],"scopeLimit":"解释现有正文的基本关系，不推导某项具体政策应采取什么措施。","reflection":{"prompt":"为什么不能把市场和政府的关系读成二选一？","answer":"正文同时要求市场在资源配置中起决定性作用、更好发挥政府作用，并推动有效市场和有为政府更好结合。两方面共同构成需要理解的要求。","sourceBlockIds":["block:politics-toc-v2-u007:b041","block:politics-toc-v2-u007:b042"]},"previousLessonId":"DEV-04","nextLessonId":"DEV-06","transition":"下一节：乡村振兴怎样组织其目标与要求","primaryUnitIds":["politics-toc-v2-u007"],"parts":[{"label":"在制度结构中定位","text":"上一小节认识了基本经济制度的三层内容，这次只聚焦社会主义市场经济体制。正文将处理好政府与市场的关系作为经济体制改革的核心问题。先明确这一问题的位置，再看两方面怎样表述。","sourceBlockIds":["block:politics-toc-v2-u007:b022","block:politics-toc-v2-u007:b041"],"emphasis":[],"kind":"explanation","id":"DEV-05-body-1"},{"label":"市场的决定性作用","text":"市场在资源配置中起决定性作用。这里需要保留“资源配置”这个对象，不能把“决定性作用”泛化成市场承担所有治理职责，也不能把它写成对所有制度层面的同一种判断。","sourceBlockIds":["block:politics-toc-v2-u007:b041"],"emphasis":[],"kind":"explanation","id":"DEV-05-body-2"},{"label":"更好发挥政府作用","text":"同一要求还包括更好发挥政府作用，并推动有效市场和有为政府更好结合。正文用“看不见的手”和“看得见的手”帮助理解两方面共同发挥作用，而不是把两者安排成只能选择其一。","sourceBlockIds":["block:politics-toc-v2-u007:b041","block:politics-toc-v2-u007:b042"],"emphasis":[{"part":"text","quote":"有效市场","occurrence":1,"role":"key"},{"part":"text","quote":"有为政府","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEV-05-body-3"},{"label":"注意边界","text":"学习这一关系时，默认内容只解释现有正式要求。它不等于为任一具体行业、市场行为或现实政策给出同一种现成处理方案；具体问题还需要相应材料。","sourceBlockIds":["block:politics-toc-v2-u007:b041","block:politics-toc-v2-u007:b042"],"emphasis":[],"kind":"boundary","id":"DEV-05-boundary"},{"label":"本节结论","text":"把市场和政府都放回社会主义市场经济体制，保留决定性作用的对象与更好结合的要求。接下来进入现代化经济体系中的实际领域，先从乡村振兴读起。","sourceBlockIds":["block:politics-toc-v2-u007:b022","block:politics-toc-v2-u007:b041","block:politics-toc-v2-u007:b042","block:politics-toc-v2-u007:b043","block:politics-toc-v2-u007:b044"],"emphasis":[],"kind":"recap","id":"DEV-05-recap"}]},{"id":"DEV-06","groupId":"development","title":"乡村振兴怎样组织其目标与要求","question":"乡村振兴的目标、方针、要求、保障和任务怎样构成一套结构？","objectives":["分清乡村振兴中不同层次的目标与要求","认识粮食和重要农产品稳定安全供给的位置"],"scopeLimit":"只解释现有乡村振兴材料的结构，不展开具体地区方案与政策细则。","reflection":{"prompt":"为什么乡村振兴要把目标、方针、要求、保障和任务分层理解？","answer":"它们分别回答要达到什么、优先怎么安排、建设成什么样、靠什么制度支撑和首先抓什么。分层后才能把农业农村现代化与粮食供给安全放入同一结构，又不把各层表述互换。","sourceBlockIds":["block:politics-toc-v2-u007:b049","block:politics-toc-v2-u007:b050"]},"previousLessonId":"DEV-05","nextLessonId":"DEV-07","transition":"下一节：区域战略与城镇化怎样区分","primaryUnitIds":["politics-toc-v2-u007"],"parts":[{"label":"先看它在本篇中的位置","text":"建设现代化经济体系是推动高质量发展的必然要求。正文在这一部分先展开全面推进乡村振兴：始终把解决好“三农”问题作为全党工作重中之重，农业强国是社会主义现代化强国的根基。","sourceBlockIds":["block:politics-toc-v2-u007:b043","block:politics-toc-v2-u007:b044","block:politics-toc-v2-u007:b045","block:politics-toc-v2-u007:b046"],"emphasis":[],"kind":"explanation","id":"DEV-06-body-1"},{"label":"目标与方针","text":"实施乡村振兴战略是新时代做好“三农”工作的总抓手。农业农村现代化是总目标，坚持农业农村优先发展是总方针；两者分别说明要达到什么与应怎样安排优先次序，不能互换名称。","sourceBlockIds":["block:politics-toc-v2-u007:b047","block:politics-toc-v2-u007:b049"],"emphasis":[{"part":"text","quote":"农业农村现代化","occurrence":1,"role":"key"},{"part":"text","quote":"农业农村优先发展","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEV-06-body-2"},{"label":"内容与要求","text":"乡村振兴包括产业、人才、文化、生态、组织振兴。总要求是产业兴旺、生态宜居、乡风文明、治理有效、生活富裕；建立健全城乡融合发展体制机制和政策体系是制度保障。先分别认清这几组内容，再把它们放在同一结构中看。","sourceBlockIds":["block:politics-toc-v2-u007:b048","block:politics-toc-v2-u007:b049"],"emphasis":[],"kind":"explanation","id":"DEV-06-body-3"},{"label":"供给安全的任务","text":"实施乡村振兴战略，必须把确保重要农产品特别是粮食供给作为首要任务；保障粮食和重要农产品稳定安全供给，是建设农业强国的头等大事。它有明确任务位置，不应被一般性的“发展农业”概括所替代。","sourceBlockIds":["block:politics-toc-v2-u007:b050","block:politics-toc-v2-u007:b051"],"emphasis":[],"kind":"explanation","id":"DEV-06-body-4"},{"label":"注意边界","text":"总目标、总方针、总要求、制度保障与首要任务是不同的表述位置。学习时可以一起整理，但不能把“农业农村优先发展”写成总目标，也不能漏掉粮食供给安全。","sourceBlockIds":["block:politics-toc-v2-u007:b049","block:politics-toc-v2-u007:b050","block:politics-toc-v2-u007:b051"],"emphasis":[],"kind":"boundary","id":"DEV-06-boundary"},{"label":"本节结论","text":"乡村振兴可以从目标、方针、要求、保障和任务五个方面理解，各层内容共同服务农业农村现代化。","sourceBlockIds":["block:politics-toc-v2-u007:b049","block:politics-toc-v2-u007:b050","block:politics-toc-v2-u007:b051","block:politics-toc-v2-u007:b052","block:politics-toc-v2-u007:b056"],"emphasis":[],"kind":"recap","id":"DEV-06-recap"}]},{"id":"DEV-07","groupId":"development","title":"区域战略与城镇化怎样区分","question":"不同区域安排与以人为核心的新型城镇化分别关注什么？","objectives":["区分区域协调发展 区域重大战略与主体功能区战略","把乡村 区域与制度放回高质量发展主题"],"scopeLimit":"解释正式材料列举的战略类型与位置，不推演具体区域政策。","reflection":{"prompt":"主体功能区战略与新型城镇化的表述重点有什么不同？","answer":"主体功能区战略说明城市化地区、农产品主产区、生态功能区三大空间格局；新型城镇化强调以人为核心、把推进农业转移人口市民化作为首要任务，并推进以县城为重要载体的城镇化建设。","sourceBlockIds":["block:politics-toc-v2-u007:b055","block:politics-toc-v2-u007:b056"]},"previousLessonId":"DEV-06","nextLessonId":null,"transition":"下一主题：民生：就业 分配与保障","primaryUnitIds":["politics-toc-v2-u007"],"parts":[{"label":"区域协调发展战略","text":"正文列出推动西部大开发形成新格局、推动东北全面振兴取得新突破、促进中部地区加快崛起、鼓励东部地区加快推进现代化。这一组先帮助认识不同区域的发展安排，不能与下方所有战略名称混成同一层级。","sourceBlockIds":["block:politics-toc-v2-u007:b053"],"emphasis":[],"kind":"explanation","id":"DEV-07-body-1"},{"label":"区域重大战略","text":"区域重大战略包括京津冀协同发展、长江经济带发展、粤港澳大湾区建设、长三角一体化发展，以及黄河流域生态保护和高质量发展；正文还列出雄安新区与成渝地区双城经济圈建设。这里识别它们所在的一组，不要求本次展开每个区域的详细政策。","sourceBlockIds":["block:politics-toc-v2-u007:b054"],"emphasis":[],"kind":"explanation","id":"DEV-07-body-2"},{"label":"功能区与城镇化","text":"主体功能区战略逐步形成城市化地区、农产品主产区、生态功能区三大空间格局。新型城镇化则以人为核心，把推进农业转移人口市民化作为首要任务，并推进以县城为重要载体的城镇化建设。前者看空间功能，后者要保留人的位置。","sourceBlockIds":["block:politics-toc-v2-u007:b055","block:politics-toc-v2-u007:b056"],"emphasis":[{"part":"text","quote":"以人为核心","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEV-07-body-3"},{"label":"回看这组发展内容","text":"这一组从发展阶段与质量开始，经过理念、格局、基本经济制度和政府市场关系，再进入乡村与区域。这些内容不是同一概念的不同叫法；学习时既要认清各自对象，也要将它们放回高质量发展这一主题中。","sourceBlockIds":["block:politics-toc-v2-u007:b002","block:politics-toc-v2-u007:b003","block:politics-toc-v2-u007:b021","block:politics-toc-v2-u007:b043","block:politics-toc-v2-u007:b057"],"emphasis":[],"kind":"explanation","id":"DEV-07-body-4"},{"label":"注意边界","text":"这里是对现有材料的分类与联系进行阅读。不能把不同区域战略、空间功能分类和城镇化要求互相替代，也不能从这些概括直接推出某一地区的具体政策结论。","sourceBlockIds":["block:politics-toc-v2-u007:b053","block:politics-toc-v2-u007:b054","block:politics-toc-v2-u007:b055","block:politics-toc-v2-u007:b056"],"emphasis":[],"kind":"boundary","id":"DEV-07-boundary"},{"label":"本主题小结","text":"发展阶段、发展理念、发展格局和制度及实际领域共同构成这一主题的结构，各自回答方位、思路、路径和落实条件。","sourceBlockIds":["block:politics-toc-v2-u007:b057","block:politics-toc-v2-u007:b021","block:politics-toc-v2-u007:b043"],"emphasis":[],"kind":"recap","id":"DEV-07-recap"}]},{"id":"FOUND-01","groupId":"foundation","title":"先抓住贯穿始终的主题","question":"核心要义和四个自信是什么关系？","objectives":["说清坚持和发展中国特色社会主义这一主题","认识四个自信各自指向什么"],"scopeLimit":"本次建立主题与四个自信的联系，不展开全部历史进程。","reflection":{"prompt":"如果只能说两句话，怎样解释核心要义与四个自信？","answer":"核心要义是坚持和发展中国特色社会主义。四个自信分别指向道路、理论、制度和文化，共同服务于新时代对这一主题的坚持和发展。","sourceBlockIds":["block:politics-toc-v2-u001:b002","block:politics-toc-v2-u001:b003","block:politics-toc-v2-u001:b004"]},"previousLessonId":null,"nextLessonId":"FOUND-02","transition":"下一节：新时代：哪些变了，哪些没有变","primaryUnitIds":["politics-toc-v2-u001"],"parts":[{"label":"这一思想围绕什么展开","text":"坚持和发展中国特色社会主义，是改革开放以来我们党全部理论和实践的鲜明主题，也是习近平新时代中国特色社会主义思想的核心要义。这里先抓住“围绕什么展开”，再看后续具体观点。主题给出理解方向，不是一条可以替代所有具体内容的概括。","sourceBlockIds":["block:politics-toc-v2-u001:b002"],"emphasis":[{"part":"text","quote":"坚持和发展中国特色社会主义","occurrence":1,"role":"key"},{"part":"text","quote":"核心要义","occurrence":1,"role":"key"}],"kind":"explanation","id":"FOUND-01-body-1"},{"label":"为什么接着讲四个自信","text":"原文把改革开放以来取得一切成绩和进步的根本原因，归结为开辟道路、形成理论体系、确立制度、发展文化。这四个方面共同构成理解中国特色社会主义的线索：既涉及所走的路，也涉及理论、制度和文化，不能只取其中一个方面。","sourceBlockIds":["block:politics-toc-v2-u001:b003"],"emphasis":[{"part":"text","quote":"道路","occurrence":1,"role":"key"},{"part":"text","quote":"理论体系","occurrence":1,"role":"key"},{"part":"text","quote":"制度","occurrence":1,"role":"key"},{"part":"text","quote":"文化","occurrence":1,"role":"key"}],"kind":"explanation","id":"FOUND-01-body-2"},{"label":"四个自信怎样放回主题","text":"新时代坚持和发展中国特色社会主义，必须坚定道路自信、理论自信、制度自信、文化自信。原文特别指出，文化自信是更基础、更广泛、更深厚的自信。读到这里，先把四个名称与前面的四个方面对应起来，理解它们服务于同一主题。","sourceBlockIds":["block:politics-toc-v2-u001:b004"],"emphasis":[{"part":"text","quote":"道路自信、理论自信、制度自信、文化自信","occurrence":1,"role":"key"}],"kind":"explanation","id":"FOUND-01-body-3"},{"label":"保留各自的作用","text":"“核心要义”回答贯穿的主题；“四个自信”说明坚持和发展这一主题所要求的自信。文化自信的基础地位，不意味着另外三个方面可以省略。","sourceBlockIds":["block:politics-toc-v2-u001:b002","block:politics-toc-v2-u001:b004"],"emphasis":[],"kind":"boundary","id":"FOUND-01-boundary"},{"label":"本节结论","text":"“坚持和发展中国特色社会主义”确定主题，道路、理论、制度、文化四个方面把这一主题具体展开。","sourceBlockIds":["block:politics-toc-v2-u001:b002","block:politics-toc-v2-u001:b003","block:politics-toc-v2-u001:b004"],"emphasis":[],"kind":"recap","id":"FOUND-01-recap"}]},{"id":"FOUND-02","groupId":"foundation","title":"新时代：哪些变了，哪些没有变","question":"为什么进入新时代不等于改变初级阶段判断？","objectives":["理解新时代判断的基本依据","区分社会主要矛盾变化与基本国情不变"],"scopeLimit":"本次解释新时代的依据与边界，不逐项展开时代内涵和历史材料。","reflection":{"prompt":"某地总量增长后群众更关注服务质量，但城乡供给仍有差距。这能否推出社会主义初级阶段结束？","answer":"不能。材料有助于理解需要与发展的问题，但主要矛盾与历史阶段是不同判断对象。","sourceBlockIds":["block:politics-toc-v2-u001:b004","block:politics-toc-v2-u001:b011","block:politics-toc-v2-u001:b013","block:politics-toc-v2-u001:b014","block:politics-toc-v2-u001:b012","block:politics-toc-v2-u001:b015"]},"previousLessonId":"FOUND-01","nextLessonId":"FOUND-03","transition":"下一节：两个结合：理论怎样扎根","primaryUnitIds":["politics-toc-v2-u001"],"parts":[{"label":"先看基本依据","text":"党的十九大作出中国特色社会主义进入新时代的重大政治论断。我国社会主要矛盾的变化，是作出这一判断的基本依据：矛盾转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。先把“需要”与“发展”的关系读清，才能理解为什么不能只把发展理解为数量增加。","sourceBlockIds":["block:politics-toc-v2-u001:b004","block:politics-toc-v2-u001:b011"],"emphasis":[{"part":"text","quote":"社会主要矛盾的变化","occurrence":1,"role":"key"},{"part":"text","quote":"美好生活需要","occurrence":1,"role":"key"},{"part":"text","quote":"不平衡不充分的发展","occurrence":1,"role":"key"}],"kind":"explanation","id":"FOUND-02-body-1"},{"label":"再看另外两条线索","text":"原文还从党的主要任务、中国和世界关系的变化来说明新时代。党的十八大后，主要任务涉及实现第一个百年奋斗目标、开启第二个百年奋斗目标新征程；中国与国际社会联系更加紧密，相互依靠和影响加深。这些是理解时代条件的不同线索，不要把它们都改写成同一个概念。","sourceBlockIds":["block:politics-toc-v2-u001:b013","block:politics-toc-v2-u001:b014"],"emphasis":[{"part":"text","quote":"党的主要任务","occurrence":1,"role":"key"},{"part":"text","quote":"中国和世界关系","occurrence":1,"role":"key"}],"kind":"explanation","id":"FOUND-02-body-2"},{"label":"变化发生在什么基础上","text":"新时代社会主要矛盾的变化，没有改变我国社会主义所处历史阶段的判断。仍处于并将长期处于社会主义初级阶段的基本国情没有变，是世界最大发展中国家的国际地位没有变。变化与不变可以同时成立，因为这里讨论的对象不同。","sourceBlockIds":["block:politics-toc-v2-u001:b012"],"emphasis":[{"part":"text","quote":"社会主义初级阶段","occurrence":1,"role":"key"},{"part":"text","quote":"世界最大发展中国家","occurrence":1,"role":"key"}],"kind":"explanation","id":"FOUND-02-body-3"},{"label":"材料怎样用","text":"先分清题目在问主要矛盾、历史阶段还是国际地位。生活需要提升、公共服务存在差距，可以用来理解需要与发展之间的矛盾；不能据此推成基本国情已变。","sourceBlockIds":["block:politics-toc-v2-u001:b004","block:politics-toc-v2-u001:b011","block:politics-toc-v2-u001:b013","block:politics-toc-v2-u001:b014","block:politics-toc-v2-u001:b012"],"kind":"explanation","id":"FOUND-02-body-4"},{"label":"不要跨过判断边界","text":"“进入新时代”不能直接推成进入发达国家行列，也不能推成已经越过社会主义初级阶段。社会主要矛盾、基本国情和国际地位，要分别判断。","sourceBlockIds":["block:politics-toc-v2-u001:b012","block:politics-toc-v2-u001:b015"],"emphasis":[],"kind":"boundary","id":"FOUND-02-boundary"},{"label":"本节结论","text":"新时代要结合社会主要矛盾、主要任务以及中国和世界关系的新变化理解；其中社会主要矛盾变化是基本依据。始终同时保留“两项没有变”，不把时代变化误读为历史阶段的同样改变。","sourceBlockIds":["block:politics-toc-v2-u001:b011","block:politics-toc-v2-u001:b012","block:politics-toc-v2-u001:b013","block:politics-toc-v2-u001:b014"],"emphasis":[],"kind":"recap","id":"FOUND-02-recap"}]},{"id":"FOUND-03","groupId":"foundation","title":"两个结合：理论怎样扎根","question":"两个结合分别结合什么，为什么不是简单拼接？","objectives":["分清两个结合的共同出发点与不同对象","理解契合、相互成就与创新之间的联系"],"scopeLimit":"本次理解两个结合的对象和意义；不展开传统文化条目或理论发展史。","reflection":{"prompt":"某方案坚持马克思主义立场，依据当地资源和产业困难制定对策。材料直接体现哪一结合？为什么？","answer":"直接体现同中国具体实际相结合。理论基础是马克思主义，材料给出的对象是当地现实条件；不能自行补入未出现的文化对象。","sourceBlockIds":["block:politics-toc-v2-u002:b002","block:politics-toc-v2-u002:b003","block:politics-toc-v2-u002:b004","block:politics-toc-v2-u002:b007","block:politics-toc-v2-u002:b008","block:politics-toc-v2-u002:b009","block:politics-toc-v2-u002:b010","block:politics-toc-v2-u002:b011","block:politics-toc-v2-u002:b012"]},"previousLessonId":"FOUND-02","nextLessonId":null,"transition":"下一主题：十个明确","primaryUnitIds":["politics-toc-v2-u002"],"parts":[{"label":"先把两句话说完整","text":"“两个结合”是把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合。两者共同的出发点都是马克思主义基本原理，结合的对象分别是具体实际与优秀传统文化。习近平新时代中国特色社会主义思想是坚持两个结合的重大成果和光辉典范。","sourceBlockIds":["block:politics-toc-v2-u002:b002"],"emphasis":[{"part":"text","quote":"马克思主义基本原理","occurrence":1,"role":"key"},{"part":"text","quote":"中国具体实际","occurrence":1,"role":"key"},{"part":"text","quote":"中华优秀传统文化","occurrence":1,"role":"key"}],"kind":"explanation","id":"FOUND-03-body-1"},{"label":"第一个结合面对具体实际","text":"原文用马克思主义之“矢”射新时代中国之“的”来说明第一个结合。可以把阅读重点放在“原理与实际相结合”：理论面对的是新时代中国的具体实际，不能把这一关系理解为只记住原理、忽略所面对的实际问题。","sourceBlockIds":["block:politics-toc-v2-u002:b003"],"emphasis":[{"part":"text","quote":"原理与实际相结合","occurrence":1,"role":"key"}],"kind":"explanation","id":"FOUND-03-body-2"},{"label":"第二个结合怎样理解","text":"第二个结合使马克思主义这个魂脉和中华优秀传统文化这个根脉内在贯通、相互成就。结合的前提是彼此契合，结果是互相成就，形成有机统一的新的文化生命体；它筑牢道路根基、打开创新空间、巩固文化主体性。因此这里强调的不是把两套词句并排摆放。","sourceBlockIds":["block:politics-toc-v2-u002:b004","block:politics-toc-v2-u002:b007","block:politics-toc-v2-u002:b008","block:politics-toc-v2-u002:b009","block:politics-toc-v2-u002:b010","block:politics-toc-v2-u002:b011"],"emphasis":[{"part":"text","quote":"内在贯通、相互成就","occurrence":1,"role":"key"},{"part":"text","quote":"彼此契合","occurrence":1,"role":"key"}],"kind":"explanation","id":"FOUND-03-body-3"},{"label":"材料怎样用","text":"先看所坚持的理论基础，再看结合对象。分析某地现实条件并形成方案，直接指向同中国具体实际相结合；只有材料明确呈现优秀传统文化对象，才据此判断第二个结合。","sourceBlockIds":["block:politics-toc-v2-u002:b002","block:politics-toc-v2-u002:b003","block:politics-toc-v2-u002:b004","block:politics-toc-v2-u002:b007","block:politics-toc-v2-u002:b008","block:politics-toc-v2-u002:b009","block:politics-toc-v2-u002:b010","block:politics-toc-v2-u002:b011"],"kind":"explanation","id":"FOUND-03-body-4"},{"label":"共同出发点不能丢","text":"第二个结合不是脱离马克思主义另立理论来源。理解两个对象的区别时，也要保留马克思主义基本原理这一共同出发点。","sourceBlockIds":["block:politics-toc-v2-u002:b012"],"emphasis":[],"kind":"boundary","id":"FOUND-03-boundary"},{"label":"本主题小结","text":"本主题从坚持和发展的主题、所处的新时代条件以及理论同实际和文化的结合三个层次建立核心要义的基础结构。","sourceBlockIds":["block:politics-toc-v2-u002:b002","block:politics-toc-v2-u002:b003","block:politics-toc-v2-u002:b004","block:politics-toc-v2-u003:b004"],"emphasis":[],"kind":"recap","id":"FOUND-03-recap"}]},{"id":"MOD-01","groupId":"modernization","title":"目标怎样分解到两个阶段","question":"中国梦、中心任务与两步走各回答什么？","objectives":["分清愿景、中心任务和阶段安排","说清2035年与本世纪中叶的目标区别"],"scopeLimit":"本次建立目标层次；2035年各领域目标细目保留原文查阅。","reflection":{"prompt":"一份提纲把中国式现代化称为时间节点，把两步走称为推进方式，怎样校正？","answer":"中国式现代化说明推进方式，两步走说明阶段安排。应先分清“怎样推进”与“到何时达到什么目标”。","sourceBlockIds":["block:politics-toc-v2-u004:b004","block:politics-toc-v2-u004:b008","block:politics-toc-v2-u004:b002","block:politics-toc-v2-u004:b009","block:politics-toc-v2-u004:b010","block:politics-toc-v2-u004:b011","block:politics-toc-v2-u004:b012","block:politics-toc-v2-u004:b013","block:politics-toc-v2-u004:b014","block:politics-toc-v2-u004:b016"]},"previousLessonId":null,"nextLessonId":"MOD-02","transition":"下一节：五个中国特色怎样放在一起理解","primaryUnitIds":["politics-toc-v2-u004"],"parts":[{"label":"中国梦想实现什么","text":"实现中华民族伟大复兴是中华民族近代以来最伟大的梦想。中国梦的本质内涵是国家富强、民族振兴、人民幸福。理解时要同时保留国家、民族与人民这三个方面，不能只把它读成经济规模目标。","sourceBlockIds":["block:politics-toc-v2-u004:b004","block:politics-toc-v2-u004:b008"],"emphasis":[{"part":"text","quote":"国家富强、民族振兴、人民幸福","occurrence":1,"role":"key"}],"kind":"explanation","id":"MOD-01-body-1"},{"label":"实现途径与中心任务","text":"实现中国梦要走中国道路、弘扬中国精神、凝聚中国力量。它们分别指中国特色社会主义道路，以爱国主义为核心的民族精神和以改革创新为核心的时代精神，以及全国各族人民大团结的力量。党的二十大报告明确中心任务：全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴。","sourceBlockIds":["block:politics-toc-v2-u004:b002","block:politics-toc-v2-u004:b009","block:politics-toc-v2-u004:b010","block:politics-toc-v2-u004:b011","block:politics-toc-v2-u004:b012"],"emphasis":[{"part":"text","quote":"中国道路","occurrence":1,"role":"key"},{"part":"text","quote":"中国精神","occurrence":1,"role":"key"},{"part":"text","quote":"中国力量","occurrence":1,"role":"key"},{"part":"text","quote":"以中国式现代化全面推进中华民族伟大复兴","occurrence":1,"role":"key"}],"kind":"explanation","id":"MOD-01-body-2"},{"label":"两步走给出推进节奏","text":"全面建成社会主义现代化强国的战略安排分两步：2020年到2035年基本实现社会主义现代化；2035年到本世纪中叶建成富强民主文明和谐美丽的社会主义现代化强国。前一阶段是“基本实现现代化”，后一阶段在此基础上建成“现代化强国”，不能把两个目标节点合成一个。","sourceBlockIds":["block:politics-toc-v2-u004:b013","block:politics-toc-v2-u004:b014","block:politics-toc-v2-u004:b016"],"emphasis":[{"part":"text","quote":"2035年","occurrence":1,"role":"key"},{"part":"text","quote":"本世纪中叶","occurrence":1,"role":"key"}],"kind":"explanation","id":"MOD-01-body-3"},{"label":"材料怎样用","text":"把愿景、推进方式和时间阶段分开核对。遇到2035年先核对“基本实现社会主义现代化”，遇到本世纪中叶再核对强国目标；不把目标写成已完成事实。","sourceBlockIds":["block:politics-toc-v2-u004:b004","block:politics-toc-v2-u004:b008","block:politics-toc-v2-u004:b002","block:politics-toc-v2-u004:b009","block:politics-toc-v2-u004:b010","block:politics-toc-v2-u004:b011","block:politics-toc-v2-u004:b012","block:politics-toc-v2-u004:b013","block:politics-toc-v2-u004:b014","block:politics-toc-v2-u004:b016"],"kind":"explanation","id":"MOD-01-body-4"},{"label":"愿景与阶段安排分别读","text":"中国梦说明追求的愿景，“两步走”说明全面建成现代化强国的阶段安排。这里不把原文中的目标表述当作已经实现的结果。","sourceBlockIds":["block:politics-toc-v2-u004:b008","block:politics-toc-v2-u004:b014","block:politics-toc-v2-u004:b016"],"emphasis":[],"kind":"boundary","id":"MOD-01-boundary"},{"label":"本节结论","text":"民族复兴说明愿景，中国式现代化说明推进方式，两个阶段说明战略安排，三者共同形成目标与路径结构。","sourceBlockIds":["block:politics-toc-v2-u004:b002","block:politics-toc-v2-u004:b008","block:politics-toc-v2-u004:b014"],"emphasis":[],"kind":"recap","id":"MOD-01-recap"}]},{"id":"MOD-02","groupId":"modernization","title":"五个中国特色怎样放在一起理解","question":"中国式现代化为什么不能只看经济增长？","objectives":["认识五个中国特色的完整内容","分清共同富裕与整齐划一"],"scopeLimit":"本次解释五个特色的观察角度，不展开各领域实施措施。","reflection":{"prompt":"只说中国式现代化是发展经济，遗漏了哪些观察角度？","answer":"还需看到人口规模、全体人民共同富裕、物质与精神文明相协调、人与自然和谐共生及和平发展道路。它不是只用经济增长就能说明的概念。","sourceBlockIds":["block:politics-toc-v2-u004:b019","block:politics-toc-v2-u004:b020","block:politics-toc-v2-u004:b021","block:politics-toc-v2-u004:b022","block:politics-toc-v2-u004:b023","block:politics-toc-v2-u004:b032"]},"previousLessonId":"MOD-01","nextLessonId":"MOD-03","transition":"下一节：本质要求与重大原则各管什么","primaryUnitIds":["politics-toc-v2-u004"],"parts":[{"label":"从国情与人的生活看","text":"中国式现代化是人口规模巨大的现代化，也是全体人民共同富裕的现代化。前者提示理解现代化所面对的人口规模，后者明确发展的受益对象是全体人民。两个特色共同提醒我们：阅读这一概念，不能只有抽象的增长指标，还要看到具体国情与人民生活。","sourceBlockIds":["block:politics-toc-v2-u004:b019","block:politics-toc-v2-u004:b020"],"emphasis":[{"part":"text","quote":"人口规模巨大","occurrence":1,"role":"key"},{"part":"text","quote":"全体人民共同富裕","occurrence":1,"role":"key"}],"kind":"explanation","id":"MOD-02-body-1"},{"label":"从文明与自然看","text":"中国式现代化是物质文明和精神文明相协调的现代化，也是人与自然和谐共生的现代化。前者要求同时看物质生活与精神生活，后者把人与自然的关系纳入现代化的理解。它们不是经济增长之后才附加的装饰，而是中国特色本身的组成部分。","sourceBlockIds":["block:politics-toc-v2-u004:b021","block:politics-toc-v2-u004:b022"],"emphasis":[{"part":"text","quote":"物质文明和精神文明相协调","occurrence":1,"role":"key"},{"part":"text","quote":"人与自然和谐共生","occurrence":1,"role":"key"}],"kind":"explanation","id":"MOD-02-body-2"},{"label":"从对外道路看","text":"中国式现代化还是走和平发展道路的现代化。把这一点与前四点连起来，才有五个特色的完整轮廓：人口规模、共同富裕、两种文明协调、人与自然和谐共生、和平发展。这里的分组是阅读归纳，不改变原文五项的正式名称。","sourceBlockIds":["block:politics-toc-v2-u004:b019","block:politics-toc-v2-u004:b020","block:politics-toc-v2-u004:b021","block:politics-toc-v2-u004:b022","block:politics-toc-v2-u004:b023"],"emphasis":[{"part":"text","quote":"走和平发展道路","occurrence":1,"role":"key"}],"kind":"explanation","id":"MOD-02-body-3"},{"label":"特色不等于排除共同特征","text":"中国式现代化既有各国现代化的共同特征，更有基于中国国情的鲜明特色。共同富裕不是整齐划一，和平发展也不是放弃维护国家利益；不能由名称直接推出这些相反结论。","sourceBlockIds":["block:politics-toc-v2-u004:b032"],"emphasis":[],"kind":"boundary","id":"MOD-02-boundary"},{"label":"本节结论","text":"人口规模巨大、共同富裕、物质文明和精神文明协调、人与自然和谐共生、走和平发展道路，共同描绘中国式现代化的基本样貌。","sourceBlockIds":["block:politics-toc-v2-u004:b019","block:politics-toc-v2-u004:b020","block:politics-toc-v2-u004:b021","block:politics-toc-v2-u004:b022","block:politics-toc-v2-u004:b023"],"emphasis":[],"kind":"recap","id":"MOD-02-recap"}]},{"id":"MOD-03","groupId":"modernization","title":"本质要求与重大原则各管什么","question":"已经有五个特色，为什么还要读本质要求和重大原则？","objectives":["认识九项本质要求与五项重大原则","把特色、要求、原则放回同一个结构"],"scopeLimit":"本次默认列出必要要求并解释关系；具体制度与领域措施不在本小节展开。","reflection":{"prompt":"本质要求和重大原则都讲党的领导，是不是重复到可以只留一套？","answer":"不能。两者有联系，但本质要求与推进重大原则分别承担不同作用，完整清单与正式表述也不同。应理解相互呼应，同时保留各自名称和内容。","sourceBlockIds":["block:politics-toc-v2-u004:b024","block:politics-toc-v2-u004:b025","block:politics-toc-v2-u004:b026","block:politics-toc-v2-u004:b027","block:politics-toc-v2-u004:b028","block:politics-toc-v2-u004:b029","block:politics-toc-v2-u004:b030","block:politics-toc-v2-u004:b031","block:politics-toc-v2-u004:b019","block:politics-toc-v2-u004:b020","block:politics-toc-v2-u004:b021","block:politics-toc-v2-u004:b022","block:politics-toc-v2-u004:b023","block:politics-toc-v2-u004:b002","block:politics-toc-v2-u004:b014"]},"previousLessonId":"MOD-02","nextLessonId":null,"transition":"下一主题：党的领导与人民立场","primaryUnitIds":["politics-toc-v2-u004"],"parts":[{"label":"本质要求先确定方向","text":"本质要求包括坚持中国共产党领导、坚持中国特色社会主义。原文强调党的领导直接关系中国式现代化的根本方向、前途命运、最终成败。因此阅读后面的具体要求时，不能把前面这两项只当作可以略过的背景。","sourceBlockIds":["block:politics-toc-v2-u004:b024","block:politics-toc-v2-u004:b025"],"emphasis":[{"part":"text","quote":"坚持中国共产党领导","occurrence":1,"role":"key"},{"part":"text","quote":"坚持中国特色社会主义","occurrence":1,"role":"key"}],"kind":"explanation","id":"MOD-03-body-1"},{"label":"再把九项要求读完整","text":"其余本质要求是：实现高质量发展、发展全过程人民民主、丰富人民精神世界、实现全体人民共同富裕、促进人与自然和谐共生、推动构建人类命运共同体、创造人类文明新形态。连同前面两项，共九项。它们有些同五个特色呼应，但这两套表述的完整内容和名称不能互换。","sourceBlockIds":["block:politics-toc-v2-u004:b024"],"emphasis":[{"part":"text","quote":"实现高质量发展","occurrence":1,"role":"key"},{"part":"text","quote":"发展全过程人民民主","occurrence":1,"role":"key"},{"part":"text","quote":"创造人类文明新形态","occurrence":1,"role":"key"}],"kind":"explanation","id":"MOD-03-body-2"},{"label":"重大原则着重怎样推进","text":"推进中国式现代化须把握五项重大原则：坚持和加强党的全面领导，坚持中国特色社会主义道路，坚持以人民为中心的发展思想，坚持深化改革开放，坚持发扬斗争精神。读到这里，可以区分三个问题：有什么中国特色，要符合哪些本质要求，推进时应坚持哪些重大原则。","sourceBlockIds":["block:politics-toc-v2-u004:b026","block:politics-toc-v2-u004:b027","block:politics-toc-v2-u004:b028","block:politics-toc-v2-u004:b029","block:politics-toc-v2-u004:b030","block:politics-toc-v2-u004:b031"],"emphasis":[{"part":"text","quote":"坚持以人民为中心的发展思想","occurrence":1,"role":"key"},{"part":"text","quote":"坚持深化改革开放","occurrence":1,"role":"key"},{"part":"text","quote":"坚持发扬斗争精神","occurrence":1,"role":"key"}],"kind":"explanation","id":"MOD-03-body-3"},{"label":"相近表述也不混成一张清单","text":"“五个特色”“本质要求”“重大原则”有联系，但回答问题和完整表述不同。比如本质要求写“坚持中国共产党领导”，重大原则写“坚持和加强党的全面领导”，理解联系时仍保留原有表述。","sourceBlockIds":["block:politics-toc-v2-u004:b019","block:politics-toc-v2-u004:b020","block:politics-toc-v2-u004:b021","block:politics-toc-v2-u004:b022","block:politics-toc-v2-u004:b023","block:politics-toc-v2-u004:b024","block:politics-toc-v2-u004:b027"],"emphasis":[],"kind":"boundary","id":"MOD-03-boundary"},{"label":"本主题小结","text":"本主题依次说明中国式现代化的目标与阶段、五个特色、本质要求和重大原则，形成目标、样貌、要求与推进原则的结构。","sourceBlockIds":["block:politics-toc-v2-u004:b002","block:politics-toc-v2-u004:b014","block:politics-toc-v2-u004:b019","block:politics-toc-v2-u004:b020","block:politics-toc-v2-u004:b021","block:politics-toc-v2-u004:b022","block:politics-toc-v2-u004:b023","block:politics-toc-v2-u004:b024","block:politics-toc-v2-u004:b026"],"emphasis":[],"kind":"recap","id":"MOD-03-recap"}]},{"id":"SYS-01","groupId":"framework","title":"四组表述怎样共同构成体系","question":"十个明确之外，为什么还要理解方略、成果和方法？","objectives":["分清四组表述在体系中的职责","理解相互联系不等于一一对应"],"scopeLimit":"本次说明四组表述的联系；十三个方面成就只解释职责，尚不逐项展开。","reflection":{"prompt":"讨论治理思路时强调人民立场、问题导向和系统观念，主要是在运用哪组表述的职责？","answer":"主要体现六个必须坚持所说明的立场观点方法。判断依据是所问职责，不是“坚持”二字。","sourceBlockIds":["block:politics-toc-v2-u003:b002","block:politics-toc-v2-u003:b004","block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b020","block:politics-toc-v2-u003:b003","block:politics-toc-v2-u003:b017","block:politics-toc-v2-u003:b018"]},"previousLessonId":null,"nextLessonId":"SYS-02","transition":"下一节：十四个坚持：先读前七项","primaryUnitIds":["politics-toc-v2-u003"],"parts":[{"label":"先把体系要回答的问题摆出来","text":"这一思想科学回答了三组重大时代课题：坚持和发展什么样的中国特色社会主义、怎样坚持和发展；建设什么样的社会主义现代化强国、怎样建设；建设什么样的长期执政的马克思主义政党、怎样建设。先看到这些问题，才能理解为什么体系需要观点、方略与方法等不同层面的内容。","sourceBlockIds":["block:politics-toc-v2-u003:b002"],"emphasis":[{"part":"text","quote":"中国特色社会主义","occurrence":1,"role":"key"},{"part":"text","quote":"社会主义现代化强国","occurrence":1,"role":"key"},{"part":"text","quote":"马克思主义政党","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-01-body-1"},{"label":"十个明确与十四个坚持怎样相连","text":"已经读过的十个明确，是这一思想的主体内容，集中体现主要观点和基本精神，发挥统摄作用。十四个坚持是在治国理政各方面作出的理论分析和政策指导，构成基本方略。前者帮助把握理论层面的核心内容，后者把理解延伸到实践方略；不能用记住其中一套，代替理解另一套。","sourceBlockIds":["block:politics-toc-v2-u003:b004","block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b020"],"emphasis":[{"part":"text","quote":"主体内容","occurrence":1,"role":"key"},{"part":"text","quote":"基本方略","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-01-body-2"},{"label":"成果与方法补上另外两个角度","text":"十三个方面成就对新时代伟大实践作出科学总结，展示理论与实践成果；现有来源没有逐项列出十三个方面，本主题不把它编成完整清单。六个必须坚持则体现世界观、方法论和贯穿其中的立场观点方法。四组表述内在贯通、有机统一，并不是四个互不相关的章节。","sourceBlockIds":["block:politics-toc-v2-u003:b003","block:politics-toc-v2-u003:b017","block:politics-toc-v2-u003:b018"],"emphasis":[{"part":"text","quote":"理论与实践成果","occurrence":1,"role":"key"},{"part":"text","quote":"世界观、方法论","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-01-body-3"},{"label":"材料怎样用","text":"先判断题目是在问主体内容、基本方略、实践成果还是立场观点方法，再匹配四组表述。相互贯通不表示可相互替代，也不能只凭都出现“坚持”来判断。","sourceBlockIds":["block:politics-toc-v2-u003:b002","block:politics-toc-v2-u003:b004","block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b020","block:politics-toc-v2-u003:b003","block:politics-toc-v2-u003:b017","block:politics-toc-v2-u003:b018"],"kind":"explanation","id":"SYS-01-body-4"},{"label":"联系不等于机械配对","text":"原文说明四组内容内在贯通，并未给出十条、十四条、十三个方面与六项之间的一一对应表。本主题按阅读问题解释各自作用，不自行发明固定配对。","sourceBlockIds":["block:politics-toc-v2-u003:b003","block:politics-toc-v2-u003:b020"],"emphasis":[],"kind":"boundary","id":"SYS-01-boundary"},{"label":"本节结论","text":"核心观点、基本方略、实践成果、立场观点方法是理解科学体系的四个阅读角度，分别承担不同的说明职责。","sourceBlockIds":["block:politics-toc-v2-u003:b003","block:politics-toc-v2-u003:b004","block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b017","block:politics-toc-v2-u003:b018"],"emphasis":[],"kind":"recap","id":"SYS-01-recap"}]},{"id":"SYS-02","groupId":"framework","title":"十四个坚持：先读前七项","question":"领导、人民立场与制度治理怎样一起理解？","objectives":["认识十四个坚持的前七项","理解领导、人民立场与相关实践方略的联系"],"scopeLimit":"只讲前七项；三段分组是阅读安排，不是新的正式分类。","reflection":{"prompt":"前七项里，“面向谁”与“怎样发展”分别可以从哪些方略读起？","answer":"坚持以人民为中心帮助理解人民立场；坚持新发展理念指向发展的理念。它们各有对象，同时属于十四个坚持这一基本方略。","sourceBlockIds":["block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b016","block:politics-toc-v2-u003:b009","block:politics-toc-v2-u003:b011"]},"previousLessonId":"SYS-01","nextLessonId":"SYS-03","transition":"下一节：十四个坚持：再读后七项","primaryUnitIds":["politics-toc-v2-u003"],"parts":[{"label":"第1、2项：领导与人民立场","text":"前两项是坚持党对一切工作的领导、坚持以人民为中心。阅读时可以分别问：谁来领导，面向谁的需要？这两个角度帮助理解后面的治理方略。它们是同一组基本方略的不同内容，不能把领导要求与人民立场读成只能二选一的关系。","sourceBlockIds":["block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b016"],"emphasis":[{"part":"text","quote":"坚持党对一切工作的领导","occurrence":1,"role":"key"},{"part":"text","quote":"坚持以人民为中心","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-02-body-1"},{"label":"第3、4项：改革与发展","text":"接着是坚持全面深化改革、坚持新发展理念。这里同时保留“全面深化改革”和“新发展理念”两个对象：前者不能只缩成经济领域的一项调整，后者也不是用任意一个发展措施替代。先记住方略名称及其指向，具体改革目标和发展理念可在对应主题中继续理解。","sourceBlockIds":["block:politics-toc-v2-u003:b009","block:politics-toc-v2-u003:b011","block:politics-toc-v2-u003:b016"],"emphasis":[{"part":"text","quote":"坚持全面深化改革","occurrence":1,"role":"key"},{"part":"text","quote":"坚持新发展理念","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-02-body-2"},{"label":"第5至7项：民主、法治与价值体系","text":"随后三项是坚持人民当家作主、坚持全面依法治国、坚持社会主义核心价值体系。它们分别把人民当家作主、法治与价值体系纳入基本方略。理解它们共同属于治国理政的内容，同时保留三项各自的对象，不把民主、法治或价值体系中的一项当成另外两项的替代。","sourceBlockIds":["block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b016"],"emphasis":[{"part":"text","quote":"坚持人民当家作主","occurrence":1,"role":"key"},{"part":"text","quote":"坚持全面依法治国","occurrence":1,"role":"key"},{"part":"text","quote":"坚持社会主义核心价值体系","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-02-body-3"},{"label":"保留正式名称","text":"第7项的正式名称是“坚持社会主义核心价值体系”。这一小节没有将其改写为其他相近名称，也不把这七项重新命名为一套独立方略。","sourceBlockIds":["block:politics-toc-v2-u003:b016"],"emphasis":[],"kind":"boundary","id":"SYS-02-boundary"},{"label":"本节结论","text":"前七项依次涉及领导、人民立场、改革、发展理念、人民当家作主、依法治国和价值体系，只构成十四个坚持的前半部分。","sourceBlockIds":["block:politics-toc-v2-u003:b016"],"emphasis":[],"kind":"recap","id":"SYS-02-recap"}]},{"id":"SYS-03","groupId":"framework","title":"十四个坚持：再读后七项","question":"民生、自然、安全和党的建设为什么都在这组方略里？","objectives":["认识后七项并补全十四个坚持","把不同领域放回同一基本方略的范围"],"scopeLimit":"本次补齐后七项的核心指向，不展开各领域政策与制度细目。","reflection":{"prompt":"读完后七项，怎样避免只记一串相近的词？","answer":"先辨认民生、人与自然、安全、人民军队、“一国两制”和祖国统一、人类命运共同体、全面从严治党等不同对象，再把它们与前七项合回完整基本方略。","sourceBlockIds":["block:politics-toc-v2-u003:b016","block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b018"]},"previousLessonId":"SYS-02","nextLessonId":"SYS-04","transition":"下一节：六个必须坚持：立场、自立与创新","primaryUnitIds":["politics-toc-v2-u003"],"parts":[{"label":"第8至10项：生活、自然与安全","text":"这三项是坚持在发展中保障和改善民生、坚持人与自然和谐共生、坚持总体国家安全观。第一项把民生放在发展的过程中理解，第二项明确人与自然的关系，第三项强调总体国家安全观。保留不同对象，才能看清基本方略涉及多方面，不能只拿经济发展来概括。","sourceBlockIds":["block:politics-toc-v2-u003:b016"],"emphasis":[{"part":"text","quote":"坚持在发展中保障和改善民生","occurrence":1,"role":"key"},{"part":"text","quote":"坚持人与自然和谐共生","occurrence":1,"role":"key"},{"part":"text","quote":"坚持总体国家安全观","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-03-body-1"},{"label":"第11至13项：军队、统一与对外关系","text":"接着是坚持党对人民军队的绝对领导、坚持“一国两制”和推进祖国统一、坚持推动构建人类命运共同体。三项分别保留对人民军队的领导、“一国两制”与祖国统一、推动构建人类命运共同体这些正式对象。理解时先区分各自所讲的问题，不把它们并成一句泛泛的“安全与外交”。","sourceBlockIds":["block:politics-toc-v2-u003:b016"],"emphasis":[{"part":"text","quote":"坚持党对人民军队的绝对领导","occurrence":1,"role":"key"},{"part":"text","quote":"坚持“一国两制”和推进祖国统一","occurrence":1,"role":"key"},{"part":"text","quote":"坚持推动构建人类命运共同体","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-03-body-2"},{"label":"第14项：全面从严治党","text":"最后一项是坚持全面从严治党。前七项和这里的七项合起来，才构成十四个坚持的完整内容。原文将它们整体定位为治国理政各方面的理论分析和政策指导，不是仅针对某一个领域的操作清单。","sourceBlockIds":["block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b016"],"emphasis":[{"part":"text","quote":"坚持全面从严治党","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-03-body-3"},{"label":"阅读分段不是新的正式结构","text":"本主题用两小节承载十四项，是为了控制一次的阅读量，不意味着原文规定了两个层次或先后实施顺序。各领域的具体制度与措施，仍要到对应主题继续理解。","sourceBlockIds":["block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b016"],"emphasis":[],"kind":"boundary","id":"SYS-03-boundary"},{"label":"本节结论","text":"十四个坚持把不同方面的实践方略组织在一起，理解时既要分清每项对象，也要把握它们共同承担的基本方略职责。","sourceBlockIds":["block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b016","block:politics-toc-v2-u003:b018"],"emphasis":[],"kind":"recap","id":"SYS-03-recap"}]},{"id":"SYS-04","groupId":"framework","title":"六个必须坚持：立场、自立与创新","question":"人民至上、自信自立、守正创新分别强调什么？","objectives":["理解前三项的方法含义","区分价值立场、精神特质与理论品格"],"scopeLimit":"本次只引入前三项及原文给出的联系，不扩展成完整哲学课程。","reflection":{"prompt":"自信自立是否意味着只要发挥主观能动性就可以？","answer":"不是。原文强调客观规律性与主观能动性的有机结合，理解自信自立时需要同时保留这两个方面。","sourceBlockIds":["block:politics-toc-v2-u003:b018","block:politics-toc-v2-u003:b020","block:politics-toc-v2-u003:b019","block:politics-toc-v2-u003:b016"]},"previousLessonId":"SYS-03","nextLessonId":"SYS-05","transition":"下一节：六个必须坚持：从问题到整体视野","primaryUnitIds":["politics-toc-v2-u003"],"parts":[{"label":"先知道这一组的职责","text":"六个必须坚持是这一思想的世界观、方法论和贯穿其中的立场观点方法的重要体现。与刚读过的十四个坚持相比，这里进一步关注立场与认识、处理问题的方法，不是再列一遍治国理政的各个领域。","sourceBlockIds":["block:politics-toc-v2-u003:b018","block:politics-toc-v2-u003:b020"],"emphasis":[{"part":"text","quote":"世界观、方法论","occurrence":1,"role":"key"},{"part":"text","quote":"立场观点方法","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-04-body-1"},{"label":"人民至上与自信自立","text":"必须坚持人民至上，原文将其定位为根本价值立场，并联系历史唯物主义群众史观；阅读重点是把人民放在价值立场上理解。必须坚持自信自立，是内在精神特质，体现客观规律性和主观能动性的有机结合，不能把“自信”读成只凭主观愿望、不顾客观规律。","sourceBlockIds":["block:politics-toc-v2-u003:b018","block:politics-toc-v2-u003:b019"],"emphasis":[{"part":"text","quote":"必须坚持人民至上","occurrence":1,"role":"key"},{"part":"text","quote":"根本价值立场","occurrence":1,"role":"key"},{"part":"text","quote":"必须坚持自信自立","occurrence":1,"role":"key"},{"part":"text","quote":"客观规律性和主观能动性","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-04-body-2"},{"label":"守正创新怎样同时成立","text":"必须坚持守正创新，是鲜明理论品格，体现变与不变、继承与发展的内在联系。“守正”与“创新”在这里共同出现，理解时要同时看到继承和发展两个方面，而不是把两者处理成只能保留其中一个。原文给出的是联系，不能自行推成一份所有事情都适用的固定操作表。","sourceBlockIds":["block:politics-toc-v2-u003:b018","block:politics-toc-v2-u003:b019"],"emphasis":[{"part":"text","quote":"必须坚持守正创新","occurrence":1,"role":"key"},{"part":"text","quote":"继承与发展","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-04-body-3"},{"label":"相近词句保留各自位置","text":"“坚持以人民为中心”属于十四个坚持；“必须坚持人民至上”属于六个必须坚持。两者相互联系，正式名称和在体系中的位置仍分别保留，不能因为都讲人民就随意替换。","sourceBlockIds":["block:politics-toc-v2-u003:b016","block:politics-toc-v2-u003:b018","block:politics-toc-v2-u003:b020"],"emphasis":[],"kind":"boundary","id":"SYS-04-boundary"},{"label":"本节结论","text":"人民至上、自信自立、守正创新分别强调根本价值立场、内在精神特质和鲜明理论品格，共同体现立场观点方法。","sourceBlockIds":["block:politics-toc-v2-u003:b018","block:politics-toc-v2-u003:b019"],"emphasis":[],"kind":"recap","id":"SYS-04-recap"}]},{"id":"SYS-05","groupId":"framework","title":"六个必须坚持：从问题到整体视野","question":"问题导向、系统观念与胸怀天下怎样放在一起理解？","objectives":["理解后三项并补全六项方法","把本主题内容重新放回科学体系"],"scopeLimit":"本次完成方法组的基本理解；不据此宣称已掌握具体领域的完整分析方法。","reflection":{"prompt":"用自己的话解释：问题导向与系统观念有什么联系，又有什么不同？","answer":"问题导向强调面对问题的实践要求，联系矛盾的普遍性和客观性；系统观念强调从普遍联系理解内容。二者可以共同帮助思考，但不是同一个概念，也不构成原文规定的固定步骤。","sourceBlockIds":["block:politics-toc-v2-u003:b018","block:politics-toc-v2-u003:b019","block:politics-toc-v2-u003:b017","block:politics-toc-v2-u003:b003","block:politics-toc-v2-u003:b004","block:politics-toc-v2-u003:b015"]},"previousLessonId":"SYS-04","nextLessonId":null,"transition":"下一主题：中国式现代化","primaryUnitIds":["politics-toc-v2-u003"],"parts":[{"label":"问题导向：面对什么问题","text":"必须坚持问题导向，是重要实践要求，体现矛盾的普遍性和客观性。这里把“问题”放在实际认识和实践中理解，不能只把“问题导向”当成文章标题。原文提供的是方法要求，不是预先给所有问题指定同一个答案。","sourceBlockIds":["block:politics-toc-v2-u003:b018","block:politics-toc-v2-u003:b019"],"emphasis":[{"part":"text","quote":"必须坚持问题导向","occurrence":1,"role":"key"},{"part":"text","quote":"矛盾的普遍性和客观性","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-05-body-1"},{"label":"系统观念：怎样看到联系","text":"必须坚持系统观念，是基本思想和工作方法，体现辩证唯物主义普遍联系的原理。它提醒阅读者看到联系，而不把不同方面当作彼此隔绝的碎片。这里说明方法的指向；具体有哪些联系，仍需根据所研究内容判断，不能由“系统”一词直接推出所有关系。","sourceBlockIds":["block:politics-toc-v2-u003:b018","block:politics-toc-v2-u003:b019"],"emphasis":[{"part":"text","quote":"必须坚持系统观念","occurrence":1,"role":"key"},{"part":"text","quote":"普遍联系","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-05-body-2"},{"label":"胸怀天下：视野不止一个局部","text":"必须坚持胸怀天下，是中国共产党人的境界格局，体现马克思主义追求人类进步和解放的崇高理想。这一项与问题导向、系统观念分别有自己的侧重。连同上一小节的人民至上、自信自立、守正创新，才构成六个必须坚持的完整内容。","sourceBlockIds":["block:politics-toc-v2-u003:b018","block:politics-toc-v2-u003:b019"],"emphasis":[{"part":"text","quote":"必须坚持胸怀天下","occurrence":1,"role":"key"},{"part":"text","quote":"人类进步和解放","occurrence":1,"role":"key"}],"kind":"explanation","id":"SYS-05-body-3"},{"label":"不是三步公式，也不是全部课程","text":"本小节按问题、联系、视野帮助阅读，不把三项改造成原文规定的先后操作流程。十三个方面成就的详细内容仍缺少来源，不能因读完本主题就宣称科学体系所有具体知识已学完。","sourceBlockIds":["block:politics-toc-v2-u003:b017","block:politics-toc-v2-u003:b018","block:politics-toc-v2-u003:b019"],"emphasis":[],"kind":"boundary","id":"SYS-05-boundary"},{"label":"本主题小结","text":"本主题区分了主体内容、基本方略、实践成果和立场观点方法四组表述的职责，并重点理解十四个坚持和六个必须坚持在体系中的位置。","sourceBlockIds":["block:politics-toc-v2-u003:b003","block:politics-toc-v2-u003:b004","block:politics-toc-v2-u003:b015","block:politics-toc-v2-u003:b017","block:politics-toc-v2-u003:b018"],"emphasis":[],"kind":"recap","id":"SYS-05-recap"}]},{"title":"党的领导怎样落实到制度","question":"党的领导与具体国家机关职能为什么不能混同？","objectives":["理解领导地位与领导制度的联系"],"scopeLimit":"本节只解释“党的领导与具体国家机关职能为什么不能混同”；制度细目保留查阅。","reflection":{"prompt":"党的领导与具体国家机关职能为什么不能混同？","answer":"不能混同。党的领导明确根本政治方向和集中统一领导，国家机关依照制度和各自职能履职；领导地位不能替代具体机关职能。","sourceBlockIds":["block:politics-toc-v2-u005:b008","block:politics-toc-v2-u005:b009","block:politics-toc-v2-u005:b011","block:politics-toc-v2-u005:b012","block:politics-toc-v2-u005:b016"]},"id":"LEADERSHIP-01","groupId":"leadership","previousLessonId":null,"nextLessonId":"LEADERSHIP-02","transition":"下一节：人民立场怎样连到群众路线","corePromises":[{"quote":"最高政治领导力量","sourceBlockIds":["block:politics-toc-v2-u005:b004","block:politics-toc-v2-u005:b005","block:politics-toc-v2-u005:b008","block:politics-toc-v2-u005:b009"]},{"quote":"党中央集中统一领导","sourceBlockIds":["block:politics-toc-v2-u005:b004","block:politics-toc-v2-u005:b005","block:politics-toc-v2-u005:b008","block:politics-toc-v2-u005:b009"]},{"quote":"根本领导制度","sourceBlockIds":["block:politics-toc-v2-u005:b011","block:politics-toc-v2-u005:b012","block:politics-toc-v2-u005:b013","block:politics-toc-v2-u005:b015"]},{"quote":"统领地位","sourceBlockIds":["block:politics-toc-v2-u005:b011","block:politics-toc-v2-u005:b012","block:politics-toc-v2-u005:b013","block:politics-toc-v2-u005:b015"]}],"primaryUnitIds":["politics-toc-v2-u005"],"parts":[{"label":"先看地位和作用","text":"中国共产党领导是中国特色社会主义制度的最大优势，是实现中华民族伟大复兴的根本保证。中国共产党是我国最高政治领导力量，党中央集中统一领导是党的领导的最高原则。这里既讲领导力量，也讲领导原则，不能只记“领导”二字而丢掉所指对象。","sourceBlockIds":["block:politics-toc-v2-u005:b004","block:politics-toc-v2-u005:b005","block:politics-toc-v2-u005:b008","block:politics-toc-v2-u005:b009"],"emphasis":[{"part":"text","quote":"最高政治领导力量","occurrence":1,"role":"key"},{"part":"text","quote":"党中央集中统一领导","occurrence":1,"role":"key"}],"kind":"explanation","id":"LEADERSHIP-01-body-1"},{"label":"再看制度怎样承接","text":"党的领导制度是我国的根本领导制度，在中国特色社会主义制度体系中居于统领地位。原文列出的制度体系包括维护党中央权威和集中统一领导、为人民执政靠人民执政、提高执政能力和领导水平、全面从严治党等内容。地位通过制度安排落实，不能把它当成一句抽象口号。","sourceBlockIds":["block:politics-toc-v2-u005:b011","block:politics-toc-v2-u005:b012","block:politics-toc-v2-u005:b013","block:politics-toc-v2-u005:b015"],"emphasis":[{"part":"text","quote":"根本领导制度","occurrence":1,"role":"key"},{"part":"text","quote":"统领地位","occurrence":1,"role":"key"}],"kind":"explanation","id":"LEADERSHIP-01-body-2"},{"label":"领导不等于代替一切","text":"党领导一切不等于包揽一切。党的领导制度居于统领地位，与具体国家机关各自承担的职能不是同一层面的概念。制度完整清单可查阅，不把本小节的阅读归纳当作新分类。","sourceBlockIds":["block:politics-toc-v2-u005:b015","block:politics-toc-v2-u005:b016"],"emphasis":[],"kind":"boundary","id":"LEADERSHIP-01-boundary"},{"label":"本节结论","text":"领导力量、集中统一领导原则和根本领导制度共同说明党的领导地位及其制度安排，同时保留各国家机关依职能履职的边界。","sourceBlockIds":["block:politics-toc-v2-u005:b008","block:politics-toc-v2-u005:b009","block:politics-toc-v2-u005:b011","block:politics-toc-v2-u005:b012","block:politics-toc-v2-u005:b016"],"emphasis":[],"kind":"recap","id":"LEADERSHIP-01-recap"}]},{"title":"人民立场怎样连到群众路线","question":"人民立场、为人民服务和群众路线分别讲什么？","objectives":["把价值立场、根本目的与工作路线连起来"],"scopeLimit":"本节只解释“人民立场、为人民服务和群众路线分别讲什么”；制度细目保留查阅。","reflection":{"prompt":"人民立场、为人民服务和群众路线分别讲什么？","answer":"人民立场确立价值方向，为人民服务说明根本宗旨，群众路线把这一方向落实为一切为了群众、一切依靠群众。三者相连，但回答的问题不同。","sourceBlockIds":["block:politics-toc-v2-u006:b004","block:politics-toc-v2-u006:b008","block:politics-toc-v2-u006:b009","block:politics-toc-v2-u006:b012"]},"id":"LEADERSHIP-02","groupId":"leadership","previousLessonId":"LEADERSHIP-01","nextLessonId":"LEADERSHIP-03","transition":"下一节：共同富裕为什么同时讲发展与分配","corePromises":[{"quote":"根本政治立场","sourceBlockIds":["block:politics-toc-v2-u006:b003","block:politics-toc-v2-u006:b004","block:politics-toc-v2-u006:b006","block:politics-toc-v2-u006:b008"]},{"quote":"增进民生福祉","sourceBlockIds":["block:politics-toc-v2-u006:b003","block:politics-toc-v2-u006:b004","block:politics-toc-v2-u006:b006","block:politics-toc-v2-u006:b008"]},{"quote":"全心全意为人民服务","sourceBlockIds":["block:politics-toc-v2-u006:b005","block:politics-toc-v2-u006:b009","block:politics-toc-v2-u006:b010","block:politics-toc-v2-u006:b012"]},{"quote":"从群众中来、到群众中去","sourceBlockIds":["block:politics-toc-v2-u006:b005","block:politics-toc-v2-u006:b009","block:politics-toc-v2-u006:b010","block:politics-toc-v2-u006:b012"]}],"primaryUnitIds":["politics-toc-v2-u006"],"parts":[{"label":"立场与发展目的","text":"人民性是马克思主义的本质属性和鲜明品格，人民立场是中国共产党的根本政治立场。坚持人民至上是新时代治国理政的根本价值取向，增进民生福祉是发展的根本目的。先明确面向谁，再理解具体工作要求。","sourceBlockIds":["block:politics-toc-v2-u006:b003","block:politics-toc-v2-u006:b004","block:politics-toc-v2-u006:b006","block:politics-toc-v2-u006:b008"],"emphasis":[{"part":"text","quote":"根本政治立场","occurrence":1,"role":"key"},{"part":"text","quote":"增进民生福祉","occurrence":1,"role":"key"}],"kind":"explanation","id":"LEADERSHIP-02-body-1"},{"label":"宗旨怎样体现在工作中","text":"全心全意为人民服务是党的宗旨，群众路线是党的生命线和根本工作路线：一切为了群众、一切依靠群众，从群众中来、到群众中去。前两句说明为了谁、依靠谁，后两句说明与群众实践相联系的工作过程。密切联系群众是最大政治优势，脱离群众是执政后的最大危险。","sourceBlockIds":["block:politics-toc-v2-u006:b005","block:politics-toc-v2-u006:b009","block:politics-toc-v2-u006:b010","block:politics-toc-v2-u006:b012"],"emphasis":[{"part":"text","quote":"全心全意为人民服务","occurrence":1,"role":"key"},{"part":"text","quote":"从群众中来、到群众中去","occurrence":1,"role":"key"}],"kind":"explanation","id":"LEADERSHIP-02-body-2"},{"label":"几个定位各有对象","text":"人民立场说明根本政治立场，宗旨说明服务方向，群众路线说明根本工作路线。它们相关，但不是可以随意互换的名称，也不能把依靠群众理解为只有被动收集意见。","sourceBlockIds":["block:politics-toc-v2-u006:b004","block:politics-toc-v2-u006:b009","block:politics-toc-v2-u006:b010","block:politics-toc-v2-u006:b012"],"emphasis":[],"kind":"boundary","id":"LEADERSHIP-02-boundary"},{"label":"本节结论","text":"人民立场确立价值方向，为人民服务体现宗旨，群众路线把这一方向落实到为了群众、依靠群众的工作中。领导与人民立场共同理解后，再看共同富裕这一发展要求。","sourceBlockIds":["block:politics-toc-v2-u006:b004","block:politics-toc-v2-u006:b008","block:politics-toc-v2-u006:b009","block:politics-toc-v2-u006:b012"],"emphasis":[],"kind":"recap","id":"LEADERSHIP-02-recap"}]},{"title":"共同富裕为什么同时讲发展与分配","question":"共同富裕为什么不是平均分配或同时富裕？","objectives":["理解共同富裕的对象、节奏及三次分配"],"scopeLimit":"本节只解释“共同富裕为什么不是平均分配或同时富裕”；制度细目保留查阅。","reflection":{"prompt":"共同富裕为什么不是平均分配或同时富裕？","answer":"不是。共同富裕面向全体人民，兼顾物质和精神生活，也有逐步实现的过程；它依靠发展创造条件，并由初次分配、再分配和第三次分配协调配套。","sourceBlockIds":["block:politics-toc-v2-u006:b015","block:politics-toc-v2-u006:b018","block:politics-toc-v2-u006:b019","block:politics-toc-v2-u006:b021","block:politics-toc-v2-u006:b022","block:politics-toc-v2-u006:b023"]},"id":"LEADERSHIP-03","groupId":"leadership","previousLessonId":"LEADERSHIP-02","nextLessonId":null,"transition":"下一主题：高质量发展","corePromises":[{"quote":"全体人民","sourceBlockIds":["block:politics-toc-v2-u006:b015","block:politics-toc-v2-u006:b016","block:politics-toc-v2-u006:b017","block:politics-toc-v2-u006:b024"]},{"quote":"物质生活","sourceBlockIds":["block:politics-toc-v2-u006:b015","block:politics-toc-v2-u006:b016","block:politics-toc-v2-u006:b017","block:politics-toc-v2-u006:b024"]},{"quote":"精神生活","sourceBlockIds":["block:politics-toc-v2-u006:b015","block:politics-toc-v2-u006:b016","block:politics-toc-v2-u006:b017","block:politics-toc-v2-u006:b024"]},{"quote":"初次分配","sourceBlockIds":["block:politics-toc-v2-u006:b018","block:politics-toc-v2-u006:b019","block:politics-toc-v2-u006:b021","block:politics-toc-v2-u006:b022","block:politics-toc-v2-u006:b023"]},{"quote":"再分配","sourceBlockIds":["block:politics-toc-v2-u006:b018","block:politics-toc-v2-u006:b019","block:politics-toc-v2-u006:b021","block:politics-toc-v2-u006:b022","block:politics-toc-v2-u006:b023"]},{"quote":"第三次分配","sourceBlockIds":["block:politics-toc-v2-u006:b018","block:politics-toc-v2-u006:b019","block:politics-toc-v2-u006:b021","block:politics-toc-v2-u006:b022","block:politics-toc-v2-u006:b023"]}],"primaryUnitIds":["politics-toc-v2-u006"],"parts":[{"label":"先把共同富裕读完整","text":"共同富裕是全体人民共同富裕，既包括物质生活，也包括精神生活；不是少数人的富裕，不是整齐划一的平均主义，也不要求所有人、所有地区同时达到一个水平。2035年取得更为明显的实质性进展、本世纪中叶基本实现，是原文的阶段目标。","sourceBlockIds":["block:politics-toc-v2-u006:b015","block:politics-toc-v2-u006:b016","block:politics-toc-v2-u006:b017","block:politics-toc-v2-u006:b024"],"emphasis":[{"part":"text","quote":"全体人民","occurrence":1,"role":"key"},{"part":"text","quote":"物质生活","occurrence":1,"role":"key"},{"part":"text","quote":"精神生活","occurrence":1,"role":"key"}],"kind":"explanation","id":"LEADERSHIP-03-body-1"},{"label":"发展与分配共同考虑","text":"实现共同富裕要把“蛋糕”做大做好，也要切好分好，正确处理效率与公平。初次分配以市场作用为核心；再分配由政府主导调节，如税收、社保、转移支付；第三次分配由社会力量自愿参与，如慈善公益。这三者是协调配套，不能只靠其中一种安排解释共同富裕。","sourceBlockIds":["block:politics-toc-v2-u006:b018","block:politics-toc-v2-u006:b019","block:politics-toc-v2-u006:b021","block:politics-toc-v2-u006:b022","block:politics-toc-v2-u006:b023"],"emphasis":[{"part":"text","quote":"初次分配","occurrence":1,"role":"key"},{"part":"text","quote":"再分配","occurrence":1,"role":"key"},{"part":"text","quote":"第三次分配","occurrence":1,"role":"key"}],"kind":"explanation","id":"LEADERSHIP-03-body-2"},{"label":"自愿与政府调节不混同","text":"第三次分配强调社会力量自愿参与，再分配强调政府主导调节。共同富裕是总体概念，不能把它改成每个地区同时达到同一指标。","sourceBlockIds":["block:politics-toc-v2-u006:b016","block:politics-toc-v2-u006:b022","block:politics-toc-v2-u006:b023","block:politics-toc-v2-u006:b024"],"emphasis":[],"kind":"boundary","id":"LEADERSHIP-03-boundary"},{"label":"本主题小结","text":"共同富裕面向全体人民，兼顾物质和精神生活，依靠发展创造条件，并由初次分配、再分配和第三次分配协调配套。","sourceBlockIds":["block:politics-toc-v2-u006:b015","block:politics-toc-v2-u006:b018","block:politics-toc-v2-u006:b019","block:politics-toc-v2-u006:b021","block:politics-toc-v2-u006:b022","block:politics-toc-v2-u006:b023"],"emphasis":[],"kind":"recap","id":"LEADERSHIP-03-recap"}]},{"title":"就业与分配怎样连接发展和生活","question":"为什么就业与收入分配不能互相替代？","objectives":["分清民生之本与民生之源"],"scopeLimit":"本节只解释“为什么就业与收入分配不能互相替代”；具体措施保留查阅。","reflection":{"prompt":"为什么就业与收入分配不能互相替代？","answer":"就业解决劳动参与、岗位数量与质量问题，收入分配处理劳动成果怎样形成和调节。二者共同连接发展与生活，但承担的职责不同。","sourceBlockIds":["block:politics-toc-v2-u010:b004","block:politics-toc-v2-u010:b005","block:politics-toc-v2-u010:b007","block:politics-toc-v2-u010:b009","block:politics-toc-v2-u010:b010","block:politics-toc-v2-u010:b024"]},"id":"LIVELIHOOD-01","groupId":"livelihood","previousLessonId":null,"nextLessonId":"LIVELIHOOD-02","transition":"下一节：保障与健康为什么构成另一层支撑","corePromises":[{"quote":"就业是民生之本","sourceBlockIds":["block:politics-toc-v2-u010:b002","block:politics-toc-v2-u010:b004","block:politics-toc-v2-u010:b005","block:politics-toc-v2-u010:b006","block:politics-toc-v2-u010:b007"]},{"quote":"结构性就业矛盾","sourceBlockIds":["block:politics-toc-v2-u010:b002","block:politics-toc-v2-u010:b004","block:politics-toc-v2-u010:b005","block:politics-toc-v2-u010:b006","block:politics-toc-v2-u010:b007"]},{"quote":"收入分配是民生之源","sourceBlockIds":["block:politics-toc-v2-u010:b009","block:politics-toc-v2-u010:b010","block:politics-toc-v2-u010:b011","block:politics-toc-v2-u010:b012","block:politics-toc-v2-u010:b013"]},{"quote":"按贡献决定报酬","sourceBlockIds":["block:politics-toc-v2-u010:b009","block:politics-toc-v2-u010:b010","block:politics-toc-v2-u010:b011","block:politics-toc-v2-u010:b012","block:politics-toc-v2-u010:b013"]}],"primaryUnitIds":["politics-toc-v2-u010"],"parts":[{"label":"就业不仅看数量","text":"增进民生福祉是发展的根本目的，就业是民生之本。促进高质量充分就业，以破解结构性就业矛盾为着力点，既看就业质的有效提升，也看量的合理增长。原文同时保留劳动者自主就业、市场调节就业、政府促进就业和鼓励创业，不能只归为单一主体的事情。","sourceBlockIds":["block:politics-toc-v2-u010:b002","block:politics-toc-v2-u010:b004","block:politics-toc-v2-u010:b005","block:politics-toc-v2-u010:b006","block:politics-toc-v2-u010:b007"],"emphasis":[{"part":"text","quote":"就业是民生之本","occurrence":1,"role":"key"},{"part":"text","quote":"结构性就业矛盾","occurrence":1,"role":"key"}],"kind":"explanation","id":"LIVELIHOOD-01-body-1"},{"label":"分配关注收入怎样形成和调节","text":"收入分配是民生之源，分配制度是促进共同富裕的基础性制度。初次分配强调市场评价贡献、按贡献决定报酬，再分配通过税收、社会保障、转移支付调节；同时构建第三次分配协调配套的体系。还要增加低收入群体收入、扩大中等收入群体，不能把改善分配简化为只增加某一笔收入。","sourceBlockIds":["block:politics-toc-v2-u010:b009","block:politics-toc-v2-u010:b010","block:politics-toc-v2-u010:b011","block:politics-toc-v2-u010:b012","block:politics-toc-v2-u010:b013"],"emphasis":[{"part":"text","quote":"收入分配是民生之源","occurrence":1,"role":"key"},{"part":"text","quote":"按贡献决定报酬","occurrence":1,"role":"key"}],"kind":"explanation","id":"LIVELIHOOD-01-body-2"},{"label":"职责相连但不相同","text":"就业讨论劳动者的就业机会和质量，分配讨论收入形成与调节。就业增加不等于分配结构自动合理，理解联系时仍须分别看各自制度安排。","sourceBlockIds":["block:politics-toc-v2-u010:b004","block:politics-toc-v2-u010:b007","block:politics-toc-v2-u010:b009","block:politics-toc-v2-u010:b010","block:politics-toc-v2-u010:b024"],"emphasis":[],"kind":"boundary","id":"LIVELIHOOD-01-boundary"},{"label":"本节结论","text":"就业是民生之本，收入分配是民生之源；就业关注岗位数量与质量，分配关注收入形成和调节。","sourceBlockIds":["block:politics-toc-v2-u010:b004","block:politics-toc-v2-u010:b005","block:politics-toc-v2-u010:b007","block:politics-toc-v2-u010:b009","block:politics-toc-v2-u010:b010","block:politics-toc-v2-u010:b024"],"emphasis":[],"kind":"recap","id":"LIVELIHOOD-01-recap"}]},{"title":"保障与健康为什么构成另一层支撑","question":"社会保障、就业与健康建设各承担什么？","objectives":["认识社会保障结构与健康建设的作用"],"scopeLimit":"本节只解释“社会保障、就业与健康建设各承担什么”；具体措施保留查阅。","reflection":{"prompt":"社会保障、就业与健康建设各承担什么？","answer":"就业提供民生基础，社会保障织牢安全网，健康建设强调人民健康和预防。三者分别承担就业、风险保障和健康支持，不能互相替代。","sourceBlockIds":["block:politics-toc-v2-u010:b002","block:politics-toc-v2-u010:b004","block:politics-toc-v2-u010:b009","block:politics-toc-v2-u010:b015","block:politics-toc-v2-u010:b022","block:politics-toc-v2-u010:b023","block:politics-toc-v2-u010:b024"]},"id":"LIVELIHOOD-02","groupId":"livelihood","previousLessonId":"LIVELIHOOD-01","nextLessonId":null,"transition":"下一主题：教育 科技与人才","corePromises":[{"quote":"安全网","sourceBlockIds":["block:politics-toc-v2-u010:b015","block:politics-toc-v2-u010:b016","block:politics-toc-v2-u010:b017","block:politics-toc-v2-u010:b018","block:politics-toc-v2-u010:b019","block:politics-toc-v2-u010:b020"]},{"quote":"社会保险","sourceBlockIds":["block:politics-toc-v2-u010:b015","block:politics-toc-v2-u010:b016","block:politics-toc-v2-u010:b017","block:politics-toc-v2-u010:b018","block:politics-toc-v2-u010:b019","block:politics-toc-v2-u010:b020"]},{"quote":"社会福利","sourceBlockIds":["block:politics-toc-v2-u010:b015","block:politics-toc-v2-u010:b016","block:politics-toc-v2-u010:b017","block:politics-toc-v2-u010:b018","block:politics-toc-v2-u010:b019","block:politics-toc-v2-u010:b020"]},{"quote":"社会救济","sourceBlockIds":["block:politics-toc-v2-u010:b015","block:politics-toc-v2-u010:b016","block:politics-toc-v2-u010:b017","block:politics-toc-v2-u010:b018","block:politics-toc-v2-u010:b019","block:politics-toc-v2-u010:b020"]},{"quote":"人民健康","sourceBlockIds":["block:politics-toc-v2-u010:b022","block:politics-toc-v2-u010:b023"]},{"quote":"预防为主","sourceBlockIds":["block:politics-toc-v2-u010:b022","block:politics-toc-v2-u010:b023"]}],"primaryUnitIds":["politics-toc-v2-u010"],"parts":[{"label":"安全网不是一种措施","text":"社会保障体系是人民生活的安全网和社会运行的稳定器，包括社会保险、社会福利、社会救济、社会优抚与安置。原文将社会保险定位为核心内容，社会福利为最高层次措施，社会救济为最低层次措施，社会优抚面向法定对象。先分清体系及各项定位，不把它们当成同一个项目。","sourceBlockIds":["block:politics-toc-v2-u010:b015","block:politics-toc-v2-u010:b016","block:politics-toc-v2-u010:b017","block:politics-toc-v2-u010:b018","block:politics-toc-v2-u010:b019","block:politics-toc-v2-u010:b020"],"emphasis":[{"part":"text","quote":"安全网","occurrence":1,"role":"key"},{"part":"text","quote":"社会保险","occurrence":1,"role":"key"},{"part":"text","quote":"社会福利","occurrence":1,"role":"key"},{"part":"text","quote":"社会救济","occurrence":1,"role":"key"}],"kind":"explanation","id":"LIVELIHOOD-02-body-1"},{"label":"健康建设把目光放在预防","text":"人民健康是社会文明进步的基础，也是民族昌盛和国家富强的重要标志。健康中国建设坚持预防为主，深入实施健康中国行动。理解时同时保留人民健康的基础地位与预防为主的方针，不能把健康建设只理解为生病后的治疗。","sourceBlockIds":["block:politics-toc-v2-u010:b022","block:politics-toc-v2-u010:b023"],"emphasis":[{"part":"text","quote":"人民健康","occurrence":1,"role":"key"},{"part":"text","quote":"预防为主","occurrence":1,"role":"key"}],"kind":"explanation","id":"LIVELIHOOD-02-body-2"},{"label":"保障与就业各有作用","text":"社会保险、社会福利、社会救济、社会优抚各有定位，安全网不是只有单一措施。就业、分配、保障相互联系，保障体系不替代就业机会和收入形成。","sourceBlockIds":["block:politics-toc-v2-u010:b015","block:politics-toc-v2-u010:b016","block:politics-toc-v2-u010:b024"],"emphasis":[],"kind":"boundary","id":"LIVELIHOOD-02-boundary"},{"label":"本主题小结","text":"就业、分配、社会保障和健康分别承担劳动参与、成果分配、风险保障和健康支持，共同服务民生福祉。","sourceBlockIds":["block:politics-toc-v2-u010:b002","block:politics-toc-v2-u010:b004","block:politics-toc-v2-u010:b009","block:politics-toc-v2-u010:b015","block:politics-toc-v2-u010:b022","block:politics-toc-v2-u010:b023","block:politics-toc-v2-u010:b024"],"emphasis":[],"kind":"recap","id":"LIVELIHOOD-02-recap"}]},{"title":"教育为什么是基础性支撑","question":"培养什么人和怎样培养人为什么要一起理解？","objectives":["理解教育目标、任务与公平质量的联系"],"scopeLimit":"本节只解释“培养什么人和怎样培养人为什么要一起理解”；具体政策细目保留查阅。","reflection":{"prompt":"培养什么人和怎样培养人为什么要一起理解？","answer":"“培养什么人”明确教育的目标和方向，“怎样培养人”涉及立德树人以及公平、质量等实现方式。目标与方式要同时保留。","sourceBlockIds":["block:politics-toc-v2-u015:b002","block:politics-toc-v2-u015:b006","block:politics-toc-v2-u015:b007","block:politics-toc-v2-u015:b008","block:politics-toc-v2-u015:b009","block:politics-toc-v2-u015:b025"]},"id":"SUPPORT-01","groupId":"support","previousLessonId":null,"nextLessonId":"SUPPORT-02","transition":"下一节：科技创新怎样连接研究与人才","corePromises":[{"quote":"基础性、战略性支撑","sourceBlockIds":["block:politics-toc-v2-u015:b002","block:politics-toc-v2-u015:b003","block:politics-toc-v2-u015:b025"]},{"quote":"第一生产力","sourceBlockIds":["block:politics-toc-v2-u015:b002","block:politics-toc-v2-u015:b003","block:politics-toc-v2-u015:b025"]},{"quote":"第一资源","sourceBlockIds":["block:politics-toc-v2-u015:b002","block:politics-toc-v2-u015:b003","block:politics-toc-v2-u015:b025"]},{"quote":"第一动力","sourceBlockIds":["block:politics-toc-v2-u015:b002","block:politics-toc-v2-u015:b003","block:politics-toc-v2-u015:b025"]},{"quote":"立德树人","sourceBlockIds":["block:politics-toc-v2-u015:b005","block:politics-toc-v2-u015:b006","block:politics-toc-v2-u015:b007","block:politics-toc-v2-u015:b008","block:politics-toc-v2-u015:b009","block:politics-toc-v2-u015:b011"]},{"quote":"教育公平","sourceBlockIds":["block:politics-toc-v2-u015:b005","block:politics-toc-v2-u015:b006","block:politics-toc-v2-u015:b007","block:politics-toc-v2-u015:b008","block:politics-toc-v2-u015:b009","block:politics-toc-v2-u015:b011"]},{"quote":"人民满意","sourceBlockIds":["block:politics-toc-v2-u015:b005","block:politics-toc-v2-u015:b006","block:politics-toc-v2-u015:b007","block:politics-toc-v2-u015:b008","block:politics-toc-v2-u015:b009","block:politics-toc-v2-u015:b011"]}],"primaryUnitIds":["politics-toc-v2-u015"],"parts":[{"label":"把三者先放在同一位置","text":"教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑。科技是第一生产力，人才是第一资源，创新是第一动力。三者相互支撑，这些定位各有对象，不能因为都重要便随意交换名称。","sourceBlockIds":["block:politics-toc-v2-u015:b002","block:politics-toc-v2-u015:b003","block:politics-toc-v2-u015:b025"],"emphasis":[{"part":"text","quote":"基础性、战略性支撑","occurrence":1,"role":"key"},{"part":"text","quote":"第一生产力","occurrence":1,"role":"key"},{"part":"text","quote":"第一资源","occurrence":1,"role":"key"},{"part":"text","quote":"第一动力","occurrence":1,"role":"key"}],"kind":"explanation","id":"SUPPORT-01-body-1"},{"label":"教育先明确育人目标","text":"教育的根本问题是培养什么人、为谁培养人、怎样培养人。建设教育强国以党的全面领导为根本保证、立德树人为根本任务、为党育人为国育才为根本目标。教育公益性与公平不能丢：以教育公平促进社会公平正义，同时提高教育质量，人民满意是根本尺度。","sourceBlockIds":["block:politics-toc-v2-u015:b005","block:politics-toc-v2-u015:b006","block:politics-toc-v2-u015:b007","block:politics-toc-v2-u015:b008","block:politics-toc-v2-u015:b009","block:politics-toc-v2-u015:b011"],"emphasis":[{"part":"text","quote":"立德树人","occurrence":1,"role":"key"},{"part":"text","quote":"教育公平","occurrence":1,"role":"key"},{"part":"text","quote":"人民满意","occurrence":1,"role":"key"}],"kind":"explanation","id":"SUPPORT-01-body-2"},{"label":"基础与龙头不互换","text":"原文把基础教育作为基点，高等教育作为龙头，把加强教师队伍建设作为建设教育强国最重要的基础工作。这些是不同层面的定位，不宜压成一句“只抓高等教育”。","sourceBlockIds":["block:politics-toc-v2-u015:b009","block:politics-toc-v2-u015:b010"],"emphasis":[],"kind":"boundary","id":"SUPPORT-01-boundary"},{"label":"本节结论","text":"教育明确培养目标，以立德树人为根本任务，兼顾公益、公平和质量，并与科技、人才共同构成基础支撑。","sourceBlockIds":["block:politics-toc-v2-u015:b002","block:politics-toc-v2-u015:b006","block:politics-toc-v2-u015:b007","block:politics-toc-v2-u015:b008","block:politics-toc-v2-u015:b009","block:politics-toc-v2-u015:b025"],"emphasis":[],"kind":"recap","id":"SUPPORT-01-recap"}]},{"title":"科技创新怎样连接研究与人才","question":"基础研究、应用研究与人才评价怎样衔接？","objectives":["区分研究环节和创新主体并理解人才评价"],"scopeLimit":"本节只解释“基础研究、应用研究与人才评价怎样衔接”；具体政策细目保留查阅。","reflection":{"prompt":"基础研究、应用研究与人才评价怎样衔接？","answer":"基础研究提供源头支撑，应用研究推动成果面向实际，人才培养和评价为持续创新提供主体条件；教育又为人才成长奠定基础。","sourceBlockIds":["block:politics-toc-v2-u015:b002","block:politics-toc-v2-u015:b016","block:politics-toc-v2-u015:b020","block:politics-toc-v2-u015:b023","block:politics-toc-v2-u015:b024","block:politics-toc-v2-u015:b025"]},"id":"SUPPORT-02","groupId":"support","previousLessonId":"SUPPORT-01","nextLessonId":null,"transition":"下一主题：全过程人民民主","corePromises":[{"quote":"基础研究","sourceBlockIds":["block:politics-toc-v2-u015:b013","block:politics-toc-v2-u015:b015","block:politics-toc-v2-u015:b016","block:politics-toc-v2-u015:b017","block:politics-toc-v2-u015:b018"]},{"quote":"应用研究","sourceBlockIds":["block:politics-toc-v2-u015:b013","block:politics-toc-v2-u015:b015","block:politics-toc-v2-u015:b016","block:politics-toc-v2-u015:b017","block:politics-toc-v2-u015:b018"]},{"quote":"企业是科技创新的主体","sourceBlockIds":["block:politics-toc-v2-u015:b013","block:politics-toc-v2-u015:b015","block:politics-toc-v2-u015:b016","block:politics-toc-v2-u015:b017","block:politics-toc-v2-u015:b018"]},{"quote":"创新能力、质量、贡献","sourceBlockIds":["block:politics-toc-v2-u015:b020","block:politics-toc-v2-u015:b021","block:politics-toc-v2-u015:b022","block:politics-toc-v2-u015:b023","block:politics-toc-v2-u015:b024"]},{"quote":"创新精神与创新能力","sourceBlockIds":["block:politics-toc-v2-u015:b020","block:politics-toc-v2-u015:b021","block:politics-toc-v2-u015:b022","block:politics-toc-v2-u015:b023","block:politics-toc-v2-u015:b024"]}],"primaryUnitIds":["politics-toc-v2-u015"],"parts":[{"label":"创新有不同环节与主体","text":"高水平科技自立自强是国家强盛和民族复兴的战略基石，自主创新是科学技术发展的战略基点。基础研究是科技创新的源头，应用研究是转化为实际应用的桥梁。高水平研究型大学是基础研究的主力军和重大科技突破的生力军，企业是科技创新的主体；这些定位不能相互替代。","sourceBlockIds":["block:politics-toc-v2-u015:b013","block:politics-toc-v2-u015:b015","block:politics-toc-v2-u015:b016","block:politics-toc-v2-u015:b017","block:politics-toc-v2-u015:b018"],"emphasis":[{"part":"text","quote":"基础研究","occurrence":1,"role":"key"},{"part":"text","quote":"应用研究","occurrence":1,"role":"key"},{"part":"text","quote":"企业是科技创新的主体","occurrence":1,"role":"key"}],"kind":"explanation","id":"SUPPORT-02-body-1"},{"label":"人才既要培养，也要合理评价","text":"人才是实现民族振兴、赢得国际竞争主动的战略资源。人才队伍建设强调党对人才工作的全面领导，以国家发展需要和社会需求为导向，培养创新精神与创新能力。评价要破除唯论文、唯职称、唯学历、唯奖项，建立以创新能力、质量、贡献为导向的体系，而不是只换一个单项指标。","sourceBlockIds":["block:politics-toc-v2-u015:b020","block:politics-toc-v2-u015:b021","block:politics-toc-v2-u015:b022","block:politics-toc-v2-u015:b023","block:politics-toc-v2-u015:b024"],"emphasis":[{"part":"text","quote":"创新能力、质量、贡献","occurrence":1,"role":"key"},{"part":"text","quote":"创新精神与创新能力","occurrence":1,"role":"key"}],"kind":"explanation","id":"SUPPORT-02-body-2"},{"label":"不能把支撑关系读成简单流水线","text":"教育、科技、人才相互支撑，不是培养完人才才开始科研的固定先后步骤。基础研究与应用研究各有职责，企业和大学的定位也不能混同。","sourceBlockIds":["block:politics-toc-v2-u015:b016","block:politics-toc-v2-u015:b017","block:politics-toc-v2-u015:b018","block:politics-toc-v2-u015:b025"],"emphasis":[],"kind":"boundary","id":"SUPPORT-02-boundary"},{"label":"本主题小结","text":"科技创新连接研究与应用，人才培养和评价为创新提供支撑，教育又为人才成长奠定基础。本主题至此把三者重新放回共同结构，不要求一次展开全部措施。","sourceBlockIds":["block:politics-toc-v2-u015:b002","block:politics-toc-v2-u015:b016","block:politics-toc-v2-u015:b020","block:politics-toc-v2-u015:b023","block:politics-toc-v2-u015:b024","block:politics-toc-v2-u015:b025"],"emphasis":[],"kind":"recap","id":"SUPPORT-02-recap"}]},{"title":"人民当家作主怎样体现为制度","question":"人民代表大会制度与其他基本政治制度怎样定位？","objectives":["区分根本政治制度与三项基本政治制度"],"scopeLimit":"本节只解释“人民代表大会制度与其他基本政治制度怎样定位”；制度细目保留查阅。","reflection":{"prompt":"人民代表大会制度与其他基本政治制度怎样定位？","answer":"人民代表大会制度是根本政治制度，中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度是基本政治制度。它们定位不同，共同构成人民当家作主的制度安排。","sourceBlockIds":["block:politics-toc-v2-u008:b003","block:politics-toc-v2-u008:b005","block:politics-toc-v2-u008:b013","block:politics-toc-v2-u008:b018","block:politics-toc-v2-u008:b023","block:politics-toc-v2-u008:b027"]},"id":"DEMOCRACY-01","groupId":"democracy","previousLessonId":null,"nextLessonId":"DEMOCRACY-02","transition":"下一节：全过程为什么不只是选举过程","corePromises":[{"quote":"人民代表大会制度","sourceBlockIds":["block:politics-toc-v2-u008:b003"]},{"quote":"根本政治制度","sourceBlockIds":["block:politics-toc-v2-u008:b003"]},{"quote":"多党合作和政治协商制度","sourceBlockIds":["block:politics-toc-v2-u008:b005","block:politics-toc-v2-u008:b006","block:politics-toc-v2-u008:b013","block:politics-toc-v2-u008:b014","block:politics-toc-v2-u008:b018","block:politics-toc-v2-u008:b019"]},{"quote":"民族区域自治制度","sourceBlockIds":["block:politics-toc-v2-u008:b005","block:politics-toc-v2-u008:b006","block:politics-toc-v2-u008:b013","block:politics-toc-v2-u008:b014","block:politics-toc-v2-u008:b018","block:politics-toc-v2-u008:b019"]},{"quote":"基层群众自治制度","sourceBlockIds":["block:politics-toc-v2-u008:b005","block:politics-toc-v2-u008:b006","block:politics-toc-v2-u008:b013","block:politics-toc-v2-u008:b014","block:politics-toc-v2-u008:b018","block:politics-toc-v2-u008:b019"]}],"primaryUnitIds":["politics-toc-v2-u008"],"parts":[{"label":"先确定根本政治制度","text":"人民代表大会制度是坚持党的领导、人民当家作主、依法治国有机统一的根本政治制度安排，其实质是人民当家作主，一切权力属于人民。它不是三项基本政治制度中的一项，而是有不同的制度定位。","sourceBlockIds":["block:politics-toc-v2-u008:b003"],"emphasis":[{"part":"text","quote":"人民代表大会制度","occurrence":1,"role":"key"},{"part":"text","quote":"根本政治制度","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEMOCRACY-01-body-1"},{"label":"再看三项基本政治制度","text":"基本政治制度包括中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度。前者保留共产党领导、多党派合作，共产党执政、多党派参政的关系；民族区域自治保障少数民族管理本民族本地方事务的权利；基层群众自治是社会主义民主最广泛的实践。","sourceBlockIds":["block:politics-toc-v2-u008:b005","block:politics-toc-v2-u008:b006","block:politics-toc-v2-u008:b013","block:politics-toc-v2-u008:b014","block:politics-toc-v2-u008:b018","block:politics-toc-v2-u008:b019"],"emphasis":[{"part":"text","quote":"多党合作和政治协商制度","occurrence":1,"role":"key"},{"part":"text","quote":"民族区域自治制度","occurrence":1,"role":"key"},{"part":"text","quote":"基层群众自治制度","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEMOCRACY-01-body-2"},{"label":"机构与制度也分别读","text":"人民政协是爱国统一战线组织、协商民主的专门协商机构，不与国家权力机关混同。村委会、居委会是原文列出的基层群众自治形式，不能因为都涉及民主便混成同一机构。","sourceBlockIds":["block:politics-toc-v2-u008:b009","block:politics-toc-v2-u008:b010","block:politics-toc-v2-u008:b012","block:politics-toc-v2-u008:b020"],"emphasis":[],"kind":"boundary","id":"DEMOCRACY-01-boundary"},{"label":"本节结论","text":"根本政治制度与三项基本政治制度定位不同，共同构成人民当家作主的制度安排。","sourceBlockIds":["block:politics-toc-v2-u008:b003","block:politics-toc-v2-u008:b005","block:politics-toc-v2-u008:b013","block:politics-toc-v2-u008:b018","block:politics-toc-v2-u008:b023","block:politics-toc-v2-u008:b027"],"emphasis":[],"kind":"recap","id":"DEMOCRACY-01-recap"}]},{"title":"全过程为什么不只是选举过程","question":"全过程人民民主的“全过程”怎样体现？","objectives":["理解全过程民主的统一关系与实现形式"],"scopeLimit":"本节只解释“全过程人民民主的“全过程”怎样体现”；制度细目保留查阅。","reflection":{"prompt":"全过程人民民主的“全过程”怎样体现？","answer":"“全过程”体现为过程与成果、程序与实质等方面的统一，并通过制度载体、协商和基层民主贯穿参与过程，因此不只是一次选举。","sourceBlockIds":["block:politics-toc-v2-u008:b024","block:politics-toc-v2-u008:b026","block:politics-toc-v2-u008:b027","block:politics-toc-v2-u008:b028","block:politics-toc-v2-u008:b029","block:politics-toc-v2-u008:b035"]},"id":"DEMOCRACY-02","groupId":"democracy","previousLessonId":"DEMOCRACY-01","nextLessonId":"DEMOCRACY-03","transition":"下一节：统一战线怎样处理一致与多样","corePromises":[{"quote":"过程民主和成果民主","sourceBlockIds":["block:politics-toc-v2-u008:b023","block:politics-toc-v2-u008:b024","block:politics-toc-v2-u008:b025","block:politics-toc-v2-u008:b026"]},{"quote":"程序民主和实质民主","sourceBlockIds":["block:politics-toc-v2-u008:b023","block:politics-toc-v2-u008:b024","block:politics-toc-v2-u008:b025","block:politics-toc-v2-u008:b026"]},{"quote":"直接民主和间接民主","sourceBlockIds":["block:politics-toc-v2-u008:b023","block:politics-toc-v2-u008:b024","block:politics-toc-v2-u008:b025","block:politics-toc-v2-u008:b026"]},{"quote":"人民民主和国家意志","sourceBlockIds":["block:politics-toc-v2-u008:b023","block:politics-toc-v2-u008:b024","block:politics-toc-v2-u008:b025","block:politics-toc-v2-u008:b026"]},{"quote":"重要制度载体","sourceBlockIds":["block:politics-toc-v2-u008:b021","block:politics-toc-v2-u008:b027","block:politics-toc-v2-u008:b028","block:politics-toc-v2-u008:b029"]},{"quote":"民主协商","sourceBlockIds":["block:politics-toc-v2-u008:b021","block:politics-toc-v2-u008:b027","block:politics-toc-v2-u008:b028","block:politics-toc-v2-u008:b029"]},{"quote":"民主监督","sourceBlockIds":["block:politics-toc-v2-u008:b021","block:politics-toc-v2-u008:b027","block:politics-toc-v2-u008:b028","block:politics-toc-v2-u008:b029"]}],"primaryUnitIds":["politics-toc-v2-u008"],"parts":[{"label":"看相互统一的几个方面","text":"全过程人民民主是社会主义民主政治的本质属性，实现过程民主和成果民主、程序民主和实质民主、直接民主和间接民主、人民民主和国家意志相统一。它是全链条、全方位、全覆盖的民主，出发点和落脚点是最广大人民根本利益。不能只挑其中一面对其他方面作替代。","sourceBlockIds":["block:politics-toc-v2-u008:b023","block:politics-toc-v2-u008:b024","block:politics-toc-v2-u008:b025","block:politics-toc-v2-u008:b026"],"emphasis":[{"part":"text","quote":"过程民主和成果民主","occurrence":1,"role":"key"},{"part":"text","quote":"程序民主和实质民主","occurrence":1,"role":"key"},{"part":"text","quote":"直接民主和间接民主","occurrence":1,"role":"key"},{"part":"text","quote":"人民民主和国家意志","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEMOCRACY-02-body-1"},{"label":"制度与形式让全过程更具体","text":"人民代表大会制度是重要制度载体，协商民主是重要形式，基层民主是重要体现。基层群众自治包括民主选举、民主协商、民主决策、民主管理、民主监督；从这些内容可以看出，参与不限于投票这一刻。","sourceBlockIds":["block:politics-toc-v2-u008:b021","block:politics-toc-v2-u008:b027","block:politics-toc-v2-u008:b028","block:politics-toc-v2-u008:b029"],"emphasis":[{"part":"text","quote":"重要制度载体","occurrence":1,"role":"key"},{"part":"text","quote":"民主协商","occurrence":1,"role":"key"},{"part":"text","quote":"民主监督","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEMOCRACY-02-body-2"},{"label":"不脱离领导与法治","text":"全过程人民民主不是只在选举时参与，也不能脱离党的领导和依法治国单独理解。把过程与成果统一起来，不意味着只要有程序就能省略实际效果。","sourceBlockIds":["block:politics-toc-v2-u008:b024","block:politics-toc-v2-u008:b035"],"emphasis":[],"kind":"boundary","id":"DEMOCRACY-02-boundary"},{"label":"本节结论","text":"全过程人民民主统一过程与成果、程序与实质等方面，并通过制度载体、协商及基层民主贯穿参与过程，因此不只是一场选举。","sourceBlockIds":["block:politics-toc-v2-u008:b024","block:politics-toc-v2-u008:b026","block:politics-toc-v2-u008:b027","block:politics-toc-v2-u008:b028","block:politics-toc-v2-u008:b029","block:politics-toc-v2-u008:b035"],"emphasis":[],"kind":"recap","id":"DEMOCRACY-02-recap"}]},{"title":"统一战线怎样处理一致与多样","question":"求同存异为什么同时强调团结与多样性？","objectives":["认识统一战线的目的、关键与领导"],"scopeLimit":"本节只解释“求同存异为什么同时强调团结与多样性”；制度细目保留查阅。","reflection":{"prompt":"求同存异为什么同时强调团结与多样性？","answer":"求同存异是在共同目标上凝聚最大共识，同时承认和包容合理差异。团结提供共同方向，多样性保留不同主体，二者共同服务大团结大联合。","sourceBlockIds":["block:politics-toc-v2-u008:b003","block:politics-toc-v2-u008:b023","block:politics-toc-v2-u008:b031","block:politics-toc-v2-u008:b032","block:politics-toc-v2-u008:b033"]},"id":"DEMOCRACY-03","groupId":"democracy","previousLessonId":"DEMOCRACY-02","nextLessonId":null,"transition":"下一主题：改革与法治","corePromises":[{"quote":"大团结大联合","sourceBlockIds":["block:politics-toc-v2-u008:b031","block:politics-toc-v2-u008:b032"]},{"quote":"人心和力量","sourceBlockIds":["block:politics-toc-v2-u008:b031","block:politics-toc-v2-u008:b032"]},{"quote":"求同存异","sourceBlockIds":["block:politics-toc-v2-u008:b033","block:politics-toc-v2-u008:b034"]},{"quote":"尊重多样性","sourceBlockIds":["block:politics-toc-v2-u008:b033","block:politics-toc-v2-u008:b034"]},{"quote":"政治原则、政治方向","sourceBlockIds":["block:politics-toc-v2-u008:b033","block:politics-toc-v2-u008:b034"]}],"primaryUnitIds":["politics-toc-v2-u008"],"parts":[{"label":"先明确团结什么力量","text":"统一战线是夺取革命、建设、改革事业胜利和实现中华民族伟大复兴的重要法宝。统战工作的本质要求是大团结大联合，解决人心和力量问题。它不是把社会成员原有差异假定为已经不存在。","sourceBlockIds":["block:politics-toc-v2-u008:b031","block:politics-toc-v2-u008:b032"],"emphasis":[{"part":"text","quote":"大团结大联合","occurrence":1,"role":"key"},{"part":"text","quote":"人心和力量","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEMOCRACY-03-body-1"},{"label":"在多样性中寻求一致性","text":"统战工作的关键是坚持求同存异，发扬“团结—批评—团结”的优良传统，在尊重多样性中寻求一致性。党的领导是统一战线最鲜明的特征和最核心最根本的问题，主要体现为政治原则、政治方向、重大方针政策的领导。","sourceBlockIds":["block:politics-toc-v2-u008:b033","block:politics-toc-v2-u008:b034"],"emphasis":[{"part":"text","quote":"求同存异","occurrence":1,"role":"key"},{"part":"text","quote":"尊重多样性","occurrence":1,"role":"key"},{"part":"text","quote":"政治原则、政治方向","occurrence":1,"role":"key"}],"kind":"explanation","id":"DEMOCRACY-03-body-2"},{"label":"求同不等于抹平差异","text":"求同存异要在尊重多样性中寻求一致性；同时保留党的政治领导，不能把多样性理解为不需要共同方向。本主题不以统一战线替代前面讲过的各项民主制度。","sourceBlockIds":["block:politics-toc-v2-u008:b003","block:politics-toc-v2-u008:b033","block:politics-toc-v2-u008:b034"],"emphasis":[],"kind":"boundary","id":"DEMOCRACY-03-boundary"},{"label":"本主题小结","text":"本主题从制度定位、全过程参与和大团结大联合三个层次理解人民当家作主；三者相互联系但不是同义词。","sourceBlockIds":["block:politics-toc-v2-u008:b003","block:politics-toc-v2-u008:b023","block:politics-toc-v2-u008:b031","block:politics-toc-v2-u008:b032","block:politics-toc-v2-u008:b033"],"emphasis":[],"kind":"recap","id":"DEMOCRACY-03-recap"}]},{"title":"改革怎样兼顾发展与稳定","question":"改革、发展、稳定为什么要放在一起理解？","objectives":["理解改革性质、总目标和相关条件"],"scopeLimit":"本节只解释“改革、发展、稳定为什么要放在一起理解”；历史材料与实施细目保留查阅。","reflection":{"prompt":"改革、发展、稳定为什么要放在一起理解？","answer":"改革为发展提供动力，发展为稳定和民生改善创造条件，稳定又为改革发展提供环境；三者通过人民生活和制度完善联系起来。","sourceBlockIds":["block:politics-toc-v2-u012:b004","block:politics-toc-v2-u012:b008","block:politics-toc-v2-u012:b010","block:politics-toc-v2-u012:b011","block:politics-toc-v2-u012:b013"]},"id":"REFORMLAW-01","groupId":"reformlaw","previousLessonId":null,"nextLessonId":"REFORMLAW-02","transition":"下一节：法治道路与法治体系各说明什么","corePromises":[{"quote":"自我完善和发展","sourceBlockIds":["block:politics-toc-v2-u012:b004","block:politics-toc-v2-u012:b008","block:politics-toc-v2-u012:b009","block:politics-toc-v2-u012:b015"]},{"quote":"国家治理体系和治理能力现代化","sourceBlockIds":["block:politics-toc-v2-u012:b004","block:politics-toc-v2-u012:b008","block:politics-toc-v2-u012:b009","block:politics-toc-v2-u012:b015"]},{"quote":"强大动力","sourceBlockIds":["block:politics-toc-v2-u012:b010","block:politics-toc-v2-u012:b013"]},{"quote":"稳定是改革发展的前提","sourceBlockIds":["block:politics-toc-v2-u012:b010","block:politics-toc-v2-u012:b013"]},{"quote":"人民福祉","sourceBlockIds":["block:politics-toc-v2-u012:b010","block:politics-toc-v2-u012:b013"]},{"quote":"以制度建设为主线","sourceBlockIds":["block:politics-toc-v2-u012:b011","block:politics-toc-v2-u012:b014"]},{"quote":"全面依法治国","sourceBlockIds":["block:politics-toc-v2-u012:b011","block:politics-toc-v2-u012:b014"]},{"quote":"系统观念","sourceBlockIds":["block:politics-toc-v2-u012:b011","block:politics-toc-v2-u012:b014"]}],"primaryUnitIds":["politics-toc-v2-u012"],"parts":[{"label":"改革改变什么，保留什么","text":"改革开放是社会主义制度的自我完善和发展。全面深化改革总目标是完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化；根本标准涉及坚持和改善党的全面领导、坚持和完善中国特色社会主义制度。因此不能把改革理解为改变制度根本性质。","sourceBlockIds":["block:politics-toc-v2-u012:b004","block:politics-toc-v2-u012:b008","block:politics-toc-v2-u012:b009","block:politics-toc-v2-u012:b015"],"emphasis":[{"part":"text","quote":"自我完善和发展","occurrence":1,"role":"key"},{"part":"text","quote":"国家治理体系和治理能力现代化","occurrence":1,"role":"key"}],"kind":"explanation","id":"REFORMLAW-01-body-1"},{"label":"动力、目标与前提共同理解","text":"改革是经济社会发展的强大动力，发展是解决一切经济社会问题的关键，稳定是改革发展的前提，改善人民生活是处理三者关系的结合点。进一步全面深化改革以经济体制改革为牵引，以社会公平正义、人民福祉为出发点和落脚点；牵引不等于只有经济一个领域。","sourceBlockIds":["block:politics-toc-v2-u012:b010","block:politics-toc-v2-u012:b013"],"emphasis":[{"part":"text","quote":"强大动力","occurrence":1,"role":"key"},{"part":"text","quote":"稳定是改革发展的前提","occurrence":1,"role":"key"},{"part":"text","quote":"人民福祉","occurrence":1,"role":"key"}],"kind":"explanation","id":"REFORMLAW-01-body-2"},{"label":"原则与法治相互承接","text":"进一步全面深化改革坚持党的全面领导、以人民为中心、守正创新、以制度建设为主线、全面依法治国、系统观念。改革和法治如鸟之两翼、车之两轮，相辅相成；下一小节继续解释法治自身的道路和体系。","sourceBlockIds":["block:politics-toc-v2-u012:b011","block:politics-toc-v2-u012:b014"],"emphasis":[{"part":"text","quote":"以制度建设为主线","occurrence":1,"role":"key"},{"part":"text","quote":"全面依法治国","occurrence":1,"role":"key"},{"part":"text","quote":"系统观念","occurrence":1,"role":"key"}],"kind":"explanation","id":"REFORMLAW-01-body-3"},{"label":"历史起点不混同","text":"十一届三中全会开启改革开放和社会主义现代化建设新时期，十八届三中全会开创新时代全面深化改革新局面。二者定位不同；完整历史材料可查阅，不把历史节点当作本次全部目标。","sourceBlockIds":["block:politics-toc-v2-u012:b003","block:politics-toc-v2-u012:b007"],"emphasis":[],"kind":"boundary","id":"REFORMLAW-01-boundary"},{"label":"本节结论","text":"改革在制度自我完善中推进治理现代化，以人民生活连接改革、发展、稳定，并与法治相互促进。理解目标、性质和条件后，再读法治的具体结构。","sourceBlockIds":["block:politics-toc-v2-u012:b004","block:politics-toc-v2-u012:b008","block:politics-toc-v2-u012:b010","block:politics-toc-v2-u012:b011","block:politics-toc-v2-u012:b013"],"emphasis":[],"kind":"recap","id":"REFORMLAW-01-recap"}]},{"title":"法治道路与法治体系各说明什么","question":"为什么不能只用“有法律”解释全面依法治国？","objectives":["区分根本保证、制度基础、总目标与总抓手"],"scopeLimit":"本节只解释“为什么不能只用“有法律”解释全面依法治国”；历史材料与实施细目保留查阅。","reflection":{"prompt":"为什么不能只用“有法律”解释全面依法治国？","answer":"因为全面依法治国还要明确法治道路，并建设法律规范、法治实施、法治监督、法治保障和党内法规等体系；只有法律文本不足以说明完整结构。","sourceBlockIds":["block:politics-toc-v2-u013:b004","block:politics-toc-v2-u013:b009","block:politics-toc-v2-u013:b010","block:politics-toc-v2-u013:b011"]},"id":"REFORMLAW-02","groupId":"reformlaw","previousLessonId":"REFORMLAW-01","nextLessonId":"REFORMLAW-03","transition":"下一节：共同推进与一体建设怎样区分","corePromises":[{"quote":"党的领导","sourceBlockIds":["block:politics-toc-v2-u013:b004","block:politics-toc-v2-u013:b005","block:politics-toc-v2-u013:b006","block:politics-toc-v2-u013:b007"]},{"quote":"中国特色社会主义制度","sourceBlockIds":["block:politics-toc-v2-u013:b004","block:politics-toc-v2-u013:b005","block:politics-toc-v2-u013:b006","block:politics-toc-v2-u013:b007"]},{"quote":"法治理论","sourceBlockIds":["block:politics-toc-v2-u013:b004","block:politics-toc-v2-u013:b005","block:politics-toc-v2-u013:b006","block:politics-toc-v2-u013:b007"]},{"quote":"总目标","sourceBlockIds":["block:politics-toc-v2-u013:b009","block:politics-toc-v2-u013:b010"]},{"quote":"总抓手","sourceBlockIds":["block:politics-toc-v2-u013:b009","block:politics-toc-v2-u013:b010"]},{"quote":"法治实施","sourceBlockIds":["block:politics-toc-v2-u013:b009","block:politics-toc-v2-u013:b010"]},{"quote":"法治监督","sourceBlockIds":["block:politics-toc-v2-u013:b009","block:politics-toc-v2-u013:b010"]},{"quote":"党内法规体系","sourceBlockIds":["block:politics-toc-v2-u013:b009","block:politics-toc-v2-u013:b010"]}],"primaryUnitIds":["politics-toc-v2-u013"],"parts":[{"label":"先看道路的核心要义","text":"中国特色社会主义法治道路坚持党的领导、坚持中国特色社会主义制度、贯彻中国特色社会主义法治理论。党的领导是最根本保证，制度是根本制度基础和保障，理论提供理论指导和学理支撑。这三个定位相关，但不是同一个对象。","sourceBlockIds":["block:politics-toc-v2-u013:b004","block:politics-toc-v2-u013:b005","block:politics-toc-v2-u013:b006","block:politics-toc-v2-u013:b007"],"emphasis":[{"part":"text","quote":"党的领导","occurrence":1,"role":"key"},{"part":"text","quote":"中国特色社会主义制度","occurrence":1,"role":"key"},{"part":"text","quote":"法治理论","occurrence":1,"role":"key"}],"kind":"explanation","id":"REFORMLAW-02-body-1"},{"label":"体系把目标落实到不同方面","text":"全面依法治国总目标是建设中国特色社会主义法治体系、建设社会主义法治国家，总抓手是建设中国特色社会主义法治体系。体系包括完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，以及完善的党内法规体系；不仅需要规则文本，还要看实施、监督和保障等不同职责。","sourceBlockIds":["block:politics-toc-v2-u013:b009","block:politics-toc-v2-u013:b010"],"emphasis":[{"part":"text","quote":"总目标","occurrence":1,"role":"key"},{"part":"text","quote":"总抓手","occurrence":1,"role":"key"},{"part":"text","quote":"法治实施","occurrence":1,"role":"key"},{"part":"text","quote":"法治监督","occurrence":1,"role":"key"},{"part":"text","quote":"党内法规体系","occurrence":1,"role":"key"}],"kind":"explanation","id":"REFORMLAW-02-body-2"},{"label":"宪法实施是必要联系","text":"依法治国首先坚持依宪治国，依法执政首先坚持依宪执政，全面贯彻实施宪法是首要任务。原文还保留宪法确定的党的领导地位、国体和政体，不能把依宪治国抽离这些规定。","sourceBlockIds":["block:politics-toc-v2-u013:b011","block:politics-toc-v2-u013:b012"],"emphasis":[],"kind":"boundary","id":"REFORMLAW-02-boundary"},{"label":"本节结论","text":"道路明确领导、制度和理论，体系组织规范、实施、监督、保障与党内法规。把这些与依宪治国连接，才能理解法治为什么不止是“有法律”。","sourceBlockIds":["block:politics-toc-v2-u013:b004","block:politics-toc-v2-u013:b009","block:politics-toc-v2-u013:b010","block:politics-toc-v2-u013:b011"],"emphasis":[],"kind":"recap","id":"REFORMLAW-02-recap"}]},{"title":"共同推进与一体建设怎样区分","question":"依法治国、依法执政、依法行政和三种建设是不是同一套名称？","objectives":["理解三种依法行为与三种建设目标的联系"],"scopeLimit":"本节只解释“依法治国、依法执政、依法行政和三种建设是不是同一套名称”；历史材料与实施细目保留查阅。","reflection":{"prompt":"依法治国、依法执政、依法行政和三种建设是不是同一套名称？","answer":"不是。依法治国、依法执政、依法行政说明不同主体和职责的共同推进，法治国家、法治政府、法治社会说明建设对象的一体推进，两组名称不能互换。","sourceBlockIds":["block:politics-toc-v2-u012:b008","block:politics-toc-v2-u012:b011","block:politics-toc-v2-u013:b004","block:politics-toc-v2-u013:b010","block:politics-toc-v2-u013:b014","block:politics-toc-v2-u013:b020"]},"id":"REFORMLAW-03","groupId":"reformlaw","previousLessonId":"REFORMLAW-02","nextLessonId":null,"transition":"下一主题：文化与生态文明","corePromises":[{"quote":"共同推进","sourceBlockIds":["block:politics-toc-v2-u013:b014","block:politics-toc-v2-u013:b020"]},{"quote":"一体建设","sourceBlockIds":["block:politics-toc-v2-u013:b014","block:politics-toc-v2-u013:b020"]},{"quote":"法治国家","sourceBlockIds":["block:politics-toc-v2-u013:b015","block:politics-toc-v2-u013:b016","block:politics-toc-v2-u013:b017","block:politics-toc-v2-u013:b018","block:politics-toc-v2-u013:b019"]},{"quote":"法治政府","sourceBlockIds":["block:politics-toc-v2-u013:b015","block:politics-toc-v2-u013:b016","block:politics-toc-v2-u013:b017","block:politics-toc-v2-u013:b018","block:politics-toc-v2-u013:b019"]},{"quote":"法治社会","sourceBlockIds":["block:politics-toc-v2-u013:b015","block:politics-toc-v2-u013:b016","block:politics-toc-v2-u013:b017","block:politics-toc-v2-u013:b018","block:politics-toc-v2-u013:b019"]},{"quote":"科学立法、严格执法、公正司法、全民守法","sourceBlockIds":["block:politics-toc-v2-u013:b015","block:politics-toc-v2-u013:b016","block:politics-toc-v2-u013:b017","block:politics-toc-v2-u013:b018","block:politics-toc-v2-u013:b019"]}],"primaryUnitIds":["politics-toc-v2-u013"],"parts":[{"label":"两组表述各有职责","text":"法治中国建设坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政府、法治社会一体建设。前一组说明不同依法行为，后一组说明相互联系的建设方面。它们共同服务社会公平正义，不能仅因都有三个名称就机械逐项画等号。","sourceBlockIds":["block:politics-toc-v2-u013:b014","block:politics-toc-v2-u013:b020"],"emphasis":[{"part":"text","quote":"共同推进","occurrence":1,"role":"key"},{"part":"text","quote":"一体建设","occurrence":1,"role":"key"}],"kind":"explanation","id":"REFORMLAW-03-body-1"},{"label":"再看目标、重点与基础","text":"依法治国是党领导人民治理国家的基本方式；法治国家是法治建设的目标，法治政府建设是重点任务和主体工程，法治社会是基础。还要全面推进科学立法、严格执法、公正司法、全民守法，公正司法是维护社会公平正义的最后一道防线。","sourceBlockIds":["block:politics-toc-v2-u013:b015","block:politics-toc-v2-u013:b016","block:politics-toc-v2-u013:b017","block:politics-toc-v2-u013:b018","block:politics-toc-v2-u013:b019"],"emphasis":[{"part":"text","quote":"法治国家","occurrence":1,"role":"key"},{"part":"text","quote":"法治政府","occurrence":1,"role":"key"},{"part":"text","quote":"法治社会","occurrence":1,"role":"key"},{"part":"text","quote":"科学立法、严格执法、公正司法、全民守法","occurrence":1,"role":"key"}],"kind":"explanation","id":"REFORMLAW-03-body-2"},{"label":"有区别也要共同理解","text":"依法治国、依法执政、依法行政的主体与侧重点不同，同时共同服务一体建设。突出法治政府的重点地位，不等于法治社会或其他环节可以省略。","sourceBlockIds":["block:politics-toc-v2-u013:b014","block:politics-toc-v2-u013:b017","block:politics-toc-v2-u013:b018","block:politics-toc-v2-u013:b020"],"emphasis":[],"kind":"boundary","id":"REFORMLAW-03-boundary"},{"label":"本主题小结","text":"改革推动制度完善并与法治相互促进；法治具有道路、体系和建设安排，共同推进与一体建设需要分别理解。","sourceBlockIds":["block:politics-toc-v2-u012:b008","block:politics-toc-v2-u012:b011","block:politics-toc-v2-u013:b004","block:politics-toc-v2-u013:b010","block:politics-toc-v2-u013:b014","block:politics-toc-v2-u013:b020"],"emphasis":[],"kind":"recap","id":"REFORMLAW-03-recap"}]},{"title":"文化自信怎样连到传承与创新","question":"传承优秀传统文化为什么同时强调创新？","objectives":["理解文化建设的方向及创造性转化"],"scopeLimit":"本节只解释“传承优秀传统文化为什么同时强调创新”；不把文化与生态文明伪造成直接因果关系。","reflection":{"prompt":"传承优秀传统文化为什么同时强调创新？","answer":"传承要保留优秀传统文化的根脉，创新则通过创造性转化和创新性发展使其适应新的条件。只有传承没有创新，文化难以持续发展。","sourceBlockIds":["block:politics-toc-v2-u009:b003","block:politics-toc-v2-u009:b004","block:politics-toc-v2-u009:b005","block:politics-toc-v2-u009:b006","block:politics-toc-v2-u009:b007","block:politics-toc-v2-u009:b008"]},"id":"CULTUREECO-01","groupId":"cultureeco","previousLessonId":null,"nextLessonId":"CULTUREECO-02","transition":"下一节：文化强国之强怎样落到人民","corePromises":[{"quote":"文化自信","sourceBlockIds":["block:politics-toc-v2-u009:b003","block:politics-toc-v2-u009:b004","block:politics-toc-v2-u009:b006"]},{"quote":"马克思主义","sourceBlockIds":["block:politics-toc-v2-u009:b003","block:politics-toc-v2-u009:b004","block:politics-toc-v2-u009:b006"]},{"quote":"创造性转化、创新性发展","sourceBlockIds":["block:politics-toc-v2-u009:b005","block:politics-toc-v2-u009:b007","block:politics-toc-v2-u009:b008"]},{"quote":"保护第一、合理利用、最小干预","sourceBlockIds":["block:politics-toc-v2-u009:b005","block:politics-toc-v2-u009:b007","block:politics-toc-v2-u009:b008"]}],"primaryUnitIds":["politics-toc-v2-u009"],"parts":[{"label":"先确定文化建设方向","text":"中国特色社会主义文化发展道路最本质的特征是坚持党的领导，建设文化强国的关键在于坚定文化自信。还要坚持马克思主义在意识形态领域指导地位的根本制度。领导、指导思想与自信分别有自己的定位，不能只留下某一个关键词。","sourceBlockIds":["block:politics-toc-v2-u009:b003","block:politics-toc-v2-u009:b004","block:politics-toc-v2-u009:b006"],"emphasis":[{"part":"text","quote":"文化自信","occurrence":1,"role":"key"},{"part":"text","quote":"马克思主义","occurrence":1,"role":"key"}],"kind":"explanation","id":"CULTUREECO-01-body-1"},{"label":"传承不是原样照搬","text":"发展社会主义先进文化、弘扬革命文化、传承中华优秀传统文化，同时坚持创造性转化、创新性发展。原文强调以马克思主义激活优秀因子、赋予时代内涵；文化遗产保护遵循保护第一、合理利用、最小干预。创新与保护各有边界，不是任意改造或完全冻结。","sourceBlockIds":["block:politics-toc-v2-u009:b005","block:politics-toc-v2-u009:b007","block:politics-toc-v2-u009:b008"],"emphasis":[{"part":"text","quote":"创造性转化、创新性发展","occurrence":1,"role":"key"},{"part":"text","quote":"保护第一、合理利用、最小干预","occurrence":1,"role":"key"}],"kind":"explanation","id":"CULTUREECO-01-body-2"},{"label":"自信不等于封闭","text":"文化自信不是文化封闭，守正与创新、民族性与开放性需要统一。中华文明具有连续性、创新性、统一性、包容性、和平性，这些特性也不能被简化成只有连续不变。","sourceBlockIds":["block:politics-toc-v2-u009:b002","block:politics-toc-v2-u009:b013"],"emphasis":[],"kind":"boundary","id":"CULTUREECO-01-boundary"},{"label":"本节结论","text":"文化建设在领导与指导思想下坚定文化自信，连接先进文化、革命文化和中华优秀传统文化，并以转化发展和保护原则处理传承创新。","sourceBlockIds":["block:politics-toc-v2-u009:b003","block:politics-toc-v2-u009:b004","block:politics-toc-v2-u009:b005","block:politics-toc-v2-u009:b006","block:politics-toc-v2-u009:b007","block:politics-toc-v2-u009:b008"],"emphasis":[],"kind":"recap","id":"CULTUREECO-01-recap"}]},{"title":"文化强国之强怎样落到人民","question":"为什么文化建设不能只看经济收益？","objectives":["理解创作导向与社会效益的关系"],"scopeLimit":"本节只解释“为什么文化建设不能只看经济收益”；不把文化与生态文明伪造成直接因果关系。","reflection":{"prompt":"为什么文化建设不能只看经济收益？","answer":"文化建设还承担价值引领、满足人民精神文化需要和社会效益等职责。经济收益只是一个方面，不能替代以人民为中心和社会效益的判断。","sourceBlockIds":["block:politics-toc-v2-u009:b005","block:politics-toc-v2-u009:b010","block:politics-toc-v2-u009:b012","block:politics-toc-v2-u011:b002","block:politics-toc-v2-u011:b004"]},"id":"CULTUREECO-02","groupId":"cultureeco","previousLessonId":"CULTUREECO-01","nextLessonId":"CULTUREECO-03","transition":"下一节：生态保护与发展怎样放在一起","corePromises":[{"quote":"以人民为中心","sourceBlockIds":["block:politics-toc-v2-u009:b010"]},{"quote":"社会效益放在首位","sourceBlockIds":["block:politics-toc-v2-u009:b010"]},{"quote":"创新创造活力","sourceBlockIds":["block:politics-toc-v2-u009:b010"]},{"quote":"思想境界、精神状态、文化修养","sourceBlockIds":["block:politics-toc-v2-u009:b009","block:politics-toc-v2-u009:b011","block:politics-toc-v2-u009:b012"]},{"quote":"首要政治任务","sourceBlockIds":["block:politics-toc-v2-u009:b009","block:politics-toc-v2-u009:b011","block:politics-toc-v2-u009:b012"]}],"primaryUnitIds":["politics-toc-v2-u009"],"parts":[{"label":"创作与效益的衡量","text":"文化建设坚持以人民为中心的创作导向，把社会效益放在首位，实现社会效益和经济效益相统一。两种效益不是不分主次地并列，也不是只留其中一种。深化文化体制机制改革以激发创新创造活力为中心环节。","sourceBlockIds":["block:politics-toc-v2-u009:b010"],"emphasis":[{"part":"text","quote":"以人民为中心","occurrence":1,"role":"key"},{"part":"text","quote":"社会效益放在首位","occurrence":1,"role":"key"},{"part":"text","quote":"创新创造活力","occurrence":1,"role":"key"}],"kind":"explanation","id":"CULTUREECO-02-body-1"},{"label":"强最终体现在哪里","text":"文化强国之“强”最终体现在人民的思想境界、精神状态、文化修养上。原文还强调用党的创新理论武装全党、教育人民这一首要政治任务，以及弘扬以伟大建党精神为源头的精神谱系。这些内容帮助把文化建设从作品数量和收入指标读回人的精神生活。","sourceBlockIds":["block:politics-toc-v2-u009:b009","block:politics-toc-v2-u009:b011","block:politics-toc-v2-u009:b012"],"emphasis":[{"part":"text","quote":"思想境界、精神状态、文化修养","occurrence":1,"role":"key"},{"part":"text","quote":"首要政治任务","occurrence":1,"role":"key"}],"kind":"explanation","id":"CULTUREECO-02-body-2"},{"label":"归纳不改变正式定位","text":"创作导向、效益关系、首要政治任务和最终体现分别回答不同问题，不能用“服务人民”一句话替代全部具体内容；更多背景仍可查阅。","sourceBlockIds":["block:politics-toc-v2-u009:b010","block:politics-toc-v2-u009:b011","block:politics-toc-v2-u009:b012"],"emphasis":[],"kind":"boundary","id":"CULTUREECO-02-boundary"},{"label":"本节结论","text":"文化建设既明确方向和传承创新，也坚持以人民为中心，处理创作导向以及社会效益与经济效益的关系。","sourceBlockIds":["block:politics-toc-v2-u009:b005","block:politics-toc-v2-u009:b010","block:politics-toc-v2-u009:b012","block:politics-toc-v2-u011:b002","block:politics-toc-v2-u011:b004"],"emphasis":[],"kind":"recap","id":"CULTUREECO-02-recap"}]},{"title":"生态保护与发展怎样放在一起","question":"为什么生态问题不能只理解为末端治理？","objectives":["理解绿色低碳与发展方式的联系"],"scopeLimit":"本节只解释“为什么生态问题不能只理解为末端治理”；不把文化与生态文明伪造成直接因果关系。","reflection":{"prompt":"为什么生态问题不能只理解为末端治理？","answer":"生态文明涉及发展方式、生活方式、资源利用和系统保护，问题产生于发展全过程。只做污染后的末端治理，不能替代源头预防和系统治理。","sourceBlockIds":["block:politics-toc-v2-u011:b002","block:politics-toc-v2-u011:b003","block:politics-toc-v2-u011:b004","block:politics-toc-v2-u011:b006","block:politics-toc-v2-u011:b007","block:politics-toc-v2-u011:b008"]},"id":"CULTUREECO-03","groupId":"cultureeco","previousLessonId":"CULTUREECO-02","nextLessonId":"CULTUREECO-04","transition":"下一节：生态目标与保护安排怎样分层","corePromises":[{"quote":"绿色化、低碳化","sourceBlockIds":["block:politics-toc-v2-u011:b002","block:politics-toc-v2-u011:b003","block:politics-toc-v2-u011:b004","block:politics-toc-v2-u011:b012"]},{"quote":"高质量发展","sourceBlockIds":["block:politics-toc-v2-u011:b002","block:politics-toc-v2-u011:b003","block:politics-toc-v2-u011:b004","block:politics-toc-v2-u011:b012"]},{"quote":"经济发展方式和生活方式","sourceBlockIds":["block:politics-toc-v2-u011:b005","block:politics-toc-v2-u011:b006","block:politics-toc-v2-u011:b007","block:politics-toc-v2-u011:b008"]},{"quote":"节约优先、保护优先、自然恢复为主","sourceBlockIds":["block:politics-toc-v2-u011:b005","block:politics-toc-v2-u011:b006","block:politics-toc-v2-u011:b007","block:politics-toc-v2-u011:b008"]}],"primaryUnitIds":["politics-toc-v2-u011"],"parts":[{"label":"先认识生态文明的位置","text":"生态文明建设是关系中华民族永续发展的根本大计，尊重自然、顺应自然、保护自然是全面建设现代化国家的内在要求。推动经济社会发展绿色化、低碳化是高质量发展的关键环节，因此保护与发展不能简单对立。","sourceBlockIds":["block:politics-toc-v2-u011:b002","block:politics-toc-v2-u011:b003","block:politics-toc-v2-u011:b004","block:politics-toc-v2-u011:b012"],"emphasis":[{"part":"text","quote":"绿色化、低碳化","occurrence":1,"role":"key"},{"part":"text","quote":"高质量发展","occurrence":1,"role":"key"}],"kind":"explanation","id":"CULTUREECO-03-body-1"},{"label":"从方式与方针理解治理","text":"生态环境问题归根到底是经济发展方式和生活方式问题，绿色低碳发展是治本之策。要坚持节约优先、保护优先、自然恢复为主，理解“绿水青山就是金山银山”的发展理念。这里不仅看已经产生的污染，还要看生产生活方式及保护方针。","sourceBlockIds":["block:politics-toc-v2-u011:b005","block:politics-toc-v2-u011:b006","block:politics-toc-v2-u011:b007","block:politics-toc-v2-u011:b008"],"emphasis":[{"part":"text","quote":"经济发展方式和生活方式","occurrence":1,"role":"key"},{"part":"text","quote":"节约优先、保护优先、自然恢复为主","occurrence":1,"role":"key"}],"kind":"explanation","id":"CULTUREECO-03-body-2"},{"label":"发展与保护相互兼顾","text":"生态保护与经济发展不是简单对立，绿色发展强调在保护中发展、在发展中保护。不能把治本之策误读为所有地方套同一种具体措施。","sourceBlockIds":["block:politics-toc-v2-u011:b008","block:politics-toc-v2-u011:b012"],"emphasis":[],"kind":"boundary","id":"CULTUREECO-03-boundary"},{"label":"本节结论","text":"生态文明把保护自然纳入现代化与高质量发展，通过发展方式、生活方式和保护方针理解系统治理。","sourceBlockIds":["block:politics-toc-v2-u011:b002","block:politics-toc-v2-u011:b003","block:politics-toc-v2-u011:b004","block:politics-toc-v2-u011:b006","block:politics-toc-v2-u011:b007","block:politics-toc-v2-u011:b008"],"emphasis":[],"kind":"recap","id":"CULTUREECO-03-recap"}]},{"title":"生态目标与保护安排怎样分层","question":"碳目标、三条控制线和自然保护地体系各管什么？","objectives":["区分时间目标、控制线与保护地体系"],"scopeLimit":"本节只解释“碳目标、三条控制线和自然保护地体系各管什么”；不把文化与生态文明伪造成直接因果关系。","reflection":{"prompt":"碳目标、三条控制线和自然保护地体系各管什么？","answer":"碳达峰、碳中和是分阶段的时间目标；三条控制线划定国土空间开发保护边界；自然保护地体系组织重要自然生态空间的保护。","sourceBlockIds":["block:politics-toc-v2-u009:b012","block:politics-toc-v2-u011:b003","block:politics-toc-v2-u011:b007","block:politics-toc-v2-u011:b009","block:politics-toc-v2-u011:b010","block:politics-toc-v2-u011:b011"]},"id":"CULTUREECO-04","groupId":"cultureeco","previousLessonId":"CULTUREECO-03","nextLessonId":null,"transition":"下一主题：党的建设与自我革命","corePromises":[{"quote":"2030年前","sourceBlockIds":["block:politics-toc-v2-u011:b009"]},{"quote":"2060年前","sourceBlockIds":["block:politics-toc-v2-u011:b009"]},{"quote":"生态保护红线、永久基本农田、城镇开发边界","sourceBlockIds":["block:politics-toc-v2-u011:b010","block:politics-toc-v2-u011:b011"]},{"quote":"国家公园","sourceBlockIds":["block:politics-toc-v2-u011:b010","block:politics-toc-v2-u011:b011"]},{"quote":"自然保护区","sourceBlockIds":["block:politics-toc-v2-u011:b010","block:politics-toc-v2-u011:b011"]},{"quote":"自然公园","sourceBlockIds":["block:politics-toc-v2-u011:b010","block:politics-toc-v2-u011:b011"]}],"primaryUnitIds":["politics-toc-v2-u011"],"parts":[{"label":"时间目标不是当前结果","text":"现有来源列出的目标是力争2030年前实现碳达峰，努力争取2060年前实现碳中和。这里按来源认识两个时间目标，不将它们写成已经实现，也不在本主题补写原文未提供的核算方法或最新进展。","sourceBlockIds":["block:politics-toc-v2-u011:b009"],"emphasis":[{"part":"text","quote":"2030年前","occurrence":1,"role":"key"},{"part":"text","quote":"2060年前","occurrence":1,"role":"key"}],"kind":"explanation","id":"CULTUREECO-04-body-1"},{"label":"空间保护有不同安排","text":"三条控制线是生态保护红线、永久基本农田、城镇开发边界；自然保护地体系则以国家公园为主体、自然保护区为基础、各类自然公园为补充。前者是三类空间控制边界，后者说明保护地体系组成，不能因都涉及空间就当成同一张清单。","sourceBlockIds":["block:politics-toc-v2-u011:b010","block:politics-toc-v2-u011:b011"],"emphasis":[{"part":"text","quote":"生态保护红线、永久基本农田、城镇开发边界","occurrence":1,"role":"key"},{"part":"text","quote":"国家公园","occurrence":1,"role":"key"},{"part":"text","quote":"自然保护区","occurrence":1,"role":"key"},{"part":"text","quote":"自然公园","occurrence":1,"role":"key"}],"kind":"explanation","id":"CULTUREECO-04-body-2"},{"label":"分清概念层次","text":"绿色发展理念、时间目标、空间控制与保护地体系各有职责。原文没有详细解释碳达峰、碳中和的技术机制，本小节只承诺识别目标，不冒充技术课程。","sourceBlockIds":["block:politics-toc-v2-u011:b005","block:politics-toc-v2-u011:b009","block:politics-toc-v2-u011:b010","block:politics-toc-v2-u011:b011"],"emphasis":[],"kind":"boundary","id":"CULTUREECO-04-boundary"},{"label":"本主题小结","text":"本主题分别从方向、人民立场与效益理解文化建设，从发展方式、时间目标和空间安排理解生态文明，二者都属于现代化全景中的重要内容。","sourceBlockIds":["block:politics-toc-v2-u009:b012","block:politics-toc-v2-u011:b003","block:politics-toc-v2-u011:b007","block:politics-toc-v2-u011:b009","block:politics-toc-v2-u011:b010","block:politics-toc-v2-u011:b011"],"emphasis":[],"kind":"recap","id":"CULTUREECO-04-recap"}]},{"title":"党的建设怎样抓住主线与统领","question":"为什么全面从严治党不能等同于反腐败？","objectives":["理解总要求中的主线、统领、根基与着力点"],"scopeLimit":"本节只解释“为什么全面从严治党不能等同于反腐败”；九项实践要求的细目保留查阅。","reflection":{"prompt":"为什么全面从严治党不能等同于反腐败？","answer":"全面从严治党还包括政治、思想、组织、作风、纪律和制度建设等整体要求，反腐败是其中的重要部分，不能替代全部党的建设。","sourceBlockIds":["block:politics-toc-v2-u014:b003","block:politics-toc-v2-u014:b006","block:politics-toc-v2-u014:b011","block:politics-toc-v2-u014:b040"]},"id":"PARTY-01","groupId":"party","previousLessonId":null,"nextLessonId":"PARTY-02","transition":"下一节：组织 作风 纪律怎样相互支撑","corePromises":[{"quote":"长期执政能力建设","sourceBlockIds":["block:politics-toc-v2-u014:b002","block:politics-toc-v2-u014:b003"]},{"quote":"政治建设为统领","sourceBlockIds":["block:politics-toc-v2-u014:b002","block:politics-toc-v2-u014:b003"]},{"quote":"理想信念宗旨","sourceBlockIds":["block:politics-toc-v2-u014:b002","block:politics-toc-v2-u014:b003"]},{"quote":"制度建设贯穿其中","sourceBlockIds":["block:politics-toc-v2-u014:b003","block:politics-toc-v2-u014:b006","block:politics-toc-v2-u014:b007","block:politics-toc-v2-u014:b011","block:politics-toc-v2-u014:b012","block:politics-toc-v2-u014:b013"]},{"quote":"根本性建设","sourceBlockIds":["block:politics-toc-v2-u014:b003","block:politics-toc-v2-u014:b006","block:politics-toc-v2-u014:b007","block:politics-toc-v2-u014:b011","block:politics-toc-v2-u014:b012","block:politics-toc-v2-u014:b013"]},{"quote":"基础性建设","sourceBlockIds":["block:politics-toc-v2-u014:b003","block:politics-toc-v2-u014:b006","block:politics-toc-v2-u014:b007","block:politics-toc-v2-u014:b011","block:politics-toc-v2-u014:b012","block:politics-toc-v2-u014:b013"]}],"primaryUnitIds":["politics-toc-v2-u014"],"parts":[{"label":"从总要求读出结构","text":"全面从严治党是新时代党的建设的鲜明主题。总要求以加强长期执政能力建设、先进性和纯洁性建设为主线，以政治建设为统领，以坚定理想信念宗旨为根基，以调动全党积极性、主动性、创造性为着力点。四个定位各有对象，不可只背名称而随意对调。","sourceBlockIds":["block:politics-toc-v2-u014:b002","block:politics-toc-v2-u014:b003"],"emphasis":[{"part":"text","quote":"长期执政能力建设","occurrence":1,"role":"key"},{"part":"text","quote":"政治建设为统领","occurrence":1,"role":"key"},{"part":"text","quote":"理想信念宗旨","occurrence":1,"role":"key"}],"kind":"explanation","id":"PARTY-01-body-1"},{"label":"建设内容不止一种","text":"总要求全面推进政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进反腐败斗争。政治建设是根本性建设，首要任务涉及服从中央、党中央权威和集中统一领导；思想建设是基础性建设，以坚定理想信念为首要任务，以创新理论武装全党为根本任务。","sourceBlockIds":["block:politics-toc-v2-u014:b003","block:politics-toc-v2-u014:b006","block:politics-toc-v2-u014:b007","block:politics-toc-v2-u014:b011","block:politics-toc-v2-u014:b012","block:politics-toc-v2-u014:b013"],"emphasis":[{"part":"text","quote":"制度建设贯穿其中","occurrence":1,"role":"key"},{"part":"text","quote":"根本性建设","occurrence":1,"role":"key"},{"part":"text","quote":"基础性建设","occurrence":1,"role":"key"}],"kind":"explanation","id":"PARTY-01-body-2"},{"label":"统领与基础不能互换","text":"政治建设与思想建设各有定位，全面从严治党覆盖建设各方面和全过程，反腐败只是其中必须理解的重要内容，不能直接等号替代整体。","sourceBlockIds":["block:politics-toc-v2-u014:b006","block:politics-toc-v2-u014:b011","block:politics-toc-v2-u014:b040"],"emphasis":[],"kind":"boundary","id":"PARTY-01-boundary"},{"label":"本节结论","text":"全面从严治党以主线、统领、根基和着力点组织总体要求，各项建设和制度建设共同构成整体布局。","sourceBlockIds":["block:politics-toc-v2-u014:b003","block:politics-toc-v2-u014:b006","block:politics-toc-v2-u014:b011","block:politics-toc-v2-u014:b040"],"emphasis":[],"kind":"recap","id":"PARTY-01-recap"}]},{"title":"组织 作风 纪律怎样相互支撑","question":"抓关键少数与保持群众联系为什么都要讲？","objectives":["分清组织重点、群众联系与纪律制度保障"],"scopeLimit":"本节只解释“抓关键少数与保持群众联系为什么都要讲”；九项实践要求的细目保留查阅。","reflection":{"prompt":"抓关键少数与保持群众联系为什么都要讲？","answer":"抓关键少数突出领导干部的示范和责任，保持群众联系处理党的作风与人民立场。组织、作风、纪律和制度相互支撑，缺一不可。","sourceBlockIds":["block:politics-toc-v2-u014:b015","block:politics-toc-v2-u014:b019","block:politics-toc-v2-u014:b021","block:politics-toc-v2-u014:b024","block:politics-toc-v2-u014:b026","block:politics-toc-v2-u014:b029"]},"id":"PARTY-02","groupId":"party","previousLessonId":"PARTY-01","nextLessonId":"PARTY-03","transition":"下一节：反腐败怎样连到自我革命","corePromises":[{"quote":"组织体系建设","sourceBlockIds":["block:politics-toc-v2-u014:b015","block:politics-toc-v2-u014:b016","block:politics-toc-v2-u014:b017"]},{"quote":"关键少数","sourceBlockIds":["block:politics-toc-v2-u014:b015","block:politics-toc-v2-u014:b016","block:politics-toc-v2-u014:b017"]},{"quote":"血肉联系","sourceBlockIds":["block:politics-toc-v2-u014:b019","block:politics-toc-v2-u014:b020","block:politics-toc-v2-u014:b021","block:politics-toc-v2-u014:b023","block:politics-toc-v2-u014:b024"]},{"quote":"纪律建设","sourceBlockIds":["block:politics-toc-v2-u014:b019","block:politics-toc-v2-u014:b020","block:politics-toc-v2-u014:b021","block:politics-toc-v2-u014:b023","block:politics-toc-v2-u014:b024"]},{"quote":"党性、党风、党纪","sourceBlockIds":["block:politics-toc-v2-u014:b019","block:politics-toc-v2-u014:b020","block:politics-toc-v2-u014:b021","block:politics-toc-v2-u014:b023","block:politics-toc-v2-u014:b024"]}],"primaryUnitIds":["politics-toc-v2-u014"],"parts":[{"label":"组织建设抓住重点与关键","text":"组织路线以组织体系建设为重点，建设忠诚干净担当的高素质干部队伍是关键。从严治党要抓住领导干部这个“关键少数”，严密组织体系同时强调党中央权威、集中统一领导和两个维护。突出关键，不表示其他组织和成员可以不受要求。","sourceBlockIds":["block:politics-toc-v2-u014:b015","block:politics-toc-v2-u014:b016","block:politics-toc-v2-u014:b017"],"emphasis":[{"part":"text","quote":"组织体系建设","occurrence":1,"role":"key"},{"part":"text","quote":"关键少数","occurrence":1,"role":"key"}],"kind":"explanation","id":"PARTY-02-body-1"},{"label":"作风与纪律不是同一件事","text":"作风问题核心是保持党同人民群众的血肉联系，密切联系群众是最大政治优势，脱离群众是执政后的最大危险。纪律建设是全面从严治党的治本之策，制度则提供长远、根本保障。党性、党风、党纪是有机整体，分别体现根本、表现、保障的关系。","sourceBlockIds":["block:politics-toc-v2-u014:b019","block:politics-toc-v2-u014:b020","block:politics-toc-v2-u014:b021","block:politics-toc-v2-u014:b023","block:politics-toc-v2-u014:b024"],"emphasis":[{"part":"text","quote":"血肉联系","occurrence":1,"role":"key"},{"part":"text","quote":"纪律建设","occurrence":1,"role":"key"},{"part":"text","quote":"党性、党风、党纪","occurrence":1,"role":"key"}],"kind":"explanation","id":"PARTY-02-body-2"},{"label":"关键少数不替代全面要求","text":"组织建设的重点与干部队伍的关键地位不同于只管理少数人；制度保障和纪律要求也不能替代群众联系。本小节按职责归纳，不新增正式建设分类。","sourceBlockIds":["block:politics-toc-v2-u014:b003","block:politics-toc-v2-u014:b015","block:politics-toc-v2-u014:b017","block:politics-toc-v2-u014:b019","block:politics-toc-v2-u014:b021","block:politics-toc-v2-u014:b024"],"emphasis":[],"kind":"boundary","id":"PARTY-02-boundary"},{"label":"本节结论","text":"组织建设关注体系和干部，作风建设关注群众联系，纪律建设与制度建设提供约束和保障，四者相互支撑。","sourceBlockIds":["block:politics-toc-v2-u014:b015","block:politics-toc-v2-u014:b019","block:politics-toc-v2-u014:b021","block:politics-toc-v2-u014:b024","block:politics-toc-v2-u014:b026","block:politics-toc-v2-u014:b029"],"emphasis":[],"kind":"recap","id":"PARTY-02-recap"}]},{"title":"反腐败怎样连到自我革命","question":"为什么不敢腐、不能腐、不想腐要一体推进？","objectives":["理解三不腐的联系及自我革命的位置"],"scopeLimit":"本节只解释“为什么不敢腐、不能腐、不想腐要一体推进”；九项实践要求的细目保留查阅。","reflection":{"prompt":"为什么不敢腐、不能腐、不想腐要一体推进？","answer":"不敢腐强化震慑，不能腐强化制度约束，不想腐增强思想自觉。三者分别作用于行为、制度和思想，需要同时推进、共同发力。","sourceBlockIds":["block:politics-toc-v2-u014:b003","block:politics-toc-v2-u014:b021","block:politics-toc-v2-u014:b024","block:politics-toc-v2-u014:b027","block:politics-toc-v2-u014:b029","block:politics-toc-v2-u014:b040"]},"id":"PARTY-03","groupId":"party","previousLessonId":"PARTY-02","nextLessonId":null,"transition":"下一主题：总体安全与国防","corePromises":[{"quote":"不敢腐、不能腐、不想腐","sourceBlockIds":["block:politics-toc-v2-u014:b026","block:politics-toc-v2-u014:b027"]},{"quote":"震慑","sourceBlockIds":["block:politics-toc-v2-u014:b026","block:politics-toc-v2-u014:b027"]},{"quote":"制度约束","sourceBlockIds":["block:politics-toc-v2-u014:b026","block:politics-toc-v2-u014:b027"]},{"quote":"思想教育","sourceBlockIds":["block:politics-toc-v2-u014:b026","block:politics-toc-v2-u014:b027"]},{"quote":"跳出历史周期率","sourceBlockIds":["block:politics-toc-v2-u014:b029","block:politics-toc-v2-u014:b031","block:politics-toc-v2-u014:b032","block:politics-toc-v2-u014:b033","block:politics-toc-v2-u014:b034","block:politics-toc-v2-u014:b035","block:politics-toc-v2-u014:b036","block:politics-toc-v2-u014:b037","block:politics-toc-v2-u014:b038","block:politics-toc-v2-u014:b039"]},{"quote":"自我监督和人民监督","sourceBlockIds":["block:politics-toc-v2-u014:b029","block:politics-toc-v2-u014:b031","block:politics-toc-v2-u014:b032","block:politics-toc-v2-u014:b033","block:politics-toc-v2-u014:b034","block:politics-toc-v2-u014:b035","block:politics-toc-v2-u014:b036","block:politics-toc-v2-u014:b037","block:politics-toc-v2-u014:b038","block:politics-toc-v2-u014:b039"]}],"primaryUnitIds":["politics-toc-v2-u014"],"parts":[{"label":"三不腐分别依靠什么","text":"腐败是党长期执政面临的最大威胁，反腐败是最彻底的自我革命。原文要求不敢腐、不能腐、不想腐一体推进，分别连接强大震慑、刚性制度约束、思想教育优势；一体推进不是三者选一，也不是只靠某一个环节替代全部。","sourceBlockIds":["block:politics-toc-v2-u014:b026","block:politics-toc-v2-u014:b027"],"emphasis":[{"part":"text","quote":"不敢腐、不能腐、不想腐","occurrence":1,"role":"key"},{"part":"text","quote":"震慑","occurrence":1,"role":"key"},{"part":"text","quote":"制度约束","occurrence":1,"role":"key"},{"part":"text","quote":"思想教育","occurrence":1,"role":"key"}],"kind":"explanation","id":"PARTY-03-body-1"},{"label":"自我革命放在更大结构中","text":"党的自我革命是跳出历史周期率的第二个答案。原文的实践要求同时涉及集中统一领导、社会革命、理论遵循、战略目标、独有难题、从严治党体系、组织队伍、正风肃纪反腐、自我监督和人民监督。这些说明自我革命不是单次整顿行为，完整九项固定表述可查阅。","sourceBlockIds":["block:politics-toc-v2-u014:b029","block:politics-toc-v2-u014:b031","block:politics-toc-v2-u014:b032","block:politics-toc-v2-u014:b033","block:politics-toc-v2-u014:b034","block:politics-toc-v2-u014:b035","block:politics-toc-v2-u014:b036","block:politics-toc-v2-u014:b037","block:politics-toc-v2-u014:b038","block:politics-toc-v2-u014:b039"],"emphasis":[{"part":"text","quote":"跳出历史周期率","occurrence":1,"role":"key"},{"part":"text","quote":"自我监督和人民监督","occurrence":1,"role":"key"}],"kind":"explanation","id":"PARTY-03-body-2"},{"label":"区分本次目标与完整清单","text":"本次讲清三不腐的职责与自我革命的整体位置，不声称已逐项解释九项实践要求。全面从严治党不能缩成反腐败，自我革命也不能只由一个行动概括。","sourceBlockIds":["block:politics-toc-v2-u014:b029","block:politics-toc-v2-u014:b030","block:politics-toc-v2-u014:b040"],"emphasis":[],"kind":"boundary","id":"PARTY-03-boundary"},{"label":"本主题小结","text":"本主题从建设总要求、各项建设到反腐败和自我革命，说明全面从严治党覆盖多方面和全过程，三不腐需要相互配合。","sourceBlockIds":["block:politics-toc-v2-u014:b003","block:politics-toc-v2-u014:b021","block:politics-toc-v2-u014:b024","block:politics-toc-v2-u014:b027","block:politics-toc-v2-u014:b029","block:politics-toc-v2-u014:b040"],"emphasis":[],"kind":"recap","id":"PARTY-03-recap"}]},{"title":"总体国家安全为什么突出总体","question":"人民安全、政治安全与经济安全分别怎样定位？","objectives":["理解安全结构中的不同定位"],"scopeLimit":"本节只解释“人民安全、政治安全与经济安全分别怎样定位”；按现有来源认识目标安排。","reflection":{"prompt":"人民安全、政治安全与经济安全分别怎样定位？","answer":"人民安全是宗旨，政治安全是根本，经济安全是基础。三者处在总体国家安全结构的不同位置，需要统筹而不能互换。","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b004","block:politics-toc-v2-u016:b008","block:politics-toc-v2-u016:b012"]},"id":"SECURITY-01","groupId":"security","previousLessonId":null,"nextLessonId":"SECURITY-02","transition":"下一节：安全任务为什么强调事前防范","corePromises":[{"quote":"人民安全为宗旨","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b004","block:politics-toc-v2-u016:b012"]},{"quote":"政治安全为根本","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b004","block:politics-toc-v2-u016:b012"]},{"quote":"经济安全为基础","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b004","block:politics-toc-v2-u016:b012"]},{"quote":"政权安全和制度安全","sourceBlockIds":["block:politics-toc-v2-u016:b005","block:politics-toc-v2-u016:b006","block:politics-toc-v2-u016:b007"]},{"quote":"人民安全宗旨","sourceBlockIds":["block:politics-toc-v2-u016:b005","block:politics-toc-v2-u016:b006","block:politics-toc-v2-u016:b007"]}],"primaryUnitIds":["politics-toc-v2-u016"],"parts":[{"label":"总体不是单一领域","text":"总体国家安全观的关键和灵魂是“总体”，覆盖多领域、强调系统统筹。它以国家利益为准则，以人民安全为宗旨，以政治安全为根本，以经济安全为基础，以军事、科技、文化、社会安全为保障，以促进国际安全为依托。不同定位共同组成结构，不是安全概念只有一个领域。","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b004","block:politics-toc-v2-u016:b012"],"emphasis":[{"part":"text","quote":"人民安全为宗旨","occurrence":1,"role":"key"},{"part":"text","quote":"政治安全为根本","occurrence":1,"role":"key"},{"part":"text","quote":"经济安全为基础","occurrence":1,"role":"key"}],"kind":"explanation","id":"SECURITY-01-body-1"},{"label":"根本与宗旨各有所指","text":"国家核心利益涉及政权、主权、统一和领土完整、人民福祉、经济社会可持续发展。政治安全核心是政权安全和制度安全，最根本涉及维护党的领导和执政地位、维护中国特色社会主义制度；践行人民安全宗旨则明确根本立场。不能把宗旨、根本和基础换位。","sourceBlockIds":["block:politics-toc-v2-u016:b005","block:politics-toc-v2-u016:b006","block:politics-toc-v2-u016:b007"],"emphasis":[{"part":"text","quote":"政权安全和制度安全","occurrence":1,"role":"key"},{"part":"text","quote":"人民安全宗旨","occurrence":1,"role":"key"}],"kind":"explanation","id":"SECURITY-01-body-2"},{"label":"总体不等于平均用力","text":"多领域统筹仍保留政治安全的首位和不同方面各自定位，不是每个领域用同样措施，也不是单一军事或国土安全。","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b006","block:politics-toc-v2-u016:b012"],"emphasis":[],"kind":"boundary","id":"SECURITY-01-boundary"},{"label":"本节结论","text":"总体国家安全观以人民安全为宗旨、政治安全为根本、经济安全为基础，并保留军事科技文化社会安全等保障和国际安全依托。","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b004","block:politics-toc-v2-u016:b008","block:politics-toc-v2-u016:b012"],"emphasis":[],"kind":"recap","id":"SECURITY-01-recap"}]},{"title":"安全任务为什么强调事前防范","question":"防范化解风险和公共安全预防各强调什么？","objectives":["理解风险任务、领导保证与公共安全的联系"],"scopeLimit":"本节只解释“防范化解风险和公共安全预防各强调什么”；按现有来源认识目标安排。","reflection":{"prompt":"防范化解风险和公共安全预防各强调什么？","answer":"防范化解重大风险强调识别和处置影响全局的风险，公共安全预防强调把防线前移、减少事故和危害。二者都重视事前，但对象和任务不同。","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b008","block:politics-toc-v2-u016:b009","block:politics-toc-v2-u016:b010","block:politics-toc-v2-u017:b002"]},"id":"SECURITY-02","groupId":"security","previousLessonId":"SECURITY-01","nextLessonId":"SECURITY-03","transition":"下一节：强军目标怎样连到原则与阶段","corePromises":[{"quote":"防范化解国家安全风险","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b008"]},{"quote":"全局性风险","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b008"]},{"quote":"根本保证","sourceBlockIds":["block:politics-toc-v2-u016:b009","block:politics-toc-v2-u016:b010","block:politics-toc-v2-u016:b011"]},{"quote":"事前预防","sourceBlockIds":["block:politics-toc-v2-u016:b009","block:politics-toc-v2-u016:b010","block:politics-toc-v2-u016:b011"]}],"primaryUnitIds":["politics-toc-v2-u016"],"parts":[{"label":"中心任务面向风险","text":"防范化解国家安全风险是新时代国家安全的中心任务，重点防控可能迟滞或中断民族复兴进程的全局性风险。它与上一小节的多领域结构相接：既然安全存在联系，就不能只等某一个局部出了问题才理解风险。","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b008"],"emphasis":[{"part":"text","quote":"防范化解国家安全风险","occurrence":1,"role":"key"},{"part":"text","quote":"全局性风险","occurrence":1,"role":"key"}],"kind":"explanation","id":"SECURITY-02-body-1"},{"label":"领导与治理方式相衔接","text":"加强党对国家安全工作的绝对领导是根本保证。公共安全则要完善体系，推动治理模式向事前预防转型。原文还将4月15日列为全民国家安全教育日；日期是知识查阅点，不能用记住日期替代理解安全结构和任务。","sourceBlockIds":["block:politics-toc-v2-u016:b009","block:politics-toc-v2-u016:b010","block:politics-toc-v2-u016:b011"],"emphasis":[{"part":"text","quote":"根本保证","occurrence":1,"role":"key"},{"part":"text","quote":"事前预防","occurrence":1,"role":"key"}],"kind":"explanation","id":"SECURITY-02-body-2"},{"label":"国家安全不缩成公共安全","text":"公共安全预防是相关治理内容，不等于总体国家安全只有公共安全。风险重点也不改变前述人民安全、政治安全、经济安全的不同定位。","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b008","block:politics-toc-v2-u016:b010","block:politics-toc-v2-u016:b012"],"emphasis":[],"kind":"boundary","id":"SECURITY-02-boundary"},{"label":"本节结论","text":"总体国家安全观提供结构，风险防范明确任务，党的领导提供保证，公共安全强调把预防关口前移。","sourceBlockIds":["block:politics-toc-v2-u016:b003","block:politics-toc-v2-u016:b008","block:politics-toc-v2-u016:b009","block:politics-toc-v2-u016:b010","block:politics-toc-v2-u017:b002"],"emphasis":[],"kind":"recap","id":"SECURITY-02-recap"}]},{"title":"强军目标怎样连到原则与阶段","question":"强军目标、绝对领导与现代化阶段分别回答什么？","objectives":["理解军队建设的目标、根本原则与时间安排"],"scopeLimit":"本节只解释“强军目标、绝对领导与现代化阶段分别回答什么”；按现有来源认识目标安排。","reflection":{"prompt":"强军目标、绝对领导与现代化阶段分别回答什么？","answer":"强军目标回答建设什么样的人民军队，党对人民军队的绝对领导回答根本原则和制度保证，现代化阶段回答建设进程与时间安排。","sourceBlockIds":["block:politics-toc-v2-u016:b012","block:politics-toc-v2-u017:b002","block:politics-toc-v2-u017:b004","block:politics-toc-v2-u017:b005","block:politics-toc-v2-u017:b006","block:politics-toc-v2-u017:b007","block:politics-toc-v2-u017:b008","block:politics-toc-v2-u017:b011"]},"id":"SECURITY-03","groupId":"security","previousLessonId":"SECURITY-02","nextLessonId":null,"transition":"下一主题：统一与对外关系","corePromises":[{"quote":"听党指挥、能打胜仗、作风优良","sourceBlockIds":["block:politics-toc-v2-u017:b002","block:politics-toc-v2-u017:b008","block:politics-toc-v2-u017:b011"]},{"quote":"军委主席负责制","sourceBlockIds":["block:politics-toc-v2-u017:b002","block:politics-toc-v2-u017:b008","block:politics-toc-v2-u017:b011"]},{"quote":"2027年","sourceBlockIds":["block:politics-toc-v2-u017:b004","block:politics-toc-v2-u017:b005","block:politics-toc-v2-u017:b006","block:politics-toc-v2-u017:b007","block:politics-toc-v2-u017:b010"]},{"quote":"2035年","sourceBlockIds":["block:politics-toc-v2-u017:b004","block:politics-toc-v2-u017:b005","block:politics-toc-v2-u017:b006","block:politics-toc-v2-u017:b007","block:politics-toc-v2-u017:b010"]},{"quote":"本世纪中叶","sourceBlockIds":["block:politics-toc-v2-u017:b004","block:politics-toc-v2-u017:b005","block:politics-toc-v2-u017:b006","block:politics-toc-v2-u017:b007","block:politics-toc-v2-u017:b010"]},{"quote":"战斗力","sourceBlockIds":["block:politics-toc-v2-u017:b004","block:politics-toc-v2-u017:b005","block:politics-toc-v2-u017:b006","block:politics-toc-v2-u017:b007","block:politics-toc-v2-u017:b010"]}],"primaryUnitIds":["politics-toc-v2-u017"],"parts":[{"label":"目标与根本原则","text":"新时代强军目标是建设听党指挥、能打胜仗、作风优良的人民军队，建设世界一流军队。党对人民军队的绝对领导是建军之本、强军之魂；军委主席负责制是坚持绝对领导的根本制度和根本实现形式。目标说明要建成什么样，原则制度说明必须怎样坚持领导。","sourceBlockIds":["block:politics-toc-v2-u017:b002","block:politics-toc-v2-u017:b008","block:politics-toc-v2-u017:b011"],"emphasis":[{"part":"text","quote":"听党指挥、能打胜仗、作风优良","occurrence":1,"role":"key"},{"part":"text","quote":"军委主席负责制","occurrence":1,"role":"key"}],"kind":"explanation","id":"SECURITY-03-body-1"},{"label":"阶段与建设方式","text":"原文战略安排为2027年建军一百年奋斗目标、2035年基本实现国防和军队现代化、本世纪中叶全面建成世界一流军队。这些是目标节点。建设中坚持政治建军、改革强军、科技强军、人才强军、依法治军，牢固树立战斗力这个唯一的根本标准。","sourceBlockIds":["block:politics-toc-v2-u017:b004","block:politics-toc-v2-u017:b005","block:politics-toc-v2-u017:b006","block:politics-toc-v2-u017:b007","block:politics-toc-v2-u017:b010"],"emphasis":[{"part":"text","quote":"2027年","occurrence":1,"role":"key"},{"part":"text","quote":"2035年","occurrence":1,"role":"key"},{"part":"text","quote":"本世纪中叶","occurrence":1,"role":"key"},{"part":"text","quote":"战斗力","occurrence":1,"role":"key"}],"kind":"explanation","id":"SECURITY-03-body-2"},{"label":"不把阶段写成已实现结果","text":"这里按来源认识战略目标，不判断当前完成进度。党对军队的绝对领导是根本原则和制度，不能与一般行政领导关系混同；历史形成过程保留查阅。","sourceBlockIds":["block:politics-toc-v2-u017:b004","block:politics-toc-v2-u017:b005","block:politics-toc-v2-u017:b006","block:politics-toc-v2-u017:b009","block:politics-toc-v2-u017:b012"],"emphasis":[],"kind":"boundary","id":"SECURITY-03-boundary"},{"label":"本主题小结","text":"本主题从总体结构、风险防范与公共安全，再到国防和军队建设理解安全领域；国防军队是重要内容，但不能替代总体国家安全。","sourceBlockIds":["block:politics-toc-v2-u016:b012","block:politics-toc-v2-u017:b002","block:politics-toc-v2-u017:b004","block:politics-toc-v2-u017:b005","block:politics-toc-v2-u017:b006","block:politics-toc-v2-u017:b007","block:politics-toc-v2-u017:b008","block:politics-toc-v2-u017:b011"],"emphasis":[],"kind":"recap","id":"SECURITY-03-recap"}]},{"title":"一国与两制为什么不能倒置","question":"一国两制中的两部分是什么关系？","objectives":["理解前提、最高原则及实践关系"],"scopeLimit":"本节只解释“一国两制中的两部分是什么关系”；不补写时事进展。","reflection":{"prompt":"一国两制中的两部分是什么关系？","answer":"“一国”是实行“两制”的前提和基础，“两制”是在“一国”之内的制度安排；维护国家主权、安全、发展利益是最高原则，顺序不能倒置。","sourceBlockIds":["block:politics-toc-v2-u018:b003","block:politics-toc-v2-u018:b004","block:politics-toc-v2-u018:b005","block:politics-toc-v2-u018:b006","block:politics-toc-v2-u018:b015"]},"id":"UNITYFOREIGN-01","groupId":"unityforeign","previousLessonId":null,"nextLessonId":"UNITYFOREIGN-02","transition":"下一节：推进统一的方略怎样分清职责","corePromises":[{"quote":"前提和基础","sourceBlockIds":["block:politics-toc-v2-u018:b003","block:politics-toc-v2-u018:b015"]},{"quote":"国家主体实行社会主义制度","sourceBlockIds":["block:politics-toc-v2-u018:b003","block:politics-toc-v2-u018:b015"]},{"quote":"国家主权、安全、发展利益","sourceBlockIds":["block:politics-toc-v2-u018:b004","block:politics-toc-v2-u018:b005","block:politics-toc-v2-u018:b006","block:politics-toc-v2-u018:b007"]},{"quote":"全面管治权","sourceBlockIds":["block:politics-toc-v2-u018:b004","block:politics-toc-v2-u018:b005","block:politics-toc-v2-u018:b006","block:politics-toc-v2-u018:b007"]}],"primaryUnitIds":["politics-toc-v2-u018"],"parts":[{"label":"先确定前提与制度安排","text":"“一国两制”是在统一国家内，国家主体实行社会主义制度，个别地区依法实行资本主义制度。“一国”是实行“两制”的前提和基础，两制从属和派生于一国，因此不能把二者读成相互独立、地位对等的安排。","sourceBlockIds":["block:politics-toc-v2-u018:b003","block:politics-toc-v2-u018:b015"],"emphasis":[{"part":"text","quote":"前提和基础","occurrence":1,"role":"key"},{"part":"text","quote":"国家主体实行社会主义制度","occurrence":1,"role":"key"}],"kind":"explanation","id":"UNITYFOREIGN-01-body-1"},{"label":"原则与实践分别认识","text":"一国两制的最高原则是维护国家主权、安全、发展利益。它的提出从解决台湾问题开始，实践中首先运用于解决香港、澳门问题；全面管治权是授权特别行政区高度自治的前提和基础。提出缘起、首先实践和权力关系各有对象。","sourceBlockIds":["block:politics-toc-v2-u018:b004","block:politics-toc-v2-u018:b005","block:politics-toc-v2-u018:b006","block:politics-toc-v2-u018:b007"],"emphasis":[{"part":"text","quote":"国家主权、安全、发展利益","occurrence":1,"role":"key"},{"part":"text","quote":"全面管治权","occurrence":1,"role":"key"}],"kind":"explanation","id":"UNITYFOREIGN-01-body-2"},{"label":"不能倒置前提关系","text":"高度自治并不取消全面管治权这一前提，两制也不取消一国。提出从解决台湾问题开始，实践首先用于香港、澳门；提出缘起与首先实践也要分别认识。","sourceBlockIds":["block:politics-toc-v2-u018:b003","block:politics-toc-v2-u018:b007","block:politics-toc-v2-u018:b015","block:politics-toc-v2-u018:b005","block:politics-toc-v2-u018:b006"],"emphasis":[],"kind":"boundary","id":"UNITYFOREIGN-01-boundary"},{"label":"本节结论","text":"“一国”是前提和基础，“两制”是制度安排，维护国家主权、安全、发展利益是最高原则，并需分清提出缘起和首先实践的地区。","sourceBlockIds":["block:politics-toc-v2-u018:b003","block:politics-toc-v2-u018:b004","block:politics-toc-v2-u018:b005","block:politics-toc-v2-u018:b006","block:politics-toc-v2-u018:b015"],"emphasis":[],"kind":"recap","id":"UNITYFOREIGN-01-recap"}]},{"title":"推进统一的方略怎样分清职责","question":"统一方略中不同定位为什么不能只记一个口号？","objectives":["认识根本保证、方针、基础、途径与动力"],"scopeLimit":"本节只解释“统一方略中不同定位为什么不能只记一个口号”；不补写时事进展。","reflection":{"prompt":"统一方略中不同定位为什么不能只记一个口号？","answer":"因为统一方略同时包含领导保证、基本方针、政治基础、实践途径、动力和支撑。只记一个口号会丢失不同定位及其相互关系。","sourceBlockIds":["block:politics-toc-v2-u018:b003","block:politics-toc-v2-u018:b009","block:politics-toc-v2-u018:b010","block:politics-toc-v2-u018:b011","block:politics-toc-v2-u018:b012","block:politics-toc-v2-u018:b013","block:politics-toc-v2-u018:b014"]},"id":"UNITYFOREIGN-02","groupId":"unityforeign","previousLessonId":"UNITYFOREIGN-01","nextLessonId":"UNITYFOREIGN-03","transition":"下一节：外交怎样连接关系建设与共同体目标","corePromises":[{"quote":"根本保证","sourceBlockIds":["block:politics-toc-v2-u018:b009","block:politics-toc-v2-u018:b010","block:politics-toc-v2-u018:b011"]},{"quote":"大政方针","sourceBlockIds":["block:politics-toc-v2-u018:b009","block:politics-toc-v2-u018:b010","block:politics-toc-v2-u018:b011"]},{"quote":"政治基础","sourceBlockIds":["block:politics-toc-v2-u018:b009","block:politics-toc-v2-u018:b010","block:politics-toc-v2-u018:b011"]},{"quote":"实践途径","sourceBlockIds":["block:politics-toc-v2-u018:b012","block:politics-toc-v2-u018:b013","block:politics-toc-v2-u018:b014"]},{"quote":"根本动力","sourceBlockIds":["block:politics-toc-v2-u018:b012","block:politics-toc-v2-u018:b013","block:politics-toc-v2-u018:b014"]},{"quote":"战略支撑","sourceBlockIds":["block:politics-toc-v2-u018:b012","block:politics-toc-v2-u018:b013","block:politics-toc-v2-u018:b014"]}],"primaryUnitIds":["politics-toc-v2-u018"],"parts":[{"label":"保证、方针与基础","text":"现有来源将党中央对对台工作的集中统一领导定位为根本保证，将和平统一、一国两制定位为大政方针，将一个中国原则和“九二共识”定位为政治基础。它们分别回答领导保证、基本方针与政治基础，不能将名称互换。","sourceBlockIds":["block:politics-toc-v2-u018:b009","block:politics-toc-v2-u018:b010","block:politics-toc-v2-u018:b011"],"emphasis":[{"part":"text","quote":"根本保证","occurrence":1,"role":"key"},{"part":"text","quote":"大政方针","occurrence":1,"role":"key"},{"part":"text","quote":"政治基础","occurrence":1,"role":"key"}],"kind":"explanation","id":"UNITYFOREIGN-02-body-1"},{"label":"途径、动力与支撑","text":"推动两岸关系和平发展、融合发展是实践途径；团结台湾同胞、争取台湾民心是根本动力；决不承诺放弃使用武力是战略支撑。六项定位一起读，才能看到方略并非只有一个表述；这些是不同定位，不是重新排出一套先后实施步骤。","sourceBlockIds":["block:politics-toc-v2-u018:b012","block:politics-toc-v2-u018:b013","block:politics-toc-v2-u018:b014"],"emphasis":[{"part":"text","quote":"实践途径","occurrence":1,"role":"key"},{"part":"text","quote":"根本动力","occurrence":1,"role":"key"},{"part":"text","quote":"战略支撑","occurrence":1,"role":"key"}],"kind":"explanation","id":"UNITYFOREIGN-02-body-2"},{"label":"保留各项对象","text":"实践途径不等于政治基础，根本动力也不等于根本保证。理解联系时保留原文六项的完整对象，不把方略改造成新的固定步骤。","sourceBlockIds":["block:politics-toc-v2-u018:b009","block:politics-toc-v2-u018:b010","block:politics-toc-v2-u018:b011","block:politics-toc-v2-u018:b012","block:politics-toc-v2-u018:b013","block:politics-toc-v2-u018:b014"],"emphasis":[],"kind":"boundary","id":"UNITYFOREIGN-02-boundary"},{"label":"本节结论","text":"统一方略从领导保证、方针和政治基础，到实践途径、动力与支撑构成整体。它与一国两制相连，接下来转向对外关系，二者是不同议题。","sourceBlockIds":["block:politics-toc-v2-u018:b003","block:politics-toc-v2-u018:b009","block:politics-toc-v2-u018:b010","block:politics-toc-v2-u018:b011","block:politics-toc-v2-u018:b012","block:politics-toc-v2-u018:b013","block:politics-toc-v2-u018:b014"],"emphasis":[],"kind":"recap","id":"UNITYFOREIGN-02-recap"}]},{"title":"外交怎样连接关系建设与共同体目标","question":"人类命运共同体是只有一个目标名称吗？","objectives":["理解总目标及实现路径等不同层次"],"scopeLimit":"本节只解释“人类命运共同体是只有一个目标名称吗”；不补写时事进展。","reflection":{"prompt":"人类命运共同体是只有一个目标名称吗？","answer":"不是。人类命运共同体还要放在不同关系对象、建设路径、基本遵循、战略支撑、引领作用和合作平台中理解，不能只剩一个目标名称。","sourceBlockIds":["block:politics-toc-v2-u019:b003","block:politics-toc-v2-u019:b004","block:politics-toc-v2-u019:b005","block:politics-toc-v2-u019:b006","block:politics-toc-v2-u019:b008","block:politics-toc-v2-u019:b009","block:politics-toc-v2-u019:b010"]},"id":"UNITYFOREIGN-03","groupId":"unityforeign","previousLessonId":"UNITYFOREIGN-02","nextLessonId":null,"transition":"本篇收束：把十四个主题放回新时代思想篇","corePromises":[{"quote":"周边","sourceBlockIds":["block:politics-toc-v2-u019:b003","block:politics-toc-v2-u019:b004","block:politics-toc-v2-u019:b005","block:politics-toc-v2-u019:b006"]},{"quote":"亲诚惠容","sourceBlockIds":["block:politics-toc-v2-u019:b003","block:politics-toc-v2-u019:b004","block:politics-toc-v2-u019:b005","block:politics-toc-v2-u019:b006"]},{"quote":"真实亲诚","sourceBlockIds":["block:politics-toc-v2-u019:b003","block:politics-toc-v2-u019:b004","block:politics-toc-v2-u019:b005","block:politics-toc-v2-u019:b006"]},{"quote":"持久和平、普遍安全、共同繁荣、开放包容、清洁美丽","sourceBlockIds":["block:politics-toc-v2-u019:b008","block:politics-toc-v2-u019:b009"]},{"quote":"共商共建共享","sourceBlockIds":["block:politics-toc-v2-u019:b008","block:politics-toc-v2-u019:b009"]},{"quote":"实践平台","sourceBlockIds":["block:politics-toc-v2-u019:b008","block:politics-toc-v2-u019:b009"]}],"primaryUnitIds":["politics-toc-v2-u019"],"parts":[{"label":"关系建设有不同对象","text":"中国特色大国外交在大国关系、周边外交、发展中国家合作和新型政党关系上分别有安排。原文强调周边置于外交全局首要位置、亲诚惠容与与邻为善以邻为伴，以及对发展中国家的真实亲诚理念和正确义利观。对象不同，不能压成一套完全相同的交往口号。","sourceBlockIds":["block:politics-toc-v2-u019:b003","block:politics-toc-v2-u019:b004","block:politics-toc-v2-u019:b005","block:politics-toc-v2-u019:b006"],"emphasis":[{"part":"text","quote":"周边","occurrence":1,"role":"key"},{"part":"text","quote":"亲诚惠容","occurrence":1,"role":"key"},{"part":"text","quote":"真实亲诚","occurrence":1,"role":"key"}],"kind":"explanation","id":"UNITYFOREIGN-03-body-1"},{"label":"共同体目标有具体结构","text":"推动构建人类命运共同体是总目标，努力建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界。它以共商共建共享全球治理为路径、全人类共同价值为遵循、新型国际关系为支撑，全球发展倡议、全球安全倡议、全球文明倡议为战略引领，高质量共建“一带一路”为实践平台。","sourceBlockIds":["block:politics-toc-v2-u019:b008","block:politics-toc-v2-u019:b009"],"emphasis":[{"part":"text","quote":"持久和平、普遍安全、共同繁荣、开放包容、清洁美丽","occurrence":1,"role":"key"},{"part":"text","quote":"共商共建共享","occurrence":1,"role":"key"},{"part":"text","quote":"实践平台","occurrence":1,"role":"key"}],"kind":"explanation","id":"UNITYFOREIGN-03-body-2"},{"label":"和平发展不等于放弃利益","text":"独立自主的和平外交政策不等于孤立主义，和平发展不等于放弃维护国家主权、安全、发展利益。本主题按来源说明结构，不声称覆盖全部外交议题。","sourceBlockIds":["block:politics-toc-v2-u019:b010"],"emphasis":[],"kind":"boundary","id":"UNITYFOREIGN-03-boundary"},{"label":"本主题小结","text":"本主题从国家统一、推进统一的方略到中国特色大国外交，分别理解国家内部统一和对外关系中的目标、路径与原则。","sourceBlockIds":["block:politics-toc-v2-u019:b003","block:politics-toc-v2-u019:b004","block:politics-toc-v2-u019:b005","block:politics-toc-v2-u019:b006","block:politics-toc-v2-u019:b008","block:politics-toc-v2-u019:b009","block:politics-toc-v2-u019:b010"],"emphasis":[],"kind":"recap","id":"UNITYFOREIGN-03-recap"}]},{"title":"组成部分与理论来源怎样区分","question":"三个组成部分、直接理论来源与两大发现是一回事吗？","objectives":["建立马克思主义的基本位置与学习方法"],"scopeLimit":"本节只解释“三个组成部分、直接理论来源与两大发现是一回事吗”；科学社会主义不作独立详细课程。","reflection":{"prompt":"三个组成部分、直接理论来源与两大发现是一回事吗？","answer":"不是。三个组成部分说明理论结构，直接理论来源说明思想来源，两大发现说明科学社会主义的重要理论基础；三者属于不同层次。","sourceBlockIds":["block:politics-toc-v2-u020:b003","block:politics-toc-v2-u020:b004","block:politics-toc-v2-u020:b005","block:politics-toc-v2-u020:b006","block:politics-toc-v2-u020:b009","block:politics-toc-v2-u020:b010"]},"id":"BASICS-01","groupId":"basics","previousLessonId":null,"nextLessonId":"BASICS-02","transition":"下一节：两组哲学分歧分别在问什么","corePromises":[{"quote":"马克思主义哲学、马克思主义政治经济学、科学社会主义","sourceBlockIds":["block:politics-toc-v2-u020:b002","block:politics-toc-v2-u020:b003","block:politics-toc-v2-u020:b004","block:politics-toc-v2-u020:b010"]},{"quote":"德国古典哲学","sourceBlockIds":["block:politics-toc-v2-u020:b002","block:politics-toc-v2-u020:b003","block:politics-toc-v2-u020:b004","block:politics-toc-v2-u020:b010"]},{"quote":"1848年","sourceBlockIds":["block:politics-toc-v2-u020:b002","block:politics-toc-v2-u020:b003","block:politics-toc-v2-u020:b004","block:politics-toc-v2-u020:b010"]},{"quote":"唯物史观和剩余价值学说","sourceBlockIds":["block:politics-toc-v2-u020:b005","block:politics-toc-v2-u020:b006","block:politics-toc-v2-u020:b007","block:politics-toc-v2-u020:b008","block:politics-toc-v2-u020:b009"]},{"quote":"理论联系实际","sourceBlockIds":["block:politics-toc-v2-u020:b005","block:politics-toc-v2-u020:b006","block:politics-toc-v2-u020:b007","block:politics-toc-v2-u020:b008","block:politics-toc-v2-u020:b009"]}],"primaryUnitIds":["politics-toc-v2-u020"],"parts":[{"label":"先看组成与来源","text":"马克思主义包括马克思主义哲学、马克思主义政治经济学、科学社会主义；直接理论来源是德国古典哲学、英国古典政治经济学、英法空想社会主义。组成回答理论包括什么，来源回答吸收了哪些思想成果，不能把两张清单互换。1848年《共产党宣言》发表标志其诞生。","sourceBlockIds":["block:politics-toc-v2-u020:b002","block:politics-toc-v2-u020:b003","block:politics-toc-v2-u020:b004","block:politics-toc-v2-u020:b010"],"emphasis":[{"part":"text","quote":"马克思主义哲学、马克思主义政治经济学、科学社会主义","occurrence":1,"role":"key"},{"part":"text","quote":"德国古典哲学","occurrence":1,"role":"key"},{"part":"text","quote":"1848年","occurrence":1,"role":"key"}],"kind":"explanation","id":"BASICS-01-body-1"},{"label":"发现与学习方法各有作用","text":"马克思的两大发现是唯物史观和剩余价值学说。理论特征是以实践为基础的科学性和革命性的统一，理论品质是与时俱进，活的灵魂是具体问题具体分析，根本学习方法是理论联系实际。这里不把几个定位换成互相替代的标签。","sourceBlockIds":["block:politics-toc-v2-u020:b005","block:politics-toc-v2-u020:b006","block:politics-toc-v2-u020:b007","block:politics-toc-v2-u020:b008","block:politics-toc-v2-u020:b009"],"emphasis":[{"part":"text","quote":"唯物史观和剩余价值学说","occurrence":1,"role":"key"},{"part":"text","quote":"理论联系实际","occurrence":1,"role":"key"}],"kind":"explanation","id":"BASICS-01-body-2"},{"label":"当前范围先说明","text":"科学社会主义是组成部分，其理论基础是唯物史观和剩余价值学说，思想来源是英法空想社会主义。但当前材料没有独立详细课程，本路线只说明位置，不假装三个部分都已系统展开。","sourceBlockIds":["block:politics-toc-v2-u020:b003","block:politics-toc-v2-u020:b005","block:politics-toc-v2-u020:b010"],"emphasis":[],"kind":"boundary","id":"BASICS-01-boundary"},{"label":"本节结论","text":"先分清组成、来源、发现与方法，再从哲学基本问题开始进入基本原理。科学社会主义保留位置与范围边界，不以名称出现代替完整讲授。","sourceBlockIds":["block:politics-toc-v2-u020:b003","block:politics-toc-v2-u020:b004","block:politics-toc-v2-u020:b005","block:politics-toc-v2-u020:b006","block:politics-toc-v2-u020:b009","block:politics-toc-v2-u020:b010"],"emphasis":[],"kind":"recap","id":"BASICS-01-recap"}]},{"title":"两组哲学分歧分别在问什么","question":"唯物与唯心、可知与不可知为什么不是同一个分法？","objectives":["分清第一性问题和同一性问题"],"scopeLimit":"本节只解释“唯物与唯心、可知与不可知为什么不是同一个分法”；科学社会主义不作独立详细课程。","reflection":{"prompt":"唯物与唯心、可知与不可知为什么不是同一个分法？","answer":"唯物与唯心围绕物质和意识谁是第一性来划分，可知与不可知围绕思维能否认识存在来划分。两组分歧回答的问题不同。","sourceBlockIds":["block:politics-toc-v2-u021:b002","block:politics-toc-v2-u021:b003","block:politics-toc-v2-u021:b005","block:politics-toc-v2-u021:b009","block:politics-toc-v2-u021:b012"]},"id":"BASICS-02","groupId":"basics","previousLessonId":"BASICS-01","nextLessonId":"BASICS-03","transition":"下一节：物质为什么同时讲运动与静止","corePromises":[{"quote":"第一性","sourceBlockIds":["block:politics-toc-v2-u021:b002","block:politics-toc-v2-u021:b003","block:politics-toc-v2-u021:b004"]},{"quote":"物质决定意识","sourceBlockIds":["block:politics-toc-v2-u021:b002","block:politics-toc-v2-u021:b003","block:politics-toc-v2-u021:b004"]},{"quote":"意识决定物质","sourceBlockIds":["block:politics-toc-v2-u021:b002","block:politics-toc-v2-u021:b003","block:politics-toc-v2-u021:b004"]},{"quote":"可知论和不可知论","sourceBlockIds":["block:politics-toc-v2-u021:b005","block:politics-toc-v2-u021:b007","block:politics-toc-v2-u021:b008","block:politics-toc-v2-u021:b009","block:politics-toc-v2-u021:b010","block:politics-toc-v2-u021:b011","block:politics-toc-v2-u021:b012"]},{"quote":"人的精神","sourceBlockIds":["block:politics-toc-v2-u021:b005","block:politics-toc-v2-u021:b007","block:politics-toc-v2-u021:b008","block:politics-toc-v2-u021:b009","block:politics-toc-v2-u021:b010","block:politics-toc-v2-u021:b011","block:politics-toc-v2-u021:b012"]},{"quote":"客观精神","sourceBlockIds":["block:politics-toc-v2-u021:b005","block:politics-toc-v2-u021:b007","block:politics-toc-v2-u021:b008","block:politics-toc-v2-u021:b009","block:politics-toc-v2-u021:b010","block:politics-toc-v2-u021:b011","block:politics-toc-v2-u021:b012"]}],"primaryUnitIds":["politics-toc-v2-u021"],"parts":[{"label":"第一性问题区分基本派别","text":"哲学基本问题是思维与存在、意识与物质的关系问题。物质和意识何者为第一性，区分唯物主义和唯心主义：前者认为物质决定意识，后者认为意识决定物质。问的是世界本原和决定关系，不是一个人生活是否重视物质享受。","sourceBlockIds":["block:politics-toc-v2-u021:b002","block:politics-toc-v2-u021:b003","block:politics-toc-v2-u021:b004"],"emphasis":[{"part":"text","quote":"第一性","occurrence":1,"role":"key"},{"part":"text","quote":"物质决定意识","occurrence":1,"role":"key"},{"part":"text","quote":"意识决定物质","occurrence":1,"role":"key"}],"kind":"explanation","id":"BASICS-02-body-1"},{"label":"同一性问题形成另一条划分","text":"物质和意识是否具有同一性，区分可知论和不可知论，这里问思维能否认识存在，而不是再次问哪一方决定另一方。唯心主义内部又有主观唯心主义与客观唯心主义，分别以人的精神或客观精神为世界本原；唯物主义经历朴素、形而上学、辩证唯物主义等不同理解，对物质的认识并不相同。","sourceBlockIds":["block:politics-toc-v2-u021:b005","block:politics-toc-v2-u021:b007","block:politics-toc-v2-u021:b008","block:politics-toc-v2-u021:b009","block:politics-toc-v2-u021:b010","block:politics-toc-v2-u021:b011","block:politics-toc-v2-u021:b012"],"emphasis":[{"part":"text","quote":"可知论和不可知论","occurrence":1,"role":"key"},{"part":"text","quote":"人的精神","occurrence":1,"role":"key"},{"part":"text","quote":"客观精神","occurrence":1,"role":"key"}],"kind":"explanation","id":"BASICS-02-body-2"},{"label":"判别维度不能混用","text":"唯物与唯心回答何者第一性，可知与不可知回答是否具有同一性。现代唯物主义以客观实在性理解物质，不能把各种唯物主义对物质的解释当成完全一样。","sourceBlockIds":["block:politics-toc-v2-u021:b009","block:politics-toc-v2-u021:b012"],"emphasis":[],"kind":"boundary","id":"BASICS-02-boundary"},{"label":"本节结论","text":"判断哲学基本问题时，先分清是在问物质和意识何者为第一性，还是二者是否具有同一性，再辨认相应派别及内部区别。","sourceBlockIds":["block:politics-toc-v2-u021:b002","block:politics-toc-v2-u021:b003","block:politics-toc-v2-u021:b005","block:politics-toc-v2-u021:b009","block:politics-toc-v2-u021:b012"],"emphasis":[],"kind":"recap","id":"BASICS-02-recap"}]},{"title":"物质为什么同时讲运动与静止","question":"客观实在性与运动是不是同一种定位？","objectives":["区分物质特性、根本属性与运动状态"],"scopeLimit":"本节只解释“客观实在性与运动是不是同一种定位”；科学社会主义不作独立详细课程。","reflection":{"prompt":"客观实在性与运动是不是同一种定位？","answer":"不是。客观实在性说明物质的唯一特性，运动说明物质的根本属性和存在方式，相对静止说明运动中的特殊状态，三者定位不同。","sourceBlockIds":["block:politics-toc-v2-u022:b002","block:politics-toc-v2-u022:b003","block:politics-toc-v2-u022:b004","block:politics-toc-v2-u022:b005","block:politics-toc-v2-u022:b006"]},"id":"BASICS-03","groupId":"basics","previousLessonId":"BASICS-02","nextLessonId":"BASICS-04","transition":"下一节：意识的能动作用有哪些条件","corePromises":[{"quote":"客观实在性","sourceBlockIds":["block:politics-toc-v2-u022:b002","block:politics-toc-v2-u022:b003","block:politics-toc-v2-u022:b016"]},{"quote":"根本属性和存在方式","sourceBlockIds":["block:politics-toc-v2-u022:b002","block:politics-toc-v2-u022:b003","block:politics-toc-v2-u022:b016"]},{"quote":"绝对运动","sourceBlockIds":["block:politics-toc-v2-u022:b003","block:politics-toc-v2-u022:b004","block:politics-toc-v2-u022:b005"]},{"quote":"相对静止","sourceBlockIds":["block:politics-toc-v2-u022:b003","block:politics-toc-v2-u022:b004","block:politics-toc-v2-u022:b005"]}],"primaryUnitIds":["politics-toc-v2-u022"],"parts":[{"label":"物质的特性与属性","text":"物质是标志客观实在的哲学范畴，客观实在性是物质的唯一特性；运动是物质的根本属性和存在方式。前者说明物质的特性，后者说明其存在方式，不能把“唯一特性”和“根本属性”两个定位交换。","sourceBlockIds":["block:politics-toc-v2-u022:b002","block:politics-toc-v2-u022:b003","block:politics-toc-v2-u022:b016"],"emphasis":[{"part":"text","quote":"客观实在性","occurrence":1,"role":"key"},{"part":"text","quote":"根本属性和存在方式","occurrence":1,"role":"key"}],"kind":"explanation","id":"BASICS-03-body-1"},{"label":"运动与静止可以同时理解","text":"运动是无条件、永恒、绝对的，静止是有条件、暂时、相对的，是运动的一种特殊状态。事物是绝对运动和相对静止的统一。因此承认某种条件下相对稳定，并不否定事物仍在运动；也不能因为运动绝对就说稳定状态不存在。","sourceBlockIds":["block:politics-toc-v2-u022:b003","block:politics-toc-v2-u022:b004","block:politics-toc-v2-u022:b005"],"emphasis":[{"part":"text","quote":"绝对运动","occurrence":1,"role":"key"},{"part":"text","quote":"相对静止","occurrence":1,"role":"key"}],"kind":"explanation","id":"BASICS-03-body-2"},{"label":"两个维度分别保留","text":"客观实在性不等于“永远不变”，运动也不等于所有性质随时都已改变。本小节区分存在特性和状态，不从一个词推出所有具体变化。","sourceBlockIds":["block:politics-toc-v2-u022:b002","block:politics-toc-v2-u022:b003","block:politics-toc-v2-u022:b004","block:politics-toc-v2-u022:b005","block:politics-toc-v2-u022:b016"],"emphasis":[],"kind":"boundary","id":"BASICS-03-boundary"},{"label":"本节结论","text":"客观实在性说明物质的唯一特性，运动说明物质的根本属性和存在方式，相对静止说明运动中的特殊状态。","sourceBlockIds":["block:politics-toc-v2-u022:b002","block:politics-toc-v2-u022:b003","block:politics-toc-v2-u022:b004","block:politics-toc-v2-u022:b005","block:politics-toc-v2-u022:b006"],"emphasis":[],"kind":"recap","id":"BASICS-03-recap"}]},{"title":"意识的能动作用有哪些条件","question":"承认物质决定意识，是否就否认意识的作用？","objectives":["理解决定作用、反作用与实践条件"],"scopeLimit":"本节只解释“承认物质决定意识，是否就否认意识的作用”；科学社会主义不作独立详细课程。","reflection":{"prompt":"承认物质决定意识，是否就否认意识的作用？","answer":"不否认。物质决定意识要求从客观实际出发，意识又能能动地认识和改造世界；这种作用必须尊重客观规律并通过实践实现。","sourceBlockIds":["block:politics-toc-v2-u022:b007","block:politics-toc-v2-u022:b008","block:politics-toc-v2-u022:b009","block:politics-toc-v2-u022:b016"]},"id":"BASICS-04","groupId":"basics","previousLessonId":"BASICS-03","nextLessonId":null,"transition":"下一主题：联系 发展与矛盾","corePromises":[{"quote":"主观映象","sourceBlockIds":["block:politics-toc-v2-u022:b006","block:politics-toc-v2-u022:b007"]},{"quote":"一切从实际出发","sourceBlockIds":["block:politics-toc-v2-u022:b006","block:politics-toc-v2-u022:b007"]},{"quote":"主观能动性","sourceBlockIds":["block:politics-toc-v2-u022:b008","block:politics-toc-v2-u022:b009","block:politics-toc-v2-u022:b016"]},{"quote":"尊重客观规律","sourceBlockIds":["block:politics-toc-v2-u022:b008","block:politics-toc-v2-u022:b009","block:politics-toc-v2-u022:b016"]},{"quote":"通过实践实现","sourceBlockIds":["block:politics-toc-v2-u022:b008","block:politics-toc-v2-u022:b009","block:politics-toc-v2-u022:b016"]}],"primaryUnitIds":["politics-toc-v2-u022"],"parts":[{"label":"先明确意识是什么","text":"意识是人脑对客观存在的主观映象，人脑是意识的器官。物质决定意识，要求一切从实际出发；“主观映象”不意味着内容可以任意编造，而要保留客观存在这个所反映对象。","sourceBlockIds":["block:politics-toc-v2-u022:b006","block:politics-toc-v2-u022:b007"],"emphasis":[{"part":"text","quote":"主观映象","occurrence":1,"role":"key"},{"part":"text","quote":"一切从实际出发","occurrence":1,"role":"key"}],"kind":"explanation","id":"BASICS-04-body-1"},{"label":"反作用不是直接改变事物","text":"意识具有主观能动性，正确意识促进发展，错误意识阻碍发展。尊重客观规律是正确发挥主观能动性的前提，意识的反作用必须通过实践实现，不能靠想法直接改变客观事物。决定作用与反作用并不相互取消。","sourceBlockIds":["block:politics-toc-v2-u022:b008","block:politics-toc-v2-u022:b009","block:politics-toc-v2-u022:b016"],"emphasis":[{"part":"text","quote":"主观能动性","occurrence":1,"role":"key"},{"part":"text","quote":"尊重客观规律","occurrence":1,"role":"key"},{"part":"text","quote":"通过实践实现","occurrence":1,"role":"key"}],"kind":"explanation","id":"BASICS-04-body-2"},{"label":"器官 映象与实践不混同","text":"人脑是意识的器官，意识是对客观存在的主观映象，意识的作用还需通过实践实现；不能把器官、认识内容和实现作用的活动混成一层。人工智能相关延伸保留原文查阅。","sourceBlockIds":["block:politics-toc-v2-u022:b006","block:politics-toc-v2-u022:b016","block:politics-toc-v2-u022:b012"],"emphasis":[],"kind":"boundary","id":"BASICS-04-boundary"},{"label":"本主题小结","text":"从客观实际出发，承认意识能动作用，又保留规律与实践条件，才是对物质意识关系的整体理解。接下来从联系、发展与矛盾理解变化。","sourceBlockIds":["block:politics-toc-v2-u022:b007","block:politics-toc-v2-u022:b008","block:politics-toc-v2-u022:b009","block:politics-toc-v2-u022:b016"],"emphasis":[],"kind":"recap","id":"BASICS-04-recap"}]},{"title":"联系与发展怎样保留具体条件","question":"联系、整体和发展分别要保留什么判断条件？","objectives":["用具体条件理解联系、整体与发展的判断"],"scopeLimit":"本节建立联系、整体与发展的三个基本判断；矛盾分析留到下一节。","reflection":{"prompt":"联系、整体和发展分别要防止什么误读？","answer":"不能把普遍联系理解成任意两件事必然相连，不能把整体功能理解成部分功能机械相加，也不能只按出现时间判断新旧事物；三类判断都要保留具体条件。","sourceBlockIds":["block:politics-toc-v2-u023:b002","block:politics-toc-v2-u023:b008","block:politics-toc-v2-u023:b009","block:politics-toc-v2-u023:b010","block:politics-toc-v2-u023:b011","block:politics-toc-v2-u024:b002"]},"id":"DIALECTICS-01","groupId":"dialectics","previousLessonId":null,"nextLessonId":"DIALECTICS-02","transition":"下一节：对立与统一为什么同时存在","corePromises":[{"quote":"客观性、普遍性、多样性、条件性","sourceBlockIds":["block:politics-toc-v2-u023:b002","block:politics-toc-v2-u023:b004","block:politics-toc-v2-u023:b005","block:politics-toc-v2-u023:b006","block:politics-toc-v2-u023:b012"]},{"quote":"任意连线","sourceBlockIds":["block:politics-toc-v2-u023:b002","block:politics-toc-v2-u023:b004","block:politics-toc-v2-u023:b005","block:politics-toc-v2-u023:b006","block:politics-toc-v2-u023:b012"]},{"quote":"整体统率部分","sourceBlockIds":["block:politics-toc-v2-u023:b008","block:politics-toc-v2-u023:b009","block:politics-toc-v2-u023:b010","block:politics-toc-v2-u023:b011","block:politics-toc-v2-u023:b012"]},{"quote":"发展的必然趋势","sourceBlockIds":["block:politics-toc-v2-u023:b008","block:politics-toc-v2-u023:b009","block:politics-toc-v2-u023:b010","block:politics-toc-v2-u023:b011","block:politics-toc-v2-u023:b012"]}],"primaryUnitIds":["politics-toc-v2-u023"],"parts":[{"label":"联系普遍存在，也有条件","text":"联系和发展是唯物辩证法的总观点、总特征。联系具有客观性、普遍性、多样性、条件性，是事物本身固有而非主观臆想。普遍性不是任意连线：任何两个事物之间不一定都有必然联系，认识具体联系要保留其条件。","sourceBlockIds":["block:politics-toc-v2-u023:b002","block:politics-toc-v2-u023:b004","block:politics-toc-v2-u023:b005","block:politics-toc-v2-u023:b006","block:politics-toc-v2-u023:b012"],"emphasis":[{"part":"text","quote":"客观性、普遍性、多样性、条件性","occurrence":1,"role":"key"},{"part":"text","quote":"任意连线","occurrence":1,"role":"key"}],"kind":"explanation","id":"DIALECTICS-01-body-1"},{"label":"整体部分与发展分别看","text":"整体统率部分并具有部分所没有的新功能，部分也影响整体，关键部分甚至决定整体功能。发展实质是新事物产生、旧事物灭亡，新旧的根本标志是是否符合发展的必然趋势，不能只按出现先后判断。","sourceBlockIds":["block:politics-toc-v2-u023:b008","block:politics-toc-v2-u023:b009","block:politics-toc-v2-u023:b010","block:politics-toc-v2-u023:b011","block:politics-toc-v2-u023:b012"],"emphasis":[{"part":"text","quote":"整体统率部分","occurrence":1,"role":"key"},{"part":"text","quote":"发展的必然趋势","occurrence":1,"role":"key"}],"kind":"explanation","id":"DIALECTICS-01-body-2"},{"label":"不把整体机械相加","text":"整体功能不是部分功能的机械相加，整体主导不否认关键部分的作用。判断新事物也不能只凭名称新或时间晚，两个判断都需要具体条件。","sourceBlockIds":["block:politics-toc-v2-u023:b012"],"emphasis":[],"kind":"boundary","id":"DIALECTICS-01-boundary"},{"label":"本节结论","text":"联系有客观条件，整体与部分相互影响，发展要按必然趋势理解。这些提供看问题的总体视角，接下来用矛盾解释发展的源泉与动力。","sourceBlockIds":["block:politics-toc-v2-u023:b002","block:politics-toc-v2-u023:b008","block:politics-toc-v2-u023:b009","block:politics-toc-v2-u023:b010","block:politics-toc-v2-u023:b011","block:politics-toc-v2-u024:b002"],"emphasis":[],"kind":"recap","id":"DIALECTICS-01-recap"}]},{"title":"对立与统一为什么同时存在","question":"同一性与斗争性，普遍性与特殊性怎样放在一起？","objectives":["理解矛盾属性及普遍特殊的联系"],"scopeLimit":"本节只解释“同一性与斗争性，普遍性与特殊性怎样放在一起”；主题内其他问题留到后续小节。","reflection":{"prompt":"同一性与斗争性，普遍性与特殊性怎样放在一起？","answer":"同一性说明矛盾双方相互依存，斗争性说明相互排斥；普遍性说明矛盾普遍存在，特殊性说明具体矛盾各有特点。分析时既要全面，也要具体。","sourceBlockIds":["block:politics-toc-v2-u024:b002","block:politics-toc-v2-u024:b003","block:politics-toc-v2-u024:b004","block:politics-toc-v2-u024:b008","block:politics-toc-v2-u024:b011","block:politics-toc-v2-u024:b013"]},"id":"DIALECTICS-02","groupId":"dialectics","previousLessonId":"DIALECTICS-01","nextLessonId":"DIALECTICS-03","transition":"下一节：主要矛盾与主要方面怎样分层","corePromises":[{"quote":"相互依存、相互贯通","sourceBlockIds":["block:politics-toc-v2-u024:b002","block:politics-toc-v2-u024:b003","block:politics-toc-v2-u024:b004"]},{"quote":"相互排斥、相互分离","sourceBlockIds":["block:politics-toc-v2-u024:b002","block:politics-toc-v2-u024:b003","block:politics-toc-v2-u024:b004"]},{"quote":"具体问题具体分析","sourceBlockIds":["block:politics-toc-v2-u024:b007","block:politics-toc-v2-u024:b008","block:politics-toc-v2-u024:b010","block:politics-toc-v2-u024:b011","block:politics-toc-v2-u024:b012","block:politics-toc-v2-u024:b013"]},{"quote":"普遍性寓于特殊性","sourceBlockIds":["block:politics-toc-v2-u024:b007","block:politics-toc-v2-u024:b008","block:politics-toc-v2-u024:b010","block:politics-toc-v2-u024:b011","block:politics-toc-v2-u024:b012","block:politics-toc-v2-u024:b013"]}],"primaryUnitIds":["politics-toc-v2-u024"],"parts":[{"label":"矛盾不只是日常争吵","text":"矛盾反映事物内部或不同事物间的对立统一关系，对立统一规律揭示发展的源泉和动力。同一性是双方相互依存、相互贯通；斗争性是双方相互排斥、相互分离。两者共同说明矛盾关系，不能只看对立而删去依存。","sourceBlockIds":["block:politics-toc-v2-u024:b002","block:politics-toc-v2-u024:b003","block:politics-toc-v2-u024:b004"],"emphasis":[{"part":"text","quote":"相互依存、相互贯通","occurrence":1,"role":"key"},{"part":"text","quote":"相互排斥、相互分离","occurrence":1,"role":"key"}],"kind":"explanation","id":"DIALECTICS-02-body-1"},{"label":"共性与个性并不排斥","text":"矛盾普遍性说明无处不在、无时不有，要求全面地、一分为二地看问题；特殊性说明具体矛盾及各方面有特点，要求具体问题具体分析。普遍性寓于特殊性之中，特殊性包含普遍性，二者在一定条件下可以相互转化。共性不能脱离具体个性独立解释一切。","sourceBlockIds":["block:politics-toc-v2-u024:b007","block:politics-toc-v2-u024:b008","block:politics-toc-v2-u024:b010","block:politics-toc-v2-u024:b011","block:politics-toc-v2-u024:b012","block:politics-toc-v2-u024:b013"],"emphasis":[{"part":"text","quote":"具体问题具体分析","occurrence":1,"role":"key"},{"part":"text","quote":"普遍性寓于特殊性","occurrence":1,"role":"key"}],"kind":"explanation","id":"DIALECTICS-02-body-2"},{"label":"不同问题不要混成一层","text":"同一与斗争说明矛盾基本属性，普遍与特殊说明共性个性；这两组不互相替代。承认普遍性，也不等于所有具体问题都可用同一答案。","sourceBlockIds":["block:politics-toc-v2-u024:b003","block:politics-toc-v2-u024:b004","block:politics-toc-v2-u024:b011","block:politics-toc-v2-u024:b012","block:politics-toc-v2-u024:b025"],"emphasis":[],"kind":"boundary","id":"DIALECTICS-02-boundary"},{"label":"本节结论","text":"矛盾具有相互依存又相互排斥的两面，共性存在于个性之中，因此分析问题既要全面，也要具体。","sourceBlockIds":["block:politics-toc-v2-u024:b002","block:politics-toc-v2-u024:b003","block:politics-toc-v2-u024:b004","block:politics-toc-v2-u024:b008","block:politics-toc-v2-u024:b011","block:politics-toc-v2-u024:b013"],"emphasis":[],"kind":"recap","id":"DIALECTICS-02-recap"}]},{"title":"主要矛盾与主要方面怎样分层","question":"主要矛盾和矛盾主要方面为什么不能互换？","objectives":["区分多个矛盾的主次与同一矛盾双方的主次"],"scopeLimit":"本节只解释“主要矛盾和矛盾主要方面为什么不能互换”；主题内其他问题留到后续小节。","reflection":{"prompt":"一个项目有资金、技术与协作问题，分析发现资金不到位会使其余改进难以启动。这主要在判断什么？","answer":"主要矛盾。这里在多组矛盾之间确定对整体进程起决定作用的一组，未比较同一矛盾内部双方。","sourceBlockIds":["block:politics-toc-v2-u024:b015","block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b019","block:politics-toc-v2-u024:b020","block:politics-toc-v2-u024:b025"]},"id":"DIALECTICS-03","groupId":"dialectics","previousLessonId":"DIALECTICS-02","nextLessonId":"DIALECTICS-04","transition":"下一节：内因与外因怎样共同作用","corePromises":[{"quote":"多个矛盾","sourceBlockIds":["block:politics-toc-v2-u024:b015","block:politics-toc-v2-u024:b016","block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b018","block:politics-toc-v2-u024:b025"]},{"quote":"同一矛盾双方","sourceBlockIds":["block:politics-toc-v2-u024:b015","block:politics-toc-v2-u024:b016","block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b018","block:politics-toc-v2-u024:b025"]},{"quote":"两点论","sourceBlockIds":["block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b019","block:politics-toc-v2-u024:b020","block:politics-toc-v2-u024:b025"]},{"quote":"重点论","sourceBlockIds":["block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b019","block:politics-toc-v2-u024:b020","block:politics-toc-v2-u024:b025"]},{"quote":"不等于平均用力","sourceBlockIds":["block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b019","block:politics-toc-v2-u024:b020","block:politics-toc-v2-u024:b025"]}],"primaryUnitIds":["politics-toc-v2-u024"],"parts":[{"label":"先看是在比较什么","text":"主要矛盾是在复杂事物多个矛盾中居支配地位、对发展过程起决定作用的矛盾，次要矛盾处于从属地位。矛盾主要方面则是在同一矛盾双方中居支配地位的方面。前者比较多个矛盾，后者比较一个矛盾内部双方，必须先分清对象再判断主次。","sourceBlockIds":["block:politics-toc-v2-u024:b015","block:politics-toc-v2-u024:b016","block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b018","block:politics-toc-v2-u024:b025"],"emphasis":[{"part":"text","quote":"多个矛盾","occurrence":1,"role":"key"},{"part":"text","quote":"同一矛盾双方","occurrence":1,"role":"key"}],"kind":"explanation","id":"DIALECTICS-03-body-1"},{"label":"两点论与重点论共同使用","text":"事物性质由主要矛盾的主要方面决定。两点论要求既看主要矛盾也看次要矛盾，既看主要方面也看次要方面；重点论要求着重把握主要矛盾、主要方面。全面不等于平均用力，突出重点也不表示次要因素不起作用。","sourceBlockIds":["block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b019","block:politics-toc-v2-u024:b020","block:politics-toc-v2-u024:b025"],"emphasis":[{"part":"text","quote":"两点论","occurrence":1,"role":"key"},{"part":"text","quote":"重点论","occurrence":1,"role":"key"},{"part":"text","quote":"不等于平均用力","occurrence":1,"role":"key"}],"kind":"explanation","id":"DIALECTICS-03-body-2"},{"label":"材料怎样用","text":"先确认比较层次：多组问题之间找决定整体进程的一组，判断主要矛盾；同一矛盾双方之间判断支配方面，判断矛盾主要方面。不要看到“关键”就直接套概念。","sourceBlockIds":["block:politics-toc-v2-u024:b015","block:politics-toc-v2-u024:b016","block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b018","block:politics-toc-v2-u024:b025","block:politics-toc-v2-u024:b019","block:politics-toc-v2-u024:b020"],"kind":"explanation","id":"DIALECTICS-03-body-3"},{"label":"不要跨层次作替换","text":"“抓主要矛盾”和“看矛盾主要方面”回答的问题不同。次要矛盾与次要方面仍有作用，不能把非决定作用写成完全没有影响。","sourceBlockIds":["block:politics-toc-v2-u024:b015","block:politics-toc-v2-u024:b016","block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b018","block:politics-toc-v2-u024:b025"],"emphasis":[],"kind":"boundary","id":"DIALECTICS-03-boundary"},{"label":"本节结论","text":"分析复杂矛盾时要先确定比较层次，再分清主要与次要，最后把两点论与重点论统一起来，不能脱离条件预设固定主次。","sourceBlockIds":["block:politics-toc-v2-u024:b015","block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b019","block:politics-toc-v2-u024:b020","block:politics-toc-v2-u024:b025"],"emphasis":[],"kind":"recap","id":"DIALECTICS-03-recap"}]},{"title":"内因与外因怎样共同作用","question":"重视内因是否等于外因不重要？","objectives":["理解根据、条件与作用途径"],"scopeLimit":"本节只解释“重视内因是否等于外因不重要”；主题内其他问题留到后续小节。","reflection":{"prompt":"重视内因是否等于外因不重要？","answer":"不等于。内因是变化的根据，外因是变化的条件，并通过内因起作用；强调内因不能取消外部条件的影响。","sourceBlockIds":["block:politics-toc-v2-u024:b015","block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b022","block:politics-toc-v2-u024:b023","block:politics-toc-v2-u024:b024","block:politics-toc-v2-u025:b002"]},"id":"DIALECTICS-04","groupId":"dialectics","previousLessonId":"DIALECTICS-03","nextLessonId":"DIALECTICS-05","transition":"下一节：量变怎样跨过度形成质变","corePromises":[{"quote":"内部矛盾","sourceBlockIds":["block:politics-toc-v2-u024:b021","block:politics-toc-v2-u024:b022","block:politics-toc-v2-u024:b023","block:politics-toc-v2-u024:b025"]},{"quote":"外部矛盾","sourceBlockIds":["block:politics-toc-v2-u024:b021","block:politics-toc-v2-u024:b022","block:politics-toc-v2-u024:b023","block:politics-toc-v2-u024:b025"]},{"quote":"内因是发展变化的根据","sourceBlockIds":["block:politics-toc-v2-u024:b024","block:politics-toc-v2-u024:b025"]},{"quote":"外因通过内因起作用","sourceBlockIds":["block:politics-toc-v2-u024:b024","block:politics-toc-v2-u024:b025"]}],"primaryUnitIds":["politics-toc-v2-u024"],"parts":[{"label":"先分清内部与外部","text":"内因是事物内部矛盾，外因是事物与他事物之间的相互影响和相互作用，即外部矛盾。这里先确定研究对象及其内外，不能只按因素看起来远近或大小划分。上一小节的主次与这里的内外，是不同分析角度。","sourceBlockIds":["block:politics-toc-v2-u024:b021","block:politics-toc-v2-u024:b022","block:politics-toc-v2-u024:b023","block:politics-toc-v2-u024:b025"],"emphasis":[{"part":"text","quote":"内部矛盾","occurrence":1,"role":"key"},{"part":"text","quote":"外部矛盾","occurrence":1,"role":"key"}],"kind":"explanation","id":"DIALECTICS-04-body-1"},{"label":"根据和条件有不同作用","text":"内因是发展变化的根据、第一位原因，外因是条件、第二位原因，外因通过内因起作用。读“根据”要同时保留“条件”，不能从内因第一位推出外因无效；也不能只列外部条件便省略内部矛盾的作用途径。","sourceBlockIds":["block:politics-toc-v2-u024:b024","block:politics-toc-v2-u024:b025"],"emphasis":[{"part":"text","quote":"内因是发展变化的根据","occurrence":1,"role":"key"},{"part":"text","quote":"外因通过内因起作用","occurrence":1,"role":"key"}],"kind":"explanation","id":"DIALECTICS-04-body-2"},{"label":"关系不等于万能配方","text":"本小节解释已有关系，并不预先给任何具体问题指定哪个因素是内因或外因。判断必须先确定对象与具体条件，不把两者当成固定褒贬标签。","sourceBlockIds":["block:politics-toc-v2-u024:b011","block:politics-toc-v2-u024:b022","block:politics-toc-v2-u024:b023","block:politics-toc-v2-u024:b024"],"emphasis":[],"kind":"boundary","id":"DIALECTICS-04-boundary"},{"label":"本节结论","text":"矛盾既可分析主次，也可分析内外。内因是根据，外因是条件且通过内因起作用；理解这些联系后，再看量变质变描述的变化形式。","sourceBlockIds":["block:politics-toc-v2-u024:b015","block:politics-toc-v2-u024:b017","block:politics-toc-v2-u024:b022","block:politics-toc-v2-u024:b023","block:politics-toc-v2-u024:b024","block:politics-toc-v2-u025:b002"],"emphasis":[],"kind":"recap","id":"DIALECTICS-04-recap"}]},{"title":"量变怎样跨过度形成质变","question":"数量有变化就一定已经质变吗？","objectives":["理解量变质变的标志与方法条件"],"scopeLimit":"本节只解释“数量有变化就一定已经质变吗”；主题内其他问题留到后续小节。","reflection":{"prompt":"某材料成分比例多次调整但基本性质未变，能只凭次数多认定质变吗？","answer":"不能。是否超出保持原质的限度才是关键，次数多本身不足以推出质变。","sourceBlockIds":["block:politics-toc-v2-u025:b002","block:politics-toc-v2-u025:b003","block:politics-toc-v2-u025:b005","block:politics-toc-v2-u025:b006","block:politics-toc-v2-u025:b009","block:politics-toc-v2-u026:b002"]},"id":"DIALECTICS-05","groupId":"dialectics","previousLessonId":"DIALECTICS-04","nextLessonId":"DIALECTICS-06","transition":"下一节：扬弃怎样连接克服保留与曲折前进","corePromises":[{"quote":"度的范围","sourceBlockIds":["block:politics-toc-v2-u025:b002","block:politics-toc-v2-u025:b003","block:politics-toc-v2-u025:b004","block:politics-toc-v2-u025:b010"]},{"quote":"量变与质变","sourceBlockIds":["block:politics-toc-v2-u025:b002","block:politics-toc-v2-u025:b003","block:politics-toc-v2-u025:b004","block:politics-toc-v2-u025:b010"]},{"quote":"必要准备","sourceBlockIds":["block:politics-toc-v2-u025:b005","block:politics-toc-v2-u025:b006","block:politics-toc-v2-u025:b007","block:politics-toc-v2-u025:b009","block:politics-toc-v2-u025:b010"]},{"quote":"重视量的积累","sourceBlockIds":["block:politics-toc-v2-u025:b005","block:politics-toc-v2-u025:b006","block:politics-toc-v2-u025:b007","block:politics-toc-v2-u025:b009","block:politics-toc-v2-u025:b010"]},{"quote":"适度原则","sourceBlockIds":["block:politics-toc-v2-u025:b005","block:politics-toc-v2-u025:b006","block:politics-toc-v2-u025:b007","block:politics-toc-v2-u025:b009","block:politics-toc-v2-u025:b010"]}],"primaryUnitIds":["politics-toc-v2-u025"],"parts":[{"label":"判断关键在是否超出度","text":"量变质变规律揭示发展的形式和状态。度是事物保持其质的量的限度、幅度和范围，区分量变与质变的根本标志是变化是否超出度的范围。因此不能只看数字有没有增加，就宣称性质已经改变。","sourceBlockIds":["block:politics-toc-v2-u025:b002","block:politics-toc-v2-u025:b003","block:politics-toc-v2-u025:b004","block:politics-toc-v2-u025:b010"],"emphasis":[{"part":"text","quote":"度的范围","occurrence":1,"role":"key"},{"part":"text","quote":"量变与质变","occurrence":1,"role":"key"}],"kind":"explanation","id":"DIALECTICS-05-body-1"},{"label":"积累与飞跃相互联系","text":"量变是质变的必要准备，量变达到一定程度必然引起质变，二者相互渗透。方法上既要重视量的积累，也要不失时机促成飞跃，同时坚持适度原则。三种要求有不同条件，不是永远只积累，或随时都应越过原有范围。","sourceBlockIds":["block:politics-toc-v2-u025:b005","block:politics-toc-v2-u025:b006","block:politics-toc-v2-u025:b007","block:politics-toc-v2-u025:b009","block:politics-toc-v2-u025:b010"],"emphasis":[{"part":"text","quote":"必要准备","occurrence":1,"role":"key"},{"part":"text","quote":"重视量的积累","occurrence":1,"role":"key"},{"part":"text","quote":"适度原则","occurrence":1,"role":"key"}],"kind":"explanation","id":"DIALECTICS-05-body-2"},{"label":"材料怎样用","text":"先找性质是否改变的依据，再看数量、次数或速度。明确仍保持原有性质，不能只凭多次增长判质变；补充条件若表明已超出度，应随条件重新判断。","sourceBlockIds":["block:politics-toc-v2-u025:b002","block:politics-toc-v2-u025:b003","block:politics-toc-v2-u025:b004","block:politics-toc-v2-u025:b010","block:politics-toc-v2-u025:b005","block:politics-toc-v2-u025:b006","block:politics-toc-v2-u025:b007","block:politics-toc-v2-u025:b009"],"kind":"explanation","id":"DIALECTICS-05-body-3"},{"label":"细微变化不能直接等号质变","text":"只有达到一定程度、超出原有度的范围，量变才引起质变。不能把“积累会带来质变”简写成任何一点变化都已经质变。","sourceBlockIds":["block:politics-toc-v2-u025:b006","block:politics-toc-v2-u025:b010"],"emphasis":[],"kind":"boundary","id":"DIALECTICS-05-boundary"},{"label":"本节结论","text":"度用来判断量变和质变的界限，量的积累、质的飞跃与适度原则需要放回各自条件理解。","sourceBlockIds":["block:politics-toc-v2-u025:b002","block:politics-toc-v2-u025:b003","block:politics-toc-v2-u025:b005","block:politics-toc-v2-u025:b006","block:politics-toc-v2-u025:b009","block:politics-toc-v2-u026:b002"],"emphasis":[],"kind":"recap","id":"DIALECTICS-05-recap"}]},{"title":"扬弃怎样连接克服保留与曲折前进","question":"辩证否定与否定之否定分别说明什么？","objectives":["区分辩证否定与否定之否定的职责"],"scopeLimit":"本节区分辩证否定的克服与保留和否定之否定揭示的发展道路；不把两者压成机械次数。","reflection":{"prompt":"辩证否定与否定之否定分别说明什么，为什么不能用“两次否定”机械理解？","answer":"辩证否定说明对旧事物既克服又保留，即“扬弃”；否定之否定说明发展是前进性与曲折性的统一。不能用表面上的两次否定替代内部矛盾和具体发展过程。","sourceBlockIds":["block:politics-toc-v2-u023:b002","block:politics-toc-v2-u024:b002","block:politics-toc-v2-u025:b002","block:politics-toc-v2-u026:b002","block:politics-toc-v2-u026:b007","block:politics-toc-v2-u026:b010"]},"id":"DIALECTICS-06","groupId":"dialectics","previousLessonId":"DIALECTICS-05","nextLessonId":null,"transition":"下一主题：实践 认识与真理","corePromises":[{"quote":"自我否定","sourceBlockIds":["block:politics-toc-v2-u026:b004","block:politics-toc-v2-u026:b005","block:politics-toc-v2-u026:b006","block:politics-toc-v2-u026:b007","block:politics-toc-v2-u026:b011"]},{"quote":"既克服又保留","sourceBlockIds":["block:politics-toc-v2-u026:b004","block:politics-toc-v2-u026:b005","block:politics-toc-v2-u026:b006","block:politics-toc-v2-u026:b007","block:politics-toc-v2-u026:b011"]},{"quote":"螺旋式上升、波浪式前进","sourceBlockIds":["block:politics-toc-v2-u026:b002","block:politics-toc-v2-u026:b009","block:politics-toc-v2-u026:b010","block:politics-toc-v2-u026:b011","block:politics-toc-v2-u023:b011"]},{"quote":"前进性和曲折性","sourceBlockIds":["block:politics-toc-v2-u026:b002","block:politics-toc-v2-u026:b009","block:politics-toc-v2-u026:b010","block:politics-toc-v2-u026:b011","block:politics-toc-v2-u023:b011"]}],"primaryUnitIds":["politics-toc-v2-u026"],"parts":[{"label":"否定来自自身矛盾运动","text":"辩证否定是事物自我否定、内部矛盾运动的结果，同时是发展和联系的环节。其实质是扬弃：既克服又保留，克服消极因素、保留并发展积极因素。它不是外部强加的任意否定，也不是把旧内容原样搬到新阶段。","sourceBlockIds":["block:politics-toc-v2-u026:b004","block:politics-toc-v2-u026:b005","block:politics-toc-v2-u026:b006","block:politics-toc-v2-u026:b007","block:politics-toc-v2-u026:b011"],"emphasis":[{"part":"text","quote":"自我否定","occurrence":1,"role":"key"},{"part":"text","quote":"既克服又保留","occurrence":1,"role":"key"}],"kind":"explanation","id":"DIALECTICS-06-body-1"},{"label":"道路曲折与方向前进共同看","text":"否定之否定规律揭示发展的方向和道路，发展表现为螺旋式上升、波浪式前进，是前进性和曲折性的统一。暂时倒退不能直接否认总体趋势，承认曲折也不等于任何反复都自然代表进步。判断仍要结合事物发展的具体内容。","sourceBlockIds":["block:politics-toc-v2-u026:b002","block:politics-toc-v2-u026:b009","block:politics-toc-v2-u026:b010","block:politics-toc-v2-u026:b011","block:politics-toc-v2-u023:b011"],"emphasis":[{"part":"text","quote":"螺旋式上升、波浪式前进","occurrence":1,"role":"key"},{"part":"text","quote":"前进性和曲折性","occurrence":1,"role":"key"}],"kind":"explanation","id":"DIALECTICS-06-body-2"},{"label":"不要把规律变成机械次数","text":"不能用经历两次否定的表面次数替代内部矛盾、克服与保留的具体关系。这里掌握辩证否定的含义，不为任意反复作合理化解释。","sourceBlockIds":["block:politics-toc-v2-u026:b004","block:politics-toc-v2-u026:b007","block:politics-toc-v2-u026:b011"],"emphasis":[],"kind":"boundary","id":"DIALECTICS-06-boundary"},{"label":"本主题小结","text":"辩证否定说明克服与保留，否定之否定说明前进性与曲折性的统一；至此，本主题从联系、矛盾、量变质变和否定之否定理解发展。","sourceBlockIds":["block:politics-toc-v2-u023:b002","block:politics-toc-v2-u024:b002","block:politics-toc-v2-u025:b002","block:politics-toc-v2-u026:b002","block:politics-toc-v2-u026:b007","block:politics-toc-v2-u026:b010"],"emphasis":[],"kind":"recap","id":"DIALECTICS-06-recap"}]},{"title":"实践与认识怎样相互作用","question":"实践是认识来源，是否要求一切认识都亲身实践？","objectives":["理解实践的决定作用与认识的反作用"],"scopeLimit":"本节只解释“实践是认识来源，是否要求一切认识都亲身实践”；不替代完整认识论课程。","reflection":{"prompt":"实践是认识来源，是否要求一切认识都亲身实践？","answer":"不要求每个人对所有知识都亲身实践。认识可以包含间接经验，但这些经验归根到底仍来源于社会实践，并要在实践中接受检验。","sourceBlockIds":["block:politics-toc-v2-u027:b012","block:politics-toc-v2-u027:b013","block:politics-toc-v2-u027:b014","block:politics-toc-v2-u027:b015","block:politics-toc-v2-u027:b016","block:politics-toc-v2-u028:b002"]},"id":"COGNITION-01","groupId":"cognition","previousLessonId":null,"nextLessonId":"COGNITION-02","transition":"下一节：认识为什么要完成两次飞跃","corePromises":[{"quote":"客观物质活动","sourceBlockIds":["block:politics-toc-v2-u027:b003","block:politics-toc-v2-u027:b004","block:politics-toc-v2-u027:b005","block:politics-toc-v2-u027:b006","block:politics-toc-v2-u027:b008","block:politics-toc-v2-u027:b009"]},{"quote":"能动反映","sourceBlockIds":["block:politics-toc-v2-u027:b003","block:politics-toc-v2-u027:b004","block:politics-toc-v2-u027:b005","block:politics-toc-v2-u027:b006","block:politics-toc-v2-u027:b008","block:politics-toc-v2-u027:b009"]},{"quote":"来源","sourceBlockIds":["block:politics-toc-v2-u027:b012","block:politics-toc-v2-u027:b013","block:politics-toc-v2-u027:b014","block:politics-toc-v2-u027:b015","block:politics-toc-v2-u027:b016"]},{"quote":"动力","sourceBlockIds":["block:politics-toc-v2-u027:b012","block:politics-toc-v2-u027:b013","block:politics-toc-v2-u027:b014","block:politics-toc-v2-u027:b015","block:politics-toc-v2-u027:b016"]},{"quote":"目的","sourceBlockIds":["block:politics-toc-v2-u027:b012","block:politics-toc-v2-u027:b013","block:politics-toc-v2-u027:b014","block:politics-toc-v2-u027:b015","block:politics-toc-v2-u027:b016"]},{"quote":"唯一标准","sourceBlockIds":["block:politics-toc-v2-u027:b012","block:politics-toc-v2-u027:b013","block:politics-toc-v2-u027:b014","block:politics-toc-v2-u027:b015","block:politics-toc-v2-u027:b016"]}],"primaryUnitIds":["politics-toc-v2-u027"],"parts":[{"label":"先分清活动与反映","text":"实践是人类能动改造世界的社会性客观物质活动，具有直接现实性、自觉能动性、社会历史性，形式包括物质生产、社会政治、科学文化实践，物质生产最基本。认识是主体在实践基础上对客体的能动反映，会带有主体因素，但不是可以任意脱离客体的想象。","sourceBlockIds":["block:politics-toc-v2-u027:b003","block:politics-toc-v2-u027:b004","block:politics-toc-v2-u027:b005","block:politics-toc-v2-u027:b006","block:politics-toc-v2-u027:b008","block:politics-toc-v2-u027:b009"],"emphasis":[{"part":"text","quote":"客观物质活动","occurrence":1,"role":"key"},{"part":"text","quote":"能动反映","occurrence":1,"role":"key"}],"kind":"explanation","id":"COGNITION-01-body-1"},{"label":"来源 动力 目的与标准","text":"实践是认识的来源、发展的动力、目的，以及检验真理的唯一标准。四个定位分别说明从哪里来、怎样发展、用于什么和怎样检验。认识又反作用于实践，正确认识促进实践，错误认识可能阻碍甚至导致失败，二者不能只保留一个方向。","sourceBlockIds":["block:politics-toc-v2-u027:b012","block:politics-toc-v2-u027:b013","block:politics-toc-v2-u027:b014","block:politics-toc-v2-u027:b015","block:politics-toc-v2-u027:b016"],"emphasis":[{"part":"text","quote":"来源","occurrence":1,"role":"key"},{"part":"text","quote":"动力","occurrence":1,"role":"key"},{"part":"text","quote":"目的","occurrence":1,"role":"key"},{"part":"text","quote":"唯一标准","occurrence":1,"role":"key"}],"kind":"explanation","id":"COGNITION-01-body-2"},{"label":"来源不等于每人都需亲历","text":"实践是认识来源，不等于每个人的一切认识都必须来自亲身实践；实践是检验真理的唯一标准，也不等于逻辑证明毫无作用。必要关系不应变成排斥其他认识途径的口号。","sourceBlockIds":["block:politics-toc-v2-u027:b023"],"emphasis":[],"kind":"boundary","id":"COGNITION-01-boundary"},{"label":"本节结论","text":"实践是认识的来源、动力、目的和检验标准，认识又反作用于实践，二者构成相互联系的过程。","sourceBlockIds":["block:politics-toc-v2-u027:b012","block:politics-toc-v2-u027:b013","block:politics-toc-v2-u027:b014","block:politics-toc-v2-u027:b015","block:politics-toc-v2-u027:b016","block:politics-toc-v2-u028:b002"],"emphasis":[],"kind":"recap","id":"COGNITION-01-recap"}]},{"title":"认识为什么要完成两次飞跃","question":"从感性认识到理性认识之后为什么还没有结束？","objectives":["理解感性理性及返回实践的关系"],"scopeLimit":"本节只解释“从感性认识到理性认识之后为什么还没有结束”；不替代完整认识论课程。","reflection":{"prompt":"团队由访谈记录形成解释，再试行服务方案并依效果修正。试行这一步主要体现什么？","answer":"主要体现从理性认识到实践的第二次飞跃。要定位所问阶段，不能把整个调查过程都归为感性认识。","sourceBlockIds":["block:politics-toc-v2-u027:b015","block:politics-toc-v2-u028:b002","block:politics-toc-v2-u028:b005","block:politics-toc-v2-u028:b006","block:politics-toc-v2-u029:b002","block:politics-toc-v2-u029:b004","block:politics-toc-v2-u029:b007"]},"id":"COGNITION-02","groupId":"cognition","previousLessonId":"COGNITION-01","nextLessonId":"COGNITION-03","transition":"下一节：真理的客观性与条件性怎样统一","corePromises":[{"quote":"感觉、知觉、表象","sourceBlockIds":["block:politics-toc-v2-u028:b003","block:politics-toc-v2-u028:b004","block:politics-toc-v2-u028:b005","block:politics-toc-v2-u028:b006"]},{"quote":"概念、判断、推理","sourceBlockIds":["block:politics-toc-v2-u028:b003","block:politics-toc-v2-u028:b004","block:politics-toc-v2-u028:b005","block:politics-toc-v2-u028:b006"]},{"quote":"第一次飞跃","sourceBlockIds":["block:politics-toc-v2-u028:b002","block:politics-toc-v2-u028:b006","block:politics-toc-v2-u027:b015"]},{"quote":"第二次飞跃","sourceBlockIds":["block:politics-toc-v2-u028:b002","block:politics-toc-v2-u028:b006","block:politics-toc-v2-u027:b015"]},{"quote":"接受检验","sourceBlockIds":["block:politics-toc-v2-u028:b002","block:politics-toc-v2-u028:b006","block:politics-toc-v2-u027:b015"]}],"primaryUnitIds":["politics-toc-v2-u028"],"parts":[{"label":"第一次飞跃不只是多记材料","text":"感性认识是初级阶段，包括感觉、知觉、表象；理性认识是高级阶段，包括概念、判断、推理。理性认识依赖感性认识，感性认识需要发展和深化为理性认识，两者相互渗透、相互包含，因此不是彼此隔绝的两种来源。","sourceBlockIds":["block:politics-toc-v2-u028:b003","block:politics-toc-v2-u028:b004","block:politics-toc-v2-u028:b005","block:politics-toc-v2-u028:b006"],"emphasis":[{"part":"text","quote":"感觉、知觉、表象","occurrence":1,"role":"key"},{"part":"text","quote":"概念、判断、推理","occurrence":1,"role":"key"}],"kind":"explanation","id":"COGNITION-02-body-1"},{"label":"第二次飞跃回到实践","text":"认识过程在实践基础上，由感性到理性完成第一次飞跃，再由理性认识到实践完成第二次飞跃。第二次更重要、更有意义，理性认识需要回到实践接受检验。用概念组织材料之后还要看实践，不能把形成一个解释当成已经完成检验。","sourceBlockIds":["block:politics-toc-v2-u028:b002","block:politics-toc-v2-u028:b006","block:politics-toc-v2-u027:b015"],"emphasis":[{"part":"text","quote":"第一次飞跃","occurrence":1,"role":"key"},{"part":"text","quote":"第二次飞跃","occurrence":1,"role":"key"},{"part":"text","quote":"接受检验","occurrence":1,"role":"key"}],"kind":"explanation","id":"COGNITION-02-body-2"},{"label":"材料怎样用","text":"先定位题目问哪一步：观察资料形成概念判断，主要是第一次飞跃；把形成的方案投入实际行动并检验，主要是第二次飞跃。增加理论论据不能替代实际检验。","sourceBlockIds":["block:politics-toc-v2-u028:b003","block:politics-toc-v2-u028:b004","block:politics-toc-v2-u028:b005","block:politics-toc-v2-u028:b006","block:politics-toc-v2-u028:b002","block:politics-toc-v2-u027:b015"],"kind":"explanation","id":"COGNITION-02-body-3"},{"label":"高级阶段不取消感性基础","text":"理性认识依赖感性认识，不能因为理性处于高级阶段便抛弃感性材料；感性认识也不能停留原状而不作深化。两次飞跃同样不等于只走一次就永远结束。","sourceBlockIds":["block:politics-toc-v2-u028:b002","block:politics-toc-v2-u028:b005","block:politics-toc-v2-u028:b006"],"emphasis":[],"kind":"boundary","id":"COGNITION-02-boundary"},{"label":"本节结论","text":"认识从实践出发，由感性认识上升为理性认识，再回到实践，使认识过程同时具有基础、深化和检验。","sourceBlockIds":["block:politics-toc-v2-u027:b015","block:politics-toc-v2-u028:b002","block:politics-toc-v2-u028:b005","block:politics-toc-v2-u028:b006","block:politics-toc-v2-u029:b002","block:politics-toc-v2-u029:b004","block:politics-toc-v2-u029:b007"],"emphasis":[],"kind":"recap","id":"COGNITION-02-recap"}]},{"title":"真理的客观性与条件性怎样统一","question":"真理有条件性，是否意味着可以任意改变？","objectives":["理解真理绝对性相对性而不相互取消"],"scopeLimit":"本节只解释“真理有条件性，是否意味着可以任意改变”；不替代完整认识论课程。","reflection":{"prompt":"真理有条件性，是否意味着可以任意改变？","answer":"不意味着可以任意改变。真理的客观性要求内容符合客观对象，条件性说明真理有适用范围；条件变化要依据新的客观实际判断。","sourceBlockIds":["block:politics-toc-v2-u027:b012","block:politics-toc-v2-u027:b015","block:politics-toc-v2-u028:b002","block:politics-toc-v2-u029:b002","block:politics-toc-v2-u029:b004","block:politics-toc-v2-u029:b008"]},"id":"COGNITION-03","groupId":"cognition","previousLessonId":"COGNITION-02","nextLessonId":null,"transition":"下一主题：社会与历史","corePromises":[{"quote":"主观与客观相符合","sourceBlockIds":["block:politics-toc-v2-u029:b002","block:politics-toc-v2-u029:b004","block:politics-toc-v2-u027:b015"]},{"quote":"实践检验","sourceBlockIds":["block:politics-toc-v2-u029:b002","block:politics-toc-v2-u029:b004","block:politics-toc-v2-u027:b015"]},{"quote":"绝对性","sourceBlockIds":["block:politics-toc-v2-u029:b005","block:politics-toc-v2-u029:b006","block:politics-toc-v2-u029:b007","block:politics-toc-v2-u029:b008"]},{"quote":"相对性","sourceBlockIds":["block:politics-toc-v2-u029:b005","block:politics-toc-v2-u029:b006","block:politics-toc-v2-u029:b007","block:politics-toc-v2-u029:b008"]},{"quote":"同一客观真理","sourceBlockIds":["block:politics-toc-v2-u029:b005","block:politics-toc-v2-u029:b006","block:politics-toc-v2-u029:b007","block:politics-toc-v2-u029:b008"]}],"primaryUnitIds":["politics-toc-v2-u029"],"parts":[{"label":"真理不只是一种确信","text":"真理是主观与客观相符合，是对客观事物及其规律的正确认识。客观性指其内容和实践检验标准是客观的；不能仅凭确信的人数或强度，把某种主观判断直接当成真理。","sourceBlockIds":["block:politics-toc-v2-u029:b002","block:politics-toc-v2-u029:b004","block:politics-toc-v2-u027:b015"],"emphasis":[{"part":"text","quote":"主观与客观相符合","occurrence":1,"role":"key"},{"part":"text","quote":"实践检验","occurrence":1,"role":"key"}],"kind":"explanation","id":"COGNITION-03-body-1"},{"label":"同一真理的两种属性","text":"绝对性说明真理正确反映客观事物及其规律，人的认识能够正确认识无限发展的客观世界；相对性说明一定条件下认识有限度、不完善。二者是同一客观真理的两种属性，不是两个彼此分离的真理。条件性不取消正确反映，也不能用绝对性否认认识仍可发展。","sourceBlockIds":["block:politics-toc-v2-u029:b005","block:politics-toc-v2-u029:b006","block:politics-toc-v2-u029:b007","block:politics-toc-v2-u029:b008"],"emphasis":[{"part":"text","quote":"绝对性","occurrence":1,"role":"key"},{"part":"text","quote":"相对性","occurrence":1,"role":"key"},{"part":"text","quote":"同一客观真理","occurrence":1,"role":"key"}],"kind":"explanation","id":"COGNITION-03-body-2"},{"label":"客观内容不排除主观形式","text":"真理内容不以人的意志为转移，不等于表现形式没有主观性；有条件性更不等于可以任意改变。仍须回到客观对象与实践检验。","sourceBlockIds":["block:politics-toc-v2-u029:b009","block:politics-toc-v2-u027:b015"],"emphasis":[],"kind":"boundary","id":"COGNITION-03-boundary"},{"label":"本主题小结","text":"本主题用实践解释认识的来源与检验，用两次飞跃解释认识深化，再以客观性及绝对相对统一理解真理。三部分合起来构成有边界的认识过程。","sourceBlockIds":["block:politics-toc-v2-u027:b012","block:politics-toc-v2-u027:b015","block:politics-toc-v2-u028:b002","block:politics-toc-v2-u029:b002","block:politics-toc-v2-u029:b004","block:politics-toc-v2-u029:b008"],"emphasis":[],"kind":"recap","id":"COGNITION-03-recap"}]},{"title":"社会意识为什么既受决定又有独立性","question":"社会意识有相对独立性，是否否定社会存在的决定作用？","objectives":["理解社会存在决定作用与意识反作用"],"scopeLimit":"本节只解释“社会意识有相对独立性，是否否定社会存在的决定作用”；详细学派分类保留查阅。","reflection":{"prompt":"社会意识有相对独立性，是否否定社会存在的决定作用？","answer":"不否定。社会存在决定社会意识，社会意识又有自身发展特点并能反作用于社会存在；相对独立性建立在决定作用仍然成立的基础上。","sourceBlockIds":["block:politics-toc-v2-u030:b005","block:politics-toc-v2-u030:b010","block:politics-toc-v2-u030:b011","block:politics-toc-v2-u030:b012","block:politics-toc-v2-u031:b002"]},"id":"HISTORY-01","groupId":"history","previousLessonId":null,"nextLessonId":"HISTORY-02","transition":"下一节：生产力与生产关系怎样相互作用","corePromises":[{"quote":"物质生产方式","sourceBlockIds":["block:politics-toc-v2-u030:b002","block:politics-toc-v2-u030:b003","block:politics-toc-v2-u030:b005","block:politics-toc-v2-u030:b006"]},{"quote":"社会存在决定社会意识","sourceBlockIds":["block:politics-toc-v2-u030:b002","block:politics-toc-v2-u030:b003","block:politics-toc-v2-u030:b005","block:politics-toc-v2-u030:b006"]},{"quote":"相对独立性","sourceBlockIds":["block:politics-toc-v2-u030:b011","block:politics-toc-v2-u030:b012","block:politics-toc-v2-u030:b013"]},{"quote":"不完全同步","sourceBlockIds":["block:politics-toc-v2-u030:b011","block:politics-toc-v2-u030:b012","block:politics-toc-v2-u030:b013"]}],"primaryUnitIds":["politics-toc-v2-u030"],"parts":[{"label":"先说明社会生活两个方面","text":"社会存在是社会生活的物质方面，包括自然地理环境、人口、物质生产方式，物质生产方式是基础和决定力量。社会意识是精神方面。唯物史观认为社会存在决定社会意识，唯心史观认为社会意识决定社会存在，这构成社会历史观的基本分歧。","sourceBlockIds":["block:politics-toc-v2-u030:b002","block:politics-toc-v2-u030:b003","block:politics-toc-v2-u030:b005","block:politics-toc-v2-u030:b006"],"emphasis":[{"part":"text","quote":"物质生产方式","occurrence":1,"role":"key"},{"part":"text","quote":"社会存在决定社会意识","occurrence":1,"role":"key"}],"kind":"explanation","id":"HISTORY-01-body-1"},{"label":"决定并不等于完全同步","text":"社会意识反作用于社会存在，先进正确意识促进发展，落后错误意识阻碍发展。相对独立性表现为变化不完全同步、不平衡，内部形式相互影响与历史继承，以及能动反作用。正因为不完全同步，不能从一时落后或超前就否定社会存在的决定作用。","sourceBlockIds":["block:politics-toc-v2-u030:b011","block:politics-toc-v2-u030:b012","block:politics-toc-v2-u030:b013"],"emphasis":[{"part":"text","quote":"相对独立性","occurrence":1,"role":"key"},{"part":"text","quote":"不完全同步","occurrence":1,"role":"key"}],"kind":"explanation","id":"HISTORY-01-body-2"},{"label":"反作用仍通过社会实践","text":"先进意识的促进作用要通过社会实践实现。意识形态与非意识形态的具体范围可查阅，本次不把所有精神现象都归为同一种经济基础反映。","sourceBlockIds":["block:politics-toc-v2-u030:b007","block:politics-toc-v2-u030:b008","block:politics-toc-v2-u030:b013"],"emphasis":[],"kind":"boundary","id":"HISTORY-01-boundary"},{"label":"本节结论","text":"物质生产方式是社会存在发展的基础，社会存在决定社会意识，社会意识具有相对独立性并反作用于社会存在。","sourceBlockIds":["block:politics-toc-v2-u030:b005","block:politics-toc-v2-u030:b010","block:politics-toc-v2-u030:b011","block:politics-toc-v2-u030:b012","block:politics-toc-v2-u031:b002"],"emphasis":[],"kind":"recap","id":"HISTORY-01-recap"}]},{"title":"生产力与生产关系怎样相互作用","question":"为什么生产关系不是生产工具的另一种名称？","objectives":["分清人与自然和人与人的生产关系"],"scopeLimit":"本节只解释“为什么生产关系不是生产工具的另一种名称”；详细学派分类保留查阅。","reflection":{"prompt":"新技术提高生产能力后，组织调整生产协作和分配使其发挥效用。怎样区分两类变化？","answer":"技术和生产能力变化属于生产力，生产协作和分配调整属于生产关系，并体现生产关系对生产力的反作用。","sourceBlockIds":["block:politics-toc-v2-u031:b004","block:politics-toc-v2-u031:b008","block:politics-toc-v2-u031:b010","block:politics-toc-v2-u031:b012","block:politics-toc-v2-u031:b018"]},"id":"HISTORY-02","groupId":"history","previousLessonId":"HISTORY-01","nextLessonId":"HISTORY-03","transition":"下一节：经济基础与上层建筑怎样连接","corePromises":[{"quote":"劳动者、劳动资料、劳动对象","sourceBlockIds":["block:politics-toc-v2-u031:b004","block:politics-toc-v2-u031:b005","block:politics-toc-v2-u031:b006","block:politics-toc-v2-u031:b007"]},{"quote":"生产工具","sourceBlockIds":["block:politics-toc-v2-u031:b004","block:politics-toc-v2-u031:b005","block:politics-toc-v2-u031:b006","block:politics-toc-v2-u031:b007"]},{"quote":"人与人的关系","sourceBlockIds":["block:politics-toc-v2-u031:b008","block:politics-toc-v2-u031:b009","block:politics-toc-v2-u031:b010"]},{"quote":"所有制形式","sourceBlockIds":["block:politics-toc-v2-u031:b008","block:politics-toc-v2-u031:b009","block:politics-toc-v2-u031:b010"]},{"quote":"生产力决定生产关系","sourceBlockIds":["block:politics-toc-v2-u031:b008","block:politics-toc-v2-u031:b009","block:politics-toc-v2-u031:b010"]}],"primaryUnitIds":["politics-toc-v2-u031"],"parts":[{"label":"生产力说明物质力量","text":"生产力是物质生产中改造影响自然、使其适合需要的物质力量，表现人与自然的关系。基本要素是劳动者、劳动资料、劳动对象，劳动者起主导作用，生产工具是劳动资料主要内容，也是生产力发展水平的客观标志；科学技术也是重要因素。","sourceBlockIds":["block:politics-toc-v2-u031:b004","block:politics-toc-v2-u031:b005","block:politics-toc-v2-u031:b006","block:politics-toc-v2-u031:b007"],"emphasis":[{"part":"text","quote":"劳动者、劳动资料、劳动对象","occurrence":1,"role":"key"},{"part":"text","quote":"生产工具","occurrence":1,"role":"key"}],"kind":"explanation","id":"HISTORY-02-body-1"},{"label":"生产关系说明经济关系","text":"生产关系是物质生产中形成的不以人的意志为转移的经济关系，表现人与人的关系，包括所有制形式、生产中的地位和相互关系、产品分配形式。所有制形式是基础。生产力决定生产关系，生产关系能动反作用，二者矛盾运动推动社会生产发展。","sourceBlockIds":["block:politics-toc-v2-u031:b008","block:politics-toc-v2-u031:b009","block:politics-toc-v2-u031:b010"],"emphasis":[{"part":"text","quote":"人与人的关系","occurrence":1,"role":"key"},{"part":"text","quote":"所有制形式","occurrence":1,"role":"key"},{"part":"text","quote":"生产力决定生产关系","occurrence":1,"role":"key"}],"kind":"explanation","id":"HISTORY-02-body-2"},{"label":"材料怎样用","text":"先按对象分类：技术、劳动者和工具等属于生产力；所有制、生产协作和分配等属于生产关系。再判断决定与反作用，不把促进作用直接等同决定作用。","sourceBlockIds":["block:politics-toc-v2-u031:b004","block:politics-toc-v2-u031:b005","block:politics-toc-v2-u031:b006","block:politics-toc-v2-u031:b007","block:politics-toc-v2-u031:b008","block:politics-toc-v2-u031:b009","block:politics-toc-v2-u031:b010"],"kind":"explanation","id":"HISTORY-02-body-3"},{"label":"适合不是越超前越好","text":"生产关系须适合生产力状况，不是静止不变，也不是越超前越好。不能因为生产关系有反作用，就把决定关系反过来。","sourceBlockIds":["block:politics-toc-v2-u031:b010","block:politics-toc-v2-u031:b020"],"emphasis":[],"kind":"boundary","id":"HISTORY-02-boundary"},{"label":"本节结论","text":"生产力说明生产中的物质力量，生产关系说明生产中人与人的经济关系，二者之间既有决定作用也有反作用。","sourceBlockIds":["block:politics-toc-v2-u031:b004","block:politics-toc-v2-u031:b008","block:politics-toc-v2-u031:b010","block:politics-toc-v2-u031:b012","block:politics-toc-v2-u031:b018"],"emphasis":[],"kind":"recap","id":"HISTORY-02-recap"}]},{"title":"经济基础与上层建筑怎样连接","question":"经济基础、生产力与上层建筑为什么不能混成一层？","objectives":["理解两对社会基本矛盾的层次和联系"],"scopeLimit":"本节只解释“经济基础、生产力与上层建筑为什么不能混成一层”；详细学派分类保留查阅。","reflection":{"prompt":"经济基础、生产力与上层建筑为什么不能混成一层？","answer":"生产力与生产关系构成一对矛盾，生产关系的总和构成经济基础，政治法律制度及相应社会意识形态属于上层建筑，三者处在不同层次。","sourceBlockIds":["block:politics-toc-v2-u031:b002","block:politics-toc-v2-u031:b010","block:politics-toc-v2-u031:b018","block:politics-toc-v2-u031:b019","block:politics-toc-v2-u032:b004"]},"id":"HISTORY-03","groupId":"history","previousLessonId":"HISTORY-02","nextLessonId":"HISTORY-04","transition":"下一节：人民群众怎样创造历史","corePromises":[{"quote":"生产关系总和","sourceBlockIds":["block:politics-toc-v2-u031:b012","block:politics-toc-v2-u031:b013","block:politics-toc-v2-u031:b014","block:politics-toc-v2-u031:b015","block:politics-toc-v2-u031:b016","block:politics-toc-v2-u031:b017"]},{"quote":"国家政权是核心","sourceBlockIds":["block:politics-toc-v2-u031:b012","block:politics-toc-v2-u031:b013","block:politics-toc-v2-u031:b014","block:politics-toc-v2-u031:b015","block:politics-toc-v2-u031:b016","block:politics-toc-v2-u031:b017"]},{"quote":"经济基础决定上层建筑","sourceBlockIds":["block:politics-toc-v2-u031:b002","block:politics-toc-v2-u031:b018","block:politics-toc-v2-u031:b019"]},{"quote":"生产力与生产关系","sourceBlockIds":["block:politics-toc-v2-u031:b002","block:politics-toc-v2-u031:b018","block:politics-toc-v2-u031:b019"]},{"quote":"根本动力","sourceBlockIds":["block:politics-toc-v2-u031:b002","block:politics-toc-v2-u031:b018","block:politics-toc-v2-u031:b019"]}],"primaryUnitIds":["politics-toc-v2-u031"],"parts":[{"label":"先分清基础与建筑","text":"经济基础是一定发展阶段生产力决定的生产关系总和，所有制有决定意义。上层建筑是建立在经济基础上的意识形态以及相应制度、组织、设施，包括观念与政治两部分；政治上层建筑居主导地位，国家政权是核心。经济基础不能直接换成机器、资金等日常“基础设施”说法。","sourceBlockIds":["block:politics-toc-v2-u031:b012","block:politics-toc-v2-u031:b013","block:politics-toc-v2-u031:b014","block:politics-toc-v2-u031:b015","block:politics-toc-v2-u031:b016","block:politics-toc-v2-u031:b017"],"emphasis":[{"part":"text","quote":"生产关系总和","occurrence":1,"role":"key"},{"part":"text","quote":"国家政权是核心","occurrence":1,"role":"key"}],"kind":"explanation","id":"HISTORY-03-body-1"},{"label":"两对矛盾怎样相接","text":"经济基础决定上层建筑，上层建筑反作用于经济基础，其矛盾运动推动社会生产发展。社会基本矛盾还包括生产力与生产关系的矛盾，后者更根本，同时其解决也依赖经济基础与上层建筑矛盾的解决。两对关系共同构成社会历史发展的根本动力。","sourceBlockIds":["block:politics-toc-v2-u031:b002","block:politics-toc-v2-u031:b018","block:politics-toc-v2-u031:b019"],"emphasis":[{"part":"text","quote":"经济基础决定上层建筑","occurrence":1,"role":"key"},{"part":"text","quote":"生产力与生产关系","occurrence":1,"role":"key"},{"part":"text","quote":"根本动力","occurrence":1,"role":"key"}],"kind":"explanation","id":"HISTORY-03-body-2"},{"label":"有反作用不等于决定关系反转","text":"上层建筑须适合经济基础，适合不等于静止或越超前越好。两对基本矛盾相互联系，不是把四个名词串成单向、无条件的机械链条。","sourceBlockIds":["block:politics-toc-v2-u031:b018","block:politics-toc-v2-u031:b019","block:politics-toc-v2-u031:b020"],"emphasis":[],"kind":"boundary","id":"HISTORY-03-boundary"},{"label":"本节结论","text":"生产力与生产关系、经济基础与上层建筑分别具有决定与反作用，两对社会基本矛盾又相互联系。","sourceBlockIds":["block:politics-toc-v2-u031:b002","block:politics-toc-v2-u031:b010","block:politics-toc-v2-u031:b018","block:politics-toc-v2-u031:b019","block:politics-toc-v2-u032:b004"],"emphasis":[],"kind":"recap","id":"HISTORY-03-recap"}]},{"title":"人民群众怎样创造历史","question":"承认人民群众决定作用是否否认杰出人物？","objectives":["理解群众决定作用与个人作用的边界"],"scopeLimit":"本节只解释“承认人民群众决定作用是否否认杰出人物”；详细学派分类保留查阅。","reflection":{"prompt":"承认人民群众决定作用是否否认杰出人物？","answer":"不否认。人民群众是历史创造的决定力量，杰出人物能够在一定条件下发挥重要作用，但其作用受社会历史条件和群众实践制约。","sourceBlockIds":["block:politics-toc-v2-u030:b002","block:politics-toc-v2-u030:b005","block:politics-toc-v2-u031:b002","block:politics-toc-v2-u032:b004","block:politics-toc-v2-u032:b005","block:politics-toc-v2-u032:b006"]},"id":"HISTORY-04","groupId":"history","previousLessonId":"HISTORY-03","nextLessonId":null,"transition":"下一主题：商品 劳动与价值量","corePromises":[{"quote":"群众史观","sourceBlockIds":["block:politics-toc-v2-u032:b002","block:politics-toc-v2-u032:b003"]},{"quote":"决定作用","sourceBlockIds":["block:politics-toc-v2-u032:b002","block:politics-toc-v2-u032:b003"]},{"quote":"物质财富","sourceBlockIds":["block:politics-toc-v2-u032:b004","block:politics-toc-v2-u032:b005"]},{"quote":"精神财富","sourceBlockIds":["block:politics-toc-v2-u032:b004","block:politics-toc-v2-u032:b005"]},{"quote":"社会变革","sourceBlockIds":["block:politics-toc-v2-u032:b004","block:politics-toc-v2-u032:b005"]}],"primaryUnitIds":["politics-toc-v2-u032"],"parts":[{"label":"先看历史观的分歧","text":"英雄史观把历史发展归因于少数统治者或社会精英；群众史观认为人民群众对历史发展起决定作用，同时承认个人特别是历史人物的作用。区别不在是否承认个人存在，而在如何理解历史发展的决定力量。","sourceBlockIds":["block:politics-toc-v2-u032:b002","block:politics-toc-v2-u032:b003"],"emphasis":[{"part":"text","quote":"群众史观","occurrence":1,"role":"key"},{"part":"text","quote":"决定作用","occurrence":1,"role":"key"}],"kind":"explanation","id":"HISTORY-04-body-1"},{"label":"创造作用有三个方面","text":"人民群众是社会历史主体、历史创造者，是物质财富创造者、精神财富创造者、社会变革决定力量。把三个方面一起理解，才不会把群众作用缩成只生产物质产品；精神与社会变革也在创造历史的范围之中。","sourceBlockIds":["block:politics-toc-v2-u032:b004","block:politics-toc-v2-u032:b005"],"emphasis":[{"part":"text","quote":"物质财富","occurrence":1,"role":"key"},{"part":"text","quote":"精神财富","occurrence":1,"role":"key"},{"part":"text","quote":"社会变革","occurrence":1,"role":"key"}],"kind":"explanation","id":"HISTORY-04-body-2"},{"label":"肯定群众不抹去个人作用","text":"杰出人物有重要作用，但受社会历史条件和人民群众实践制约。不能从承认群众决定作用推出个人无用，也不能从个人重要性推出少数人独自创造历史。","sourceBlockIds":["block:politics-toc-v2-u032:b006"],"emphasis":[],"kind":"boundary","id":"HISTORY-04-boundary"},{"label":"本主题小结","text":"本主题从社会存在与社会意识、两对社会基本矛盾和人民群众三个层次，分别理解社会结构、发展动力和历史主体。","sourceBlockIds":["block:politics-toc-v2-u030:b002","block:politics-toc-v2-u030:b005","block:politics-toc-v2-u031:b002","block:politics-toc-v2-u032:b004","block:politics-toc-v2-u032:b005","block:politics-toc-v2-u032:b006"],"emphasis":[],"kind":"recap","id":"HISTORY-04-recap"}]},{"title":"货币怎样表现价值并参与流通","question":"价值尺度为什么可以是观念货币，流通手段却要求现实货币？","objectives":["理解一般等价物及两项基本职能"],"scopeLimit":"本节只解释“价值尺度为什么可以是观念货币，流通手段却要求现实货币”；主题内其他职能留到相应小节。","reflection":{"prompt":"价值尺度为什么可以是观念货币，流通手段却要求现实货币？","answer":"价值尺度用于表现和衡量商品价值，可以由观念货币承担；流通手段要在商品交换中实际充当媒介，因此需要现实货币。","sourceBlockIds":["block:politics-toc-v2-u036:b002","block:politics-toc-v2-u036:b003","block:politics-toc-v2-u036:b004","block:politics-toc-v2-u036:b005","block:politics-toc-v2-u036:b007"]},"id":"MONEY-01","groupId":"money","previousLessonId":null,"nextLessonId":"MONEY-02","transition":"下一节：贮藏 支付与世界货币怎样区分","corePromises":[{"quote":"一般等价物","sourceBlockIds":["block:politics-toc-v2-u036:b002","block:politics-toc-v2-u033:b002","block:politics-toc-v2-u033:b003"]},{"quote":"价值尺度","sourceBlockIds":["block:politics-toc-v2-u036:b004","block:politics-toc-v2-u036:b005","block:politics-toc-v2-u036:b006","block:politics-toc-v2-u036:b007","block:politics-toc-v2-u036:b008","block:politics-toc-v2-u036:b014"]},{"quote":"流通手段","sourceBlockIds":["block:politics-toc-v2-u036:b004","block:politics-toc-v2-u036:b005","block:politics-toc-v2-u036:b006","block:politics-toc-v2-u036:b007","block:politics-toc-v2-u036:b008","block:politics-toc-v2-u036:b014"]},{"quote":"观念货币","sourceBlockIds":["block:politics-toc-v2-u036:b004","block:politics-toc-v2-u036:b005","block:politics-toc-v2-u036:b006","block:politics-toc-v2-u036:b007","block:politics-toc-v2-u036:b008","block:politics-toc-v2-u036:b014"]},{"quote":"现实货币","sourceBlockIds":["block:politics-toc-v2-u036:b004","block:politics-toc-v2-u036:b005","block:politics-toc-v2-u036:b006","block:politics-toc-v2-u036:b007","block:politics-toc-v2-u036:b008","block:politics-toc-v2-u036:b014"]}],"primaryUnitIds":["politics-toc-v2-u036"],"parts":[{"label":"从商品价值读到货币","text":"前面的商品、劳动与价值量说明商品怎样理解其价值。货币是固定充当一般等价物的商品，本质是一般等价物；这里先抓住它在交换中的一般等价物地位，不把货币本质直接换成任何一种具体职能。","sourceBlockIds":["block:politics-toc-v2-u036:b002","block:politics-toc-v2-u033:b002","block:politics-toc-v2-u033:b003"],"emphasis":[{"part":"text","quote":"一般等价物","occurrence":1,"role":"key"}],"kind":"explanation","id":"MONEY-01-body-1"},{"label":"两个最基本职能条件不同","text":"价值尺度和流通手段是两个最基本职能。价值尺度表现其他商品的价值、衡量价值量，可以只需要观念货币；流通手段在商品流通中充当交换媒介，需要现实货币。前者在表现衡量，后者在实际流通媒介作用，不能只看是否出现一个货币数字。","sourceBlockIds":["block:politics-toc-v2-u036:b004","block:politics-toc-v2-u036:b005","block:politics-toc-v2-u036:b006","block:politics-toc-v2-u036:b007","block:politics-toc-v2-u036:b008","block:politics-toc-v2-u036:b014"],"emphasis":[{"part":"text","quote":"价值尺度","occurrence":1,"role":"key"},{"part":"text","quote":"流通手段","occurrence":1,"role":"key"},{"part":"text","quote":"观念货币","occurrence":1,"role":"key"},{"part":"text","quote":"现实货币","occurrence":1,"role":"key"}],"kind":"explanation","id":"MONEY-01-body-2"},{"label":"本质与职能分开再联系","text":"一般等价物是货币本质，两项基本职能说明具体作用。这里没有讲货币起源的完整历史，也不把所有货币作用都压成交换媒介。","sourceBlockIds":["block:politics-toc-v2-u036:b002","block:politics-toc-v2-u036:b003","block:politics-toc-v2-u036:b004"],"emphasis":[],"kind":"boundary","id":"MONEY-01-boundary"},{"label":"本节结论","text":"货币的本质是一般等价物，价值尺度用于表现价值，流通手段充当商品交换媒介，二者的作用和条件不同。","sourceBlockIds":["block:politics-toc-v2-u036:b002","block:politics-toc-v2-u036:b003","block:politics-toc-v2-u036:b004","block:politics-toc-v2-u036:b005","block:politics-toc-v2-u036:b007"],"emphasis":[],"kind":"recap","id":"MONEY-01-recap"}]},{"title":"贮藏 支付与世界货币怎样区分","question":"为什么不能把所有付款都直接称为流通手段？","objectives":["认识五种货币职能的完整范围与条件"],"scopeLimit":"本节只解释“为什么不能把所有付款都直接称为流通手段”；主题内其他职能留到相应小节。","reflection":{"prompt":"为什么不能把所有付款都直接称为流通手段？","answer":"因为流通手段是在商品交换中充当媒介，支付手段则用于赊购赊销、清偿债务以及租金、税金、工资等支付关系；具体条件不同。","sourceBlockIds":["block:politics-toc-v2-u036:b002","block:politics-toc-v2-u036:b003","block:politics-toc-v2-u036:b005","block:politics-toc-v2-u036:b007","block:politics-toc-v2-u036:b009","block:politics-toc-v2-u036:b011","block:politics-toc-v2-u036:b013"]},"id":"MONEY-02","groupId":"money","previousLessonId":"MONEY-01","nextLessonId":null,"transition":"下一主题：剩余价值：定义与条件","corePromises":[{"quote":"贮藏手段","sourceBlockIds":["block:politics-toc-v2-u036:b009","block:politics-toc-v2-u036:b010","block:politics-toc-v2-u036:b011","block:politics-toc-v2-u036:b012","block:politics-toc-v2-u036:b014"]},{"quote":"支付手段","sourceBlockIds":["block:politics-toc-v2-u036:b009","block:politics-toc-v2-u036:b010","block:politics-toc-v2-u036:b011","block:politics-toc-v2-u036:b012","block:politics-toc-v2-u036:b014"]},{"quote":"世界货币","sourceBlockIds":["block:politics-toc-v2-u036:b003","block:politics-toc-v2-u036:b004","block:politics-toc-v2-u036:b005","block:politics-toc-v2-u036:b007","block:politics-toc-v2-u036:b009","block:politics-toc-v2-u036:b011","block:politics-toc-v2-u036:b013"]},{"quote":"五种职能","sourceBlockIds":["block:politics-toc-v2-u036:b003","block:politics-toc-v2-u036:b004","block:politics-toc-v2-u036:b005","block:politics-toc-v2-u036:b007","block:politics-toc-v2-u036:b009","block:politics-toc-v2-u036:b011","block:politics-toc-v2-u036:b013"]}],"primaryUnitIds":["politics-toc-v2-u036"],"parts":[{"label":"退出流通与延期支付","text":"贮藏手段指货币退出流通、作为社会财富一般代表保存起来，本节按金属货币理论口径，以足值金属货币或金属条块说明条件。支付手段则涉及赊购赊销、清偿债务，也用于租金、税金、工资等。前者强调退出流通保存，后者强调相应支付关系，不是同一种作用。","sourceBlockIds":["block:politics-toc-v2-u036:b009","block:politics-toc-v2-u036:b010","block:politics-toc-v2-u036:b011","block:politics-toc-v2-u036:b012","block:politics-toc-v2-u036:b014"],"emphasis":[{"part":"text","quote":"贮藏手段","occurrence":1,"role":"key"},{"part":"text","quote":"支付手段","occurrence":1,"role":"key"}],"kind":"explanation","id":"MONEY-02-body-1"},{"label":"国际流通中的作用","text":"世界货币是在国际商品流通中发挥一般等价物作用。连同上一小节的价值尺度、流通手段，再加贮藏、支付，形成五种职能。完整理解时既看作用，也看观念或现实、流通或保存、具体支付关系等条件。","sourceBlockIds":["block:politics-toc-v2-u036:b003","block:politics-toc-v2-u036:b004","block:politics-toc-v2-u036:b005","block:politics-toc-v2-u036:b007","block:politics-toc-v2-u036:b009","block:politics-toc-v2-u036:b011","block:politics-toc-v2-u036:b013"],"emphasis":[{"part":"text","quote":"世界货币","occurrence":1,"role":"key"},{"part":"text","quote":"五种职能","occurrence":1,"role":"key"}],"kind":"explanation","id":"MONEY-02-body-2"},{"label":"贮藏条件与其他职能分别看","text":"本节的贮藏条件限定在金属货币理论口径，不泛化为现代信用货币的普遍结论。区分流通、贮藏与支付，须看作用和具体关系，不能只看钱被保存或出现付款动作。","sourceBlockIds":["block:politics-toc-v2-u036:b009","block:politics-toc-v2-u036:b010","block:politics-toc-v2-u036:b014"],"emphasis":[],"kind":"boundary","id":"MONEY-02-boundary"},{"label":"本主题小结","text":"货币本质是一般等价物，五种职能分别说明价值衡量、流通媒介、保存、支付和国际流通作用，需根据具体作用与条件区分。","sourceBlockIds":["block:politics-toc-v2-u036:b002","block:politics-toc-v2-u036:b003","block:politics-toc-v2-u036:b005","block:politics-toc-v2-u036:b007","block:politics-toc-v2-u036:b009","block:politics-toc-v2-u036:b011","block:politics-toc-v2-u036:b013"],"emphasis":[],"kind":"recap","id":"MONEY-02-recap"}]},{"title":"两种剩余价值方法的条件怎样比较","question":"绝对与相对剩余价值分别保留哪个时间条件？","objectives":["认识定义与两种方法的变与不变"],"scopeLimit":"本节只解释“绝对与相对剩余价值分别保留哪个时间条件”；劳动力价值前置不足，完整产生机制待补源。","reflection":{"prompt":"绝对与相对剩余价值分别保留哪个时间条件？","answer":"绝对剩余价值生产保持必要劳动时间不变并延长劳动日；相对剩余价值生产保持工作日长度不变，通过提高社会劳动生产率缩短必要劳动时间。完整产生机制仍待补源。","sourceBlockIds":["block:politics-toc-v2-u037:b004","block:politics-toc-v2-u037:b005","block:politics-toc-v2-u037:b014"]},"id":"CAPITAL-01","groupId":"capital","previousLessonId":null,"nextLessonId":"CAPITAL-02","transition":"下一节：资本分类为什么看剩余价值中的作用","corePromises":[{"quote":"超过劳动力价值","sourceBlockIds":["block:politics-toc-v2-u037:b002"]},{"quote":"完整产生机制","sourceBlockIds":["block:politics-toc-v2-u037:b002"]},{"quote":"必要劳动时间不变","sourceBlockIds":["block:politics-toc-v2-u037:b004","block:politics-toc-v2-u037:b005","block:politics-toc-v2-u037:b014"]},{"quote":"工作日长度不变","sourceBlockIds":["block:politics-toc-v2-u037:b004","block:politics-toc-v2-u037:b005","block:politics-toc-v2-u037:b014"]},{"quote":"全社会劳动生产率","sourceBlockIds":["block:politics-toc-v2-u037:b004","block:politics-toc-v2-u037:b005","block:politics-toc-v2-u037:b014"]}],"primaryUnitIds":["politics-toc-v2-u037"],"parts":[{"label":"先明确这里的有限目标","text":"剩余价值是雇佣工人创造、被资本家无偿占有、超过劳动力价值的那部分价值，体现相应生产关系。本主题只认识这一正式定义和已有方法条件，尚不展开劳动力价值如何形成；不能把读到定义当作已经解释了完整产生机制。","sourceBlockIds":["block:politics-toc-v2-u037:b002"],"emphasis":[{"part":"text","quote":"超过劳动力价值","occurrence":1,"role":"key"},{"part":"text","quote":"完整产生机制","occurrence":1,"role":"key"}],"kind":"explanation","id":"CAPITAL-01-body-1"},{"label":"比较劳动日与必要劳动时间","text":"绝对剩余价值生产是在必要劳动时间不变时延长劳动日；相对剩余价值生产是在工作日长度不变时缩短必要劳动时间、相应延长剩余劳动时间，缩短通过全社会劳动生产率提高实现。先分清哪一段时间不变、哪一段变化，不把企业个别效率提高直接等同这一社会条件。","sourceBlockIds":["block:politics-toc-v2-u037:b004","block:politics-toc-v2-u037:b005","block:politics-toc-v2-u037:b014"],"emphasis":[{"part":"text","quote":"必要劳动时间不变","occurrence":1,"role":"key"},{"part":"text","quote":"工作日长度不变","occurrence":1,"role":"key"},{"part":"text","quote":"全社会劳动生产率","occurrence":1,"role":"key"}],"kind":"explanation","id":"CAPITAL-01-body-2"},{"label":"前置不足不靠记名词补齐","text":"现有材料未充分解释劳动力价值及必要劳动时间之间的完整机制，本次目标因此限缩为定义识别与条件比较。剩余价值产生于生产而非流通过程，不是简单把商品卖贵就完成解释。","sourceBlockIds":["block:politics-toc-v2-u037:b002","block:politics-toc-v2-u037:b004","block:politics-toc-v2-u037:b005","block:politics-toc-v2-u037:b014"],"emphasis":[],"kind":"boundary","id":"CAPITAL-01-boundary"},{"label":"本节结论","text":"绝对方法保持必要劳动时间不变、延长劳动日；相对方法保持工作日不变、通过社会劳动生产率提高缩短必要劳动时间。本次比较条件即可，完整机制仍待补源。","sourceBlockIds":["block:politics-toc-v2-u037:b004","block:politics-toc-v2-u037:b005","block:politics-toc-v2-u037:b014"],"emphasis":[],"kind":"recap","id":"CAPITAL-01-recap"}]},{"title":"资本分类为什么看剩余价值中的作用","question":"不变资本和可变资本的划分与技术比例是一回事吗？","objectives":["区分不变可变资本与资本构成的不同维度"],"scopeLimit":"本节只解释“不变资本和可变资本的划分与技术比例是一回事吗”；劳动力价值前置不足，完整产生机制待补源。","reflection":{"prompt":"不变资本和可变资本的划分与技术比例是一回事吗？","answer":"不是。不变资本和可变资本按它们在剩余价值生产中的不同作用划分，技术构成则表示生产资料与劳动力的比例，划分依据不同。","sourceBlockIds":["block:politics-toc-v2-u037:b004","block:politics-toc-v2-u037:b005","block:politics-toc-v2-u037:b006","block:politics-toc-v2-u037:b008","block:politics-toc-v2-u037:b009","block:politics-toc-v2-u037:b011","block:politics-toc-v2-u037:b012","block:politics-toc-v2-u037:b013"]},"id":"CAPITAL-02","groupId":"capital","previousLessonId":"CAPITAL-01","nextLessonId":null,"transition":"本篇收束：把七个主题放回基本原理篇","corePromises":[{"quote":"不变资本C","sourceBlockIds":["block:politics-toc-v2-u037:b006","block:politics-toc-v2-u037:b007","block:politics-toc-v2-u037:b008","block:politics-toc-v2-u037:b009"]},{"quote":"可变资本V","sourceBlockIds":["block:politics-toc-v2-u037:b006","block:politics-toc-v2-u037:b007","block:politics-toc-v2-u037:b008","block:politics-toc-v2-u037:b009"]},{"quote":"不同作用","sourceBlockIds":["block:politics-toc-v2-u037:b006","block:politics-toc-v2-u037:b007","block:politics-toc-v2-u037:b008","block:politics-toc-v2-u037:b009"]},{"quote":"技术构成","sourceBlockIds":["block:politics-toc-v2-u037:b010","block:politics-toc-v2-u037:b011","block:politics-toc-v2-u037:b012","block:politics-toc-v2-u037:b013"]},{"quote":"价值构成","sourceBlockIds":["block:politics-toc-v2-u037:b010","block:politics-toc-v2-u037:b011","block:politics-toc-v2-u037:b012","block:politics-toc-v2-u037:b013"]},{"quote":"有机构成","sourceBlockIds":["block:politics-toc-v2-u037:b010","block:politics-toc-v2-u037:b011","block:politics-toc-v2-u037:b012","block:politics-toc-v2-u037:b013"]},{"quote":"C:V","sourceBlockIds":["block:politics-toc-v2-u037:b010","block:politics-toc-v2-u037:b011","block:politics-toc-v2-u037:b012","block:politics-toc-v2-u037:b013"]}],"primaryUnitIds":["politics-toc-v2-u037"],"parts":[{"label":"不变可变按作用划分","text":"资本以生产资料和劳动力形态存在，按在剩余价值生产中的不同作用分为不变资本C与可变资本V。不变资本以生产资料形式存在，物质形态改变但自身价值量不增殖；可变资本以劳动力价值形式存在，其价值由工人劳动再生产出来。划分依据是作用，不只是形态名称。","sourceBlockIds":["block:politics-toc-v2-u037:b006","block:politics-toc-v2-u037:b007","block:politics-toc-v2-u037:b008","block:politics-toc-v2-u037:b009"],"emphasis":[{"part":"text","quote":"不变资本C","occurrence":1,"role":"key"},{"part":"text","quote":"可变资本V","occurrence":1,"role":"key"},{"part":"text","quote":"不同作用","occurrence":1,"role":"key"}],"kind":"explanation","id":"CAPITAL-02-body-1"},{"label":"构成有技术与价值两个角度","text":"技术构成指生产资料与劳动力之间的比例，价值构成指不变资本与可变资本价值之间的比例。有机构成是由技术构成决定并反映其变化的价值构成，即C:V。技术与价值不是两个可以随意互换的计量对象，理解有机构成需要保留这层关系。","sourceBlockIds":["block:politics-toc-v2-u037:b010","block:politics-toc-v2-u037:b011","block:politics-toc-v2-u037:b012","block:politics-toc-v2-u037:b013"],"emphasis":[{"part":"text","quote":"技术构成","occurrence":1,"role":"key"},{"part":"text","quote":"价值构成","occurrence":1,"role":"key"},{"part":"text","quote":"有机构成","occurrence":1,"role":"key"},{"part":"text","quote":"C:V","occurrence":1,"role":"key"}],"kind":"explanation","id":"CAPITAL-02-body-2"},{"label":"范围不扩大为完整经济学","text":"本主题只解释已有分类与定义联系，不推导原文没有给出的公式和完整劳动力价值机制。前置缺口仍在，不能因两小节结束而宣称剩余价值理论已经全面学完。","sourceBlockIds":["block:politics-toc-v2-u037:b002","block:politics-toc-v2-u037:b006","block:politics-toc-v2-u037:b010","block:politics-toc-v2-u037:b013"],"emphasis":[],"kind":"boundary","id":"CAPITAL-02-boundary"},{"label":"本主题小结","text":"本主题先比较绝对与相对剩余价值的时间条件，再按剩余价值生产中的作用区分不变资本与可变资本，并辨认技术构成、价值构成和有机构成的关系。","sourceBlockIds":["block:politics-toc-v2-u037:b004","block:politics-toc-v2-u037:b005","block:politics-toc-v2-u037:b006","block:politics-toc-v2-u037:b008","block:politics-toc-v2-u037:b009","block:politics-toc-v2-u037:b011","block:politics-toc-v2-u037:b012","block:politics-toc-v2-u037:b013"],"emphasis":[],"kind":"recap","id":"CAPITAL-02-recap"}]}]};
